// Global fetch interceptor — CSRF, 401 redirect, 402 credits modal
let _csrfToken = sessionStorage.getItem("tf_csrf") || "";

const originalFetch = window.fetch;
window.fetch = async function (...args) {
  let [url, opts = {}] = args;
  if (typeof url === "string" && url.startsWith("/api/")) {
    const headers = { ...(opts.headers || {}) };

    // Inject CSRF if not GET
    if (opts.method && opts.method !== "GET") {
      headers["X-CSRF-Token"] = _csrfToken;
    }

    // Inject custom AI headers if stored in localStorage
    const provider = localStorage.getItem("ai_provider");
    const apiKey = localStorage.getItem("ai_api_key");
    const model = localStorage.getItem("ai_model");

    if (provider) {
      headers["X-AI-Provider"] = provider;
      if (apiKey) headers["X-AI-Key"] = apiKey;
      if (model) headers["X-AI-Model"] = model;
    }

    opts = { ...opts, headers };
  }
  const response = await originalFetch(url, opts);
  if (response.status === 401) {
    window.location.href = "/login.html";
    return response;
  }
  if (response.status === 402) {
    try {
      const data = await response.clone().json();
      showCreditsModal(data);
    } catch { /* ignore */ }
  }
  return response;
};

async function showCreditsModal(data) {
  const el = $("creditsModal");
  const reqEl = $("creditsReqValue");
  const balEl = $("creditsBalValue");
  if (!el) {
    if (await showConfirm((data?.error || "Insufficient credits") + "\n\nGo to pricing page?")) {
      window.location.href = "/pricing.html";
    }
    return;
  }
  const req = data?.required ?? 1;
  const bal = data?.balance ?? 0;
  if (reqEl) {
    reqEl.textContent = req === 1 ? "1 credit" : `${req} credits`;
  }
  if (balEl) {
    balEl.textContent = bal === 1 ? "1 credit" : `${bal} credits`;
  }
  el.classList.remove("hidden");
}

function closeCreditsModal() {
  $("creditsModal")?.classList.add("hidden");
}

const ALERT_DAYS = 10;
const EXPECTED_API_VERSION = 6;

function storageKey(key) {
  const uid = (typeof state !== "undefined" && state && state.username) ? state.username : 'guest';
  const cleanKey = key.startsWith("tf_") ? key.substring(3) : key;
  return `tf_${uid}_${cleanKey}`;
}

// ── Stale-while-revalidate ──────────────────────────────────────────────────────────────────────
// Supplier / Buyer Intelligence show the last result they had for the same query immediately, then
// replace it when fresh data arrives. Cached per user in localStorage; every access is guarded
// because storage can be full, blocked, or disabled (private windows).
const SWR_MAX_AGE_MS = 24 * 3600 * 1000;

function swrRead(key) {
  try {
    const raw = localStorage.getItem(storageKey(`swr_${key}`));
    if (!raw) return null;
    const entry = JSON.parse(raw);
    if (!entry || !entry.data || Date.now() - entry.at > SWR_MAX_AGE_MS) return null;
    return entry.data;
  } catch { return null; }
}

function swrWrite(key, data) {
  try {
    localStorage.setItem(storageKey(`swr_${key}`), JSON.stringify({ at: Date.now(), data }));
  } catch { /* full or blocked: the cache is an optimisation, never required */ }
}

function swrClearPrefix(prefix) {
  try {
    const fullPrefix = storageKey(`swr_${prefix}`);
    const toRemove = [];
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && k.startsWith(fullPrefix)) toRemove.push(k);
    }
    toRemove.forEach(k => localStorage.removeItem(k));
  } catch { /* ignore */ }
}

// A thin animated bar on a list while newer data is on its way (see .tf-refreshing in theme.css).
function setRefreshing(el, on) {
  if (!el) return;
  el.classList.toggle("tf-refreshing", Boolean(on));
  if (on) el.setAttribute("aria-busy", "true"); else el.removeAttribute("aria-busy");
}

