// ── Persistence (recent + saved searches, view preference) ────────────────
const LS_RECENT = "tf_recent_searches";
const LS_SAVED = "tf_saved_searches";
const LS_VIEW = "tf_results_view";
const LS_PROFILE = "tf_active_profile";
const LS_THEME = "tf_theme";
const LS_SEARCH_COLLAPSED = "tf_search_collapsed";
const LS_FILTERS_COLLAPSED = "tf_filters_collapsed";
const LS_SIDEBAR_COLLAPSED = "tf_sidebar_collapsed";
const LS_PORTAL = "tf_selected_portals";
const LS_MANAGED_COUNTRIES = "tf_managed_countries";
const LS_UK_COUNTIES = "tf_selected_uk_counties";
const LS_HIDE_UNSTATED_LOCATION = "tf_hide_unstated_location";
const LS_STATUS_FILTER = "tf_status_filter";
const LS_FOCUS_MODE = "tf_focus_mode";
const LS_KEYWORD_SCOPE = "tf_keyword_scope";

const LEGACY_KEYS = [
  'tf_active_profile', 'tf_recent_searches', 'tf_saved_searches',
  'tf_selected_portals', 'tf_search_collapsed', 'tf_filters_collapsed',
  'tf_sidebar_collapsed', 'tf_results_view', 'tf_lang', 'tf_theme'
];
LEGACY_KEYS.forEach(k => {
  try {
    localStorage.removeItem(k);
  } catch (e) { }
});

function lsGet(key, fallback) {
  try {
    const raw = localStorage.getItem(storageKey(key));
    return raw !== null ? JSON.parse(raw) : fallback;
  } catch {
    return fallback;
  }
}

function lsSet(key, value) {
  try {
    localStorage.setItem(storageKey(key), JSON.stringify(value));
  } catch {
    /* storage unavailable — ignore */
  }
}

function syncStatusFilterUI() {
  const chkOpp = $("chkOpportunities");
  const chkAwarded = $("chkAwarded");

  const cur = state.statusFilter || "opportunities";
  if (chkOpp && chkAwarded) {
    if (cur === "opportunities") {
      chkOpp.checked = true;
      chkAwarded.checked = false;
    } else if (cur === "awards") {
      chkOpp.checked = false;
      chkAwarded.checked = true;
    } else if (cur === "all") {
      chkOpp.checked = true;
      chkAwarded.checked = true;
    } else if (cur === "none") {
      chkOpp.checked = false;
      chkAwarded.checked = false;
    }
  }

  const statusContainer = $("rmStatusPills");
  if (statusContainer) {
    const status = cur === "awards" ? "awarded" : cur;
    statusContainer.querySelectorAll(".rm-pill").forEach(pill => {
      pill.classList.toggle("active", pill.dataset.status === status);
    });
  }
}

const DEFAULT_MANAGED_COUNTRIES = ["United Kingdom"];

// Drops entries that no longer correspond to a real, selectable country (e.g. "Northern Ireland",
// which used to be its own portal country before eTenders NI was folded into "United Kingdom").
// Stale values like this can otherwise linger forever in localStorage/server prefs.
function sanitizeManagedCountries(list) {
  const valid = new Set(getAvailableCountries().map(c => c.name));
  const cleaned = Array.isArray(list) ? list.filter(name => valid.has(name)) : [];
  return cleaned.length > 0 ? cleaned : [...DEFAULT_MANAGED_COUNTRIES];
}

function loadPrefs() {
  const savedCountries = lsGet(LS_MANAGED_COUNTRIES, null);
  const cleanedCountries = sanitizeManagedCountries(savedCountries);
  state.managedCountries = cleanedCountries;
  if (JSON.stringify(cleanedCountries) !== JSON.stringify(savedCountries)) {
    lsSet(LS_MANAGED_COUNTRIES, cleanedCountries);
    savePrefsToServer({ managed_countries: JSON.stringify(cleanedCountries) });
  }

  const savedCounties = lsGet(LS_UK_COUNTIES, null);
  // null means never saved (first load) → default all-selected.
  // An explicit empty array [] means user deselected all → respect that.
  state.selectedUkCounties = savedCounties === null
    ? (typeof UK_COUNTIES !== "undefined" ? UK_COUNTIES.map(c => c.name) : [])
    : (Array.isArray(savedCounties) ? savedCounties : []);

  state.hideLocationNotStated = lsGet(LS_HIDE_UNSTATED_LOCATION, false) === true;
  state.statusFilter = lsGet(LS_STATUS_FILTER, "opportunities");
  syncStatusFilterUI();

  // Restore keyword scope selection (persisted so it survives refresh)
  const savedScope = lsGet(LS_KEYWORD_SCOPE, "all");
  const validScopes = ["all", "title", "supplier", "buyer"];
  state.keywordScope = validScopes.includes(savedScope) ? savedScope : "all";

  const rawRecent = lsGet(LS_RECENT, []);
  // Deduplicate stored recent searches by query text (keep newest per query)
  const seenQ = new Set();
  state.recentSearches = rawRecent.filter(r => {
    const key = (r.q || "").toLowerCase();
    if (seenQ.has(key)) return false;
    seenQ.add(key);
    return true;
  });
  state.savedSearches = lsGet(LS_SAVED, []);
  const hasViewPref = localStorage.getItem(storageKey(LS_VIEW)) !== null;
  const v = lsGet(LS_VIEW, null);
  if (!hasViewPref && window.matchMedia("(max-width: 760px)").matches) {
    state.view = "card";
  } else {
    state.view = v === "card" ? "card" : "table";
  }
  state.activeProfileId = lsGet(LS_PROFILE, "") || "";

  const cachedBalance = lsGet("tf_credit_balance", null);
  if (cachedBalance != null) {
    state.creditBalance = Number(cachedBalance);
  }
  const cachedPlan = lsGet("tf_user_plan", null);
  if (cachedPlan) {
    state.plan = cachedPlan;
  }
  updateCreditDisplay();

  if (typeof loadPortalPrefs === "function") {
    loadPortalPrefs();
  }

  initTheme();
}

function initTheme() {
  const saved = localStorage.getItem(storageKey(LS_THEME));
  const prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
  const theme = saved || (prefersDark ? "dark" : "light");
  document.documentElement.setAttribute("data-theme", theme);
  const label = $("themeLabel");
  if (label) label.textContent = theme === "dark" ? "Light mode" : "Dark mode";
}

function toggleTheme() {
  const current = document.documentElement.getAttribute("data-theme") === "dark" ? "dark" : "light";
  const next = current === "dark" ? "light" : "dark";
  document.documentElement.setAttribute("data-theme", next);
  localStorage.setItem(storageKey(LS_THEME), next);
  const label = $("themeLabel");
  if (label) label.textContent = next === "dark" ? "Light mode" : "Dark mode";
  savePrefsToServer({ theme: next });
}

// Rail collapse: shrinks the sidebar to an icon-only strip (labels hidden, native
// title tooltips take over). Toggled from the button next to "Find work".
const LS_RAIL_COLLAPSED = "tf_rail_collapsed";

function applyRailCollapsed(on) {
  document.body.classList.toggle("tf-rail-collapsed", !!on);
  const btn = $("btnRailCollapse");
  if (btn) {
    btn.setAttribute("aria-pressed", on ? "true" : "false");
    btn.title = on ? "Expand sidebar" : "Collapse sidebar to icons";
  }
}

function toggleRailCollapsed() {
  const isOn = document.body.classList.contains("tf-rail-collapsed");
  const next = !isOn;
  applyRailCollapsed(next);
  try { localStorage.setItem(LS_RAIL_COLLAPSED, next ? "1" : "0"); } catch (e) {}
}

(function initRailCollapsed() {
  let saved = "0";
  try { saved = localStorage.getItem(LS_RAIL_COLLAPSED) || "0"; } catch (e) {}
  applyRailCollapsed(saved === "1");
  $("btnRailCollapse")?.addEventListener("click", toggleRailCollapsed);
})();

// ── Server-side preference sync (cross-browser) ───────────────────────────
// Debounced: batches rapid changes (e.g. portal picks) into one request
let _prefsSaveTimer = null;
let _pendingPrefs = {};

function flushPendingPrefs() {
  if (!state.username || Object.keys(_pendingPrefs).length === 0) return;
  const csrf = _csrfToken || sessionStorage.getItem("tf_csrf") || "";
  const toSend = { ..._pendingPrefs };
  _pendingPrefs = {};
  if (_prefsSaveTimer) {
    clearTimeout(_prefsSaveTimer);
    _prefsSaveTimer = null;
  }
  try {
    const payload = JSON.stringify({ prefs: toSend, csrf_token: csrf });
    const headers = { "Content-Type": "application/json" };
    if (csrf) headers["X-CSRF-Token"] = csrf;
    fetch("/api/user-prefs", {
      method: "POST",
      headers,
      body: payload,
      keepalive: true
    }).catch(() => {/* non-critical */ });
  } catch (e) {}
}

if (typeof window !== "undefined") {
  window.addEventListener("beforeunload", flushPendingPrefs);
  window.addEventListener("pagehide", flushPendingPrefs);
}

function savePrefsToServer(prefs, immediate = false) {
  if (!state.username) return; // only when logged in
  
  // Update state.userPrefs immediately with new preferences
  if (!state.userPrefs) state.userPrefs = {};
  Object.assign(state.userPrefs, prefs);
  
  Object.assign(_pendingPrefs, prefs);

  if (immediate) {
    flushPendingPrefs();
    return;
  }

  clearTimeout(_prefsSaveTimer);
  _prefsSaveTimer = setTimeout(() => {
    flushPendingPrefs();
  }, 600);
}

async function loadPrefsFromServer() {
  try {
    const res = await fetch("/api/user-prefs");
    if (!res.ok) return;
    const data = await res.json();
    if (!data.ok || !data.prefs) return;
    const p = data.prefs;

    // Initialize state.userPrefs to hold all preferences in memory
    if (!state.userPrefs) state.userPrefs = {};
    state.userPrefs = { ...p };

    // Theme
    if (p.theme) {
      localStorage.setItem(storageKey(LS_THEME), p.theme);
    }
    // Language
    if (p.lang) {
      localStorage.setItem(storageKey("tf_lang"), p.lang);
      state.lang = p.lang;
    }
    // View mode
    if (p.view) {
      localStorage.setItem(storageKey(LS_VIEW), JSON.stringify(p.view));
    }
    // Panel states
    if (p.sidebar_collapsed !== undefined) {
      localStorage.setItem(storageKey(LS_SIDEBAR_COLLAPSED), p.sidebar_collapsed);
    }
    if (p.search_collapsed !== undefined) {
      localStorage.setItem(storageKey(LS_SEARCH_COLLAPSED), p.search_collapsed);
    }
    if (p.filters_collapsed !== undefined) {
      localStorage.setItem(storageKey(LS_FILTERS_COLLAPSED), p.filters_collapsed);
    }
    // Portal selections
    if (p.selected_portals !== undefined) {
      try {
        const parsed = p.selected_portals === "null" ? null : JSON.parse(p.selected_portals);
        localStorage.setItem(storageKey(LS_PORTAL), JSON.stringify(parsed));
      } catch { /* ignore parse error */ }
    }
    // Managed countries
    if (p.managed_countries !== undefined) {
      try {
        const parsed = typeof p.managed_countries === "string"
          ? JSON.parse(p.managed_countries)
          : p.managed_countries;
        state.managedCountries = sanitizeManagedCountries(parsed);
        localStorage.setItem(storageKey(LS_MANAGED_COUNTRIES), JSON.stringify(state.managedCountries));
        if (JSON.stringify(state.managedCountries) !== JSON.stringify(parsed)) {
          savePrefsToServer({ managed_countries: JSON.stringify(state.managedCountries) });
        }
      } catch { /* ignore parse error */ }
    }
    // Status filter
    if (p.status_filter !== undefined) {
      localStorage.setItem(storageKey(LS_STATUS_FILTER), JSON.stringify(p.status_filter));
      state.statusFilter = p.status_filter;
      syncStatusFilterUI();
    }
    // Active profile
    if (p.active_profile !== undefined) {
      localStorage.setItem(storageKey(LS_PROFILE), JSON.stringify(p.active_profile));
    }
    // Bid Step Checks & Selected Documents from server
    if (p.tf_bid_step_checks !== undefined && p.tf_bid_step_checks !== null) {
      try {
        localStorage.setItem(storageKey("tf_bid_step_checks"), p.tf_bid_step_checks);
      } catch {}
    }
    for (const key in p) {
      if (key.startsWith("bid_doc_ids_") || key.startsWith("bid_selected_doc_ids_")) {
        try {
          if (p[key] !== undefined && p[key] !== null) {
            localStorage.setItem(storageKey(key), p[key]);
          }
        } catch {}
      }
    }
  } catch {/* ignore */ }
}

function updateAivDashboardUrl(username) {
  const user = username || state?.username || state?.email || "Admin";
  const btn = document.getElementById("btnAivDashboard");
  const iframe = document.getElementById("aivDashboardFrame");

  const currentHref = btn?.getAttribute("href") || iframe?.getAttribute("src") ||
    "https://aiv.test.oneaiv.com:8086/aiv/embed/external/5068476a6870253242536a73706d676f7a6976496c4462427467567675463870706b71356e6a6755545a377267253344/a_u__Admin&a_p__&a_t__eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiJBZG1pbjo6RGVmYXVsdCIsImlhdCI6MTc4MTUyNzA1NH0.MegE9u4WF9VJkSl9h6w-NTP9jEanXlDgOMOqyWcKOvI&a_d__Default&a_af__false/noparam";

  const newUrl = currentHref.replace(/a_u__[^&]+/, "a_u__" + encodeURIComponent(user));

  if (btn) btn.href = newUrl;
  if (iframe && iframe.src !== newUrl) iframe.src = newUrl;
}

document.addEventListener("DOMContentLoaded", () => {
  const btn = document.getElementById("btnAivDashboard");
  if (btn) {
    btn.addEventListener("click", () => updateAivDashboardUrl());
    btn.addEventListener("mouseenter", () => updateAivDashboardUrl());
  }
});

async function loadCurrentUser() {
  try {
    const res = await fetch("/api/me");
    if (!res.ok) return;
    const data = await res.json();
    state.username = data.username || "";
    state.email = data.email || "";

    // Update AIV dashboard link with logged-in user's username
    updateAivDashboardUrl(state.username || state.email);

    // Now that username is known, reload all preferences from user-scoped keys.
    // 1) Pull from server first — writes authoritative values into localStorage
    //    so portals/theme/lang/view/panels sync across browsers.
    await loadPrefsFromServer();

    // 2) Read lang (may have been updated by server) and load local prefs
    state.lang = localStorage.getItem(storageKey("tf_lang")) || "en";
    loadPrefs();
    loadPanelPrefs();
    if (typeof loadBidStepCheckStates === "function") {
      loadBidStepCheckStates();
    }

    // Re-render portal picker now that we have the correct user-scoped prefs
    loadPortalPrefs();
    reconcilePortalCatalogue();
    renderCountryBadges();
    renderManageCountriesList("");
    renderPortalsInCountries();
    syncNativeScope();

    // Sync scope dropdown label and hint with restored/default scope
    if (typeof updateScopeLabelAndHint === "function") {
      updateScopeLabelAndHint(state.keywordScope || "all");
      const s1 = $("keywordScopeSelect");
      if (s1) s1.value = state.keywordScope || "all";
      const s2 = $("rmKeywordScopeSelect");
      if (s2) s2.value = state.keywordScope || "all";
    }

    // Re-apply restored activeProfileId to the dropdown in case loadCompanyProfiles()
    // already ran and populated it before we knew the user (race condition fix)
    if (typeof populateFitProfileSelect === "function") populateFitProfileSelect();

    // Fetch saved + recent searches from server (authoritative across browsers)
    // Must run AFTER state.username is set so lsSet writes to correct scoped key
    await Promise.all([loadServerSavedSearches(), loadServerRecentSearches()]);

    // Theme & Language (applied after server prefs are loaded)
    initTheme();
    loadSavedProfileColor();
    setLanguage(state.lang);

    // UI components
    renderSearchChips();
    updateViewToggle();


    state.creditBalance = data.balance ?? state.creditBalance;
    state.plan = data.plan || state.plan || "free";
    if (state.creditBalance != null) {
      lsSet("tf_credit_balance", state.creditBalance);
    }
    if (state.plan) {
      lsSet("tf_user_plan", state.plan);
    }
    state.lowCredit = !!data.low_credit;
    state.role = data.role || "member";
    state.isAdmin = !!data.is_admin;
    if (data.csrf_token) {
      _csrfToken = data.csrf_token;
      sessionStorage.setItem("tf_csrf", _csrfToken);
    }

    // Update initials in topbar avatar button
    const initialsSpan = $("navProfileInitials");
    if (initialsSpan) {
      const nameToUse = state.username || state.email;
      if (nameToUse) {
        initialsSpan.textContent = nameToUse.trim().charAt(0).toUpperCase();
      } else {
        initialsSpan.innerHTML = '<span class="topbar-skeleton topbar-skeleton--avatar"></span>';
      }
    }

    // Update detailed profile dropdown header
    const dropdownName = $("dropdownProfileName");
    const dropdownEmail = $("dropdownProfileEmail");
    const dropdownPlan = $("dropdownProfilePlan");
    if (dropdownName) {
      dropdownName.textContent = state.username || state.email || "User";
    }
    if (dropdownEmail) {
      dropdownEmail.textContent = state.email || "";
    }
    if (dropdownPlan) {
      const plan = (state.plan || "free").toLowerCase();
      dropdownPlan.className = "topbar-dropdown__profile-badge";
      dropdownPlan.onclick = null;
      if (plan === "advance" || plan === "teams" || plan === "business" || plan === "premium" || plan === "enterprise") {
        dropdownPlan.innerHTML = "★ Teams";
        dropdownPlan.classList.add("topbar-dropdown__profile-badge--business");
      } else if (plan === "standard" || plan === "solo") {
        dropdownPlan.innerHTML = "★ Solo";
        dropdownPlan.classList.add("topbar-dropdown__profile-badge--pro");
      } else {
        // Free plan: this used to fall into the Solo branch above and mislabel free users as
        // paying subscribers. Show an upgrade CTA instead of a (wrong) plan name.
        dropdownPlan.innerHTML = "⚡ Upgrade to paid plan";
        dropdownPlan.classList.add("topbar-dropdown__profile-badge--upgrade");
        dropdownPlan.onclick = () => {
          $("profileDropdownWrap")?.classList.remove("topbar-dropdown--open");
          $("btnProfileDropdown")?.setAttribute("aria-expanded", "false");
          openPricingModal();
        };
      }
    }

    updateCreditDisplay();
    if (state.lowCredit && state.creditBalance != null) {
      const dismissed = sessionStorage.getItem("tf_low_credit_dismissed");
      if (!dismissed) $("lowCreditBanner")?.classList.remove("hidden");
    }

    if (typeof window.maybeTriggerWalkthroughForUser === "function") {
      window.maybeTriggerWalkthroughForUser(state.username || state.email);
    }
  } catch {/* ignore */ }
}

function updatePlanBadge() {
  const badge = $("headerPlanBadge");
  if (!badge) return;
  const plan = (state.plan || "free").toLowerCase();
  badge.className = "plan-badge";
  if (plan === "advance" || plan === "teams" || plan === "business" || plan === "premium" || plan === "enterprise") {
    badge.textContent = "TEAMS";
    badge.classList.add("plan-badge--business");
  } else if (plan === "standard" || plan === "solo") {
    badge.textContent = "SOLO";
    badge.classList.add("plan-badge--pro");
  } else {
    badge.textContent = "FREE";
    badge.classList.add("plan-badge--free");
  }
}

function updateCreditDisplay() {
  const el = $("creditBalance");
  const btn = $("btnCredits");
  if (!el) return;
  if (state.creditBalance == null) {
    el.innerHTML = '<span class="topbar-skeleton topbar-skeleton--credits"></span>';
    if (btn) btn.classList.add("topbar-btn--loading");
    return;
  }
  el.textContent = state.creditBalance.toLocaleString();
  el.classList.toggle("credit-balance--low", state.lowCredit);
  if (btn) {
    btn.classList.remove("topbar-btn--loading");
    // Icon-only by default; the balance slides out on hover (see .topbar-btn__credits-label in styles.css).
    btn.title = `${state.creditBalance.toLocaleString()} credits · Plan: ${state.plan} — click to buy credits`;
  }
  updatePlanBadge();
}

async function refreshCredits() {
  try {
    const res = await fetch("/api/me");
    if (!res.ok) return;
    const data = await res.json();
    state.creditBalance = data.balance ?? state.creditBalance;
    state.lowCredit = !!data.low_credit;
    state.plan = data.plan || state.plan;
    updateCreditDisplay();
  } catch {/* ignore */ }
}

function updateFilterSidebarSummary() {
  const el = $("filterExplanation");
  if (!el) return;
  const parts = [];

  // Keywords
  const q = (state.q || $("q")?.value || "").trim();
  if (q) {
    parts.push(`"${q}"`);
  }

  // Portal Scope
  const scope = (typeof buildPickerLabel === "function" ? buildPickerLabel() : null)
    || $("scope")?.selectedOptions?.[0]?.text || state.scope || "All";
  if (scope && scope !== "All portals" && scope !== "All") {
    parts.push(scope);
  }

  // Filters
  if (state.statusFilter && state.statusFilter !== "all") {
    parts.push(t("pill_" + state.statusFilter) || state.statusFilter);
  }
  if (state.dateFilterActive && state.dateFilterPreset !== "all") {
    parts.push(state.dateFilterPreset === "custom" ? t("custom_dates") : `${state.dateFilterPreset}d`);
  }
  if (state.sourceFilter && state.sourceFilter !== "all") parts.push(state.sourceFilter);
  if (state.valueMin != null || state.valueMax != null) parts.push(t("value_range") || "Value");
  if (state.fitMin != null) parts.push(`fit ≥${state.fitMin}`);
  if (state.activeProfileId) {
    const activeProfile = typeof getActiveProfile === "function" ? getActiveProfile() : null;
    parts.push(activeProfile ? activeProfile.name : (t("profile_fit") || "Profile"));
  }

  el.textContent = parts.length ? parts.join(" · ") : (t("filter_exp_all") || "Showing all tenders");
  if (typeof updateRightmoveResultsCount === "function") updateRightmoveResultsCount();
}

function updateSearchPanelSummary() {
  updateFilterSidebarSummary();
}

function updateFiltersPanelSummary() {
  updateFilterSidebarSummary();
}

let _activePopoverId = null;

function restoreSidebarSections() {
  const sidebarBody = document.querySelector(".filter-sidebar__body");
  if (!sidebarBody) return;

  // Use the sentinel anchor as the insertion reference point.
  // Each section is inserted immediately after the previous, maintaining
  // the exact original order: Keywords → Countries → Portals → County → Fit → Date → Source → Value → SaveSearch
  // This ensures the Search footer button (in .filter-sidebar__footer, a sibling of this body div)
  // always remains at the bottom and is never affected.
  const anchor = document.getElementById("sidebarSectionsAnchor") || sidebarBody.firstChild;

  const sectionsInOrder = [
    "fitBar",
    "keywordsSection",
    "fitControls",
    "countriesSection",
    "portalsSection",
    "ukCountyFilterSection",
    "dateFilterRow",
    "valueSection",
    "saveSearchSection"
  ];

  // Insert each section in order right after the anchor (or after the previously inserted section).
  let insertAfter = anchor;
  sectionsInOrder.forEach(id => {
    const el = document.getElementById(id);
    if (el) {
      // insertAfter.nextSibling is the node we insert before, placing el after insertAfter
      const nextNode = insertAfter ? insertAfter.nextSibling : null;
      sidebarBody.insertBefore(el, nextNode);
      insertAfter = el;
    }
  });

  if (typeof updateUkCountyFilterVisibility === "function") {
    updateUkCountyFilterVisibility();
  }
}

function closeFocusPopovers() {
  const popovers = document.querySelectorAll(".focus-popover");
  popovers.forEach(popover => popover.classList.add("hidden"));

  const btns = document.querySelectorAll(".focus-pill-btn");
  btns.forEach(btn => {
    btn.classList.remove("active");
    btn.setAttribute("aria-expanded", "false");
  });

  if (_activePopoverId) {
    restoreSidebarSections();
    _activePopoverId = null;
  }
}

function toggleFocusPopover(popoverId, sectionIds, pillBtnId) {
  const targetPopover = $(popoverId);
  const targetBtn = $(pillBtnId);
  if (!targetPopover || !targetBtn) return;

  const isAlreadyOpen = !targetPopover.classList.contains("hidden");

  closeFocusPopovers();

  if (isAlreadyOpen) {
    return;
  }

  const sectionIdList = Array.isArray(sectionIds) ? sectionIds : [sectionIds];
  sectionIdList.forEach(id => {
    const sec = $(id);
    if (sec) {
      sec.classList.remove("hidden");
      targetPopover.appendChild(sec);
    }
  });

  targetPopover.classList.remove("hidden");
  targetBtn.classList.add("active");
  targetBtn.setAttribute("aria-expanded", "true");
  _activePopoverId = popoverId;
}

function updateFocusPillSummaries() {
  // 1. Countries pill
  const countriesText = $("pillCountriesText");
  if (countriesText) {
    const managed = state.managedCountries || [];
    if (!managed || managed.length === 0) {
      countriesText.textContent = "Countries: All";
    } else {
      const countryNames = managed.map(c => typeof getCountryName === "function" ? getCountryName(c) : c);
      if (countryNames.length <= 2) {
        countriesText.textContent = `Countries: ${countryNames.join(", ")}`;
      } else {
        countriesText.textContent = `Countries: ${countryNames.slice(0, 2).join(", ")} +${countryNames.length - 2}`;
      }
    }
  }

  // 2. County pill
  const countyWrap = $("pillCountyWrap");
  const countyText = $("pillCountyText");
  if (countyWrap) {
    countyWrap.classList.remove("hidden");
  }
  if (countyText) {
    const counties = state.selectedUkCounties || [];
    if (counties.length === 0) {
      countyText.textContent = "+ County";
    } else if (counties.length === 1) {
      countyText.textContent = `County: ${counties[0]}`;
    } else {
      countyText.textContent = `County: ${counties[0]} +${counties.length - 1}`;
    }
  }

  // 3. Profile & Fit pill
  const profileText = $("pillProfileText");
  if (profileText) {
    if (state.activeProfileId) {
      const activeProf = typeof getActiveProfile === "function" ? getActiveProfile() : null;
      profileText.textContent = `Profile: ${activeProf ? activeProf.name : "Selected"}`;
    } else if (state.fitMin != null) {
      profileText.textContent = `Fit: ${state.fitMin === 0 ? "All" : state.fitMin + "+"}`;
    } else {
      profileText.textContent = "Fit: All";
    }
  }

  // 4. Portals pill
  const portalsText = $("pillPortalsText");
  if (portalsText) {
    const portalsListEl = $("portalsList");
    if (portalsListEl) {
      const checkboxes = portalsListEl.querySelectorAll("input[type='checkbox']");
      const checked = portalsListEl.querySelectorAll("input[type='checkbox']:checked");
      if (checkboxes.length > 0) {
        portalsText.textContent = `Portals: ${checked.length}/${checkboxes.length}`;
      } else {
        portalsText.textContent = "Portals: All";
      }
    } else {
      portalsText.textContent = "Portals: All";
    }
  }

  // 5. More filters pill
  const moreText = $("pillMoreText");
  if (moreText) {
    let extraCount = 0;
    const q = (state.q || $("q")?.value || "").trim();
    if (q) extraCount++;
    if (state.statusFilter && state.statusFilter !== "all" && state.statusFilter !== "opportunities") extraCount++;
    if (state.dateFilterActive && state.dateFilterPreset !== "all") extraCount++;
    if (state.sourceFilter && state.sourceFilter !== "all") extraCount++;
    if (state.valueMin != null || state.valueMax != null) extraCount++;

    moreText.textContent = extraCount > 0 ? `+ More filters (${extraCount})` : "+ More filters";
  }
}

function toggleFocusMode(forceState) {
  const nextState = forceState !== undefined ? !!forceState : !state.focusMode;
  state.focusMode = nextState;

  const btnSidebar = $("btnFocusMode");
  const btnTopbar = $("btnFocusModeTopbar");
  const pillBar = $("focusPillBar");
  const sidebar = $("filterSidebar");

  const iconMaximize = `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-1px;"><polyline points="15 3 21 3 21 9"></polyline><polyline points="9 21 3 21 3 15"></polyline><line x1="21" y1="3" x2="14" y2="10"></line><line x1="3" y1="21" x2="10" y2="14"></line></svg>`;
  const iconMinimize = `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-1px;"><polyline points="4 14 10 14 10 20"></polyline><polyline points="20 10 14 10 14 4"></polyline><line x1="14" y1="10" x2="21" y2="3"></line><line x1="10" y1="14" x2="3" y2="21"></line></svg>`;

  if (btnSidebar) {
    btnSidebar.classList.toggle("active", nextState);
    btnSidebar.setAttribute("aria-pressed", nextState ? "true" : "false");
    btnSidebar.setAttribute("title", nextState ? "Close Filter" : "Maximize Filter");
    const svgEl = btnSidebar.querySelector("svg");
    if (svgEl) svgEl.outerHTML = nextState ? iconMinimize : iconMaximize;
  }
  if (btnTopbar) {
    btnTopbar.classList.toggle("active", nextState);
    btnTopbar.setAttribute("aria-pressed", nextState ? "true" : "false");
    btnTopbar.setAttribute("title", nextState ? "Close Filter" : "Maximize Filter");
    const svgEl = btnTopbar.querySelector("svg");
    if (svgEl) svgEl.outerHTML = nextState ? iconMinimize : iconMaximize;
  }

  if (nextState) {
    if (sidebar) sidebar.classList.add("focus-mode-hidden");
    if (pillBar) pillBar.classList.remove("hidden");
    document.body.classList.add("focus-mode-active");
    const rmDrawer = $("rmFilterDrawer");
    const isDrawerExpanded = rmDrawer && !rmDrawer.classList.contains("hidden");
    document.body.classList.toggle("rm-drawer-expanded", isDrawerExpanded);
    if (typeof renderRightmoveFocusFilters === "function") {
      renderRightmoveFocusFilters();
    }
  } else {
    if (sidebar) sidebar.classList.remove("focus-mode-hidden");
    if (pillBar) pillBar.classList.add("hidden");
    document.body.classList.remove("focus-mode-active");
    document.body.classList.remove("rm-drawer-expanded");
  }

  const val = nextState ? "1" : "0";
  if (localStorage.getItem(storageKey(LS_FOCUS_MODE)) !== val) {
    localStorage.setItem(storageKey(LS_FOCUS_MODE), val);
    if (typeof savePrefsToServer === "function") {
      savePrefsToServer({ focus_mode: val });
    }
  }
}

function setSidebarCollapsed(collapsed) {
  const sidebar = $("filterSidebar");
  if (!sidebar) return;
  
  
  sidebar.classList.toggle("sidebar--collapsed", collapsed);
  const btn = $("btnToggleSidebar");
  if (btn) {
    btn.setAttribute("aria-expanded", collapsed ? "false" : "true");
    btn.setAttribute("title", collapsed ? "Expand filters" : "Collapse filters");
  }
  if (!collapsed) {
    if (typeof updateFilterSidebarSummary === "function") {
      updateFilterSidebarSummary();
    }
  }
}

function setPanelCollapsed(panelId, collapsed) {
  setSidebarCollapsed(collapsed);
}

function loadPanelPrefs() {
  // Search filters always use the horizontal filter bar; the vertical sidebar stays hidden.
  toggleFocusMode(true);
  updateFilterSidebarSummary();
}

function initRightmoveFocusFilters() {
  // 1. Drawer expand/collapse toggle button
  const btnToggleDrawer = $("btnToggleRmDrawer");
  const rmDrawer = $("rmFilterDrawer");
  if (btnToggleDrawer && rmDrawer) {
    btnToggleDrawer.addEventListener("click", () => {
      const isHidden = rmDrawer.classList.contains("hidden");
      rmDrawer.classList.toggle("hidden", !isHidden);
      btnToggleDrawer.classList.toggle("active", isHidden);
      btnToggleDrawer.setAttribute("aria-expanded", isHidden ? "true" : "false");
      document.body.classList.toggle("rm-drawer-expanded", isHidden && state.focusMode);
    });
  }

  // 2. Clear button
  $("btnRmClear")?.addEventListener("click", () => {
    resetAllFilters();
  });

  // 3. Done button (collapses expanded drawer panel and displays tender table)
  $("btnRmDone")?.addEventListener("click", () => {
    if (rmDrawer) rmDrawer.classList.add("hidden");
    if (btnToggleDrawer) {
      btnToggleDrawer.classList.remove("active");
      btnToggleDrawer.setAttribute("aria-expanded", "false");
    }
    document.body.classList.remove("rm-drawer-expanded");
  });

  // 4. Search input, Search button & clear icon in quick bar and drawer
  const rmInput = $("rmSearchInput");
  const rmKeywordInput = $("rmSearchKeywordInput");
  const rmClearBtn = $("rmSearchClear");
  const rmSearchBtn = $("btnRmSearchSubmit");

  const handleKeywordChange = (val) => {
    state.q = val;
    if (typeof syncKeywordScopeFromInput === "function") syncKeywordScopeFromInput(val);
    const sidebarQ = $("q");
    if (sidebarQ && sidebarQ.value !== val) sidebarQ.value = val;
    if (rmInput && rmInput.value !== val) rmInput.value = val;
    if (rmKeywordInput && rmKeywordInput.value !== val) rmKeywordInput.value = val;
    if (typeof renderRows === "function") renderRows();
    updateRightmoveResultsCount();
  };

  const triggerSearch = () => {
    if (typeof search === "function") {
      search();
    } else if (typeof loadPage === "function") {
      loadPage(true);
    }
  };

  rmInput?.addEventListener("input", (e) => handleKeywordChange(e.target.value));
  rmInput?.addEventListener("keydown", (e) => {
    if (e.key === "Enter") triggerSearch();
  });
  rmKeywordInput?.addEventListener("input", (e) => handleKeywordChange(e.target.value));
  rmKeywordInput?.addEventListener("keydown", (e) => {
    if (e.key === "Enter") triggerSearch();
  });
  rmSearchBtn?.addEventListener("click", triggerSearch);

  if (rmClearBtn) {
    rmClearBtn.addEventListener("click", () => handleKeywordChange(""));
  }

  // 5. Section headers toggle (collapsible caret ^ / v)
  document.querySelectorAll(".rm-section-header").forEach(header => {
    header.addEventListener("click", () => {
      const targetId = header.dataset.toggle;
      const targetSec = $(targetId);
      if (targetSec) {
        const isHidden = targetSec.classList.contains("hidden");
        targetSec.classList.toggle("hidden", !isHidden);
        header.classList.toggle("collapsed", !isHidden);
      }
    });
  });

  // 5. County Multi-Select Events
  initRmCountyMultiSelectEvents();

  // 6. Value Min/Max selects
  const rmMinVal = $("rmValueMin");
  const rmMaxVal = $("rmValueMax");
  const handleValueChange = () => {
    const minVal = rmMinVal ? (rmMinVal.value ? parseFloat(rmMinVal.value) : null) : null;
    const maxVal = rmMaxVal ? (rmMaxVal.value ? parseFloat(rmMaxVal.value) : null) : null;
    state.valueMin = minVal;
    state.valueMax = maxVal;
    if ($("valueMin")) $("valueMin").value = minVal !== null ? minVal : "";
    if ($("valueMax")) $("valueMax").value = maxVal !== null ? maxVal : "";
    if (typeof renderRows === "function") renderRows();
    updateRightmoveResultsCount();
  };
  rmMinVal?.addEventListener("change", handleValueChange);
  rmMaxVal?.addEventListener("change", handleValueChange);

  // 7. Date selects
  const rmDateSelect = $("rmDateAddedSelect");
  const rmQuickDate = $("rmQuickDate");
  const handleDateChange = (val) => {
    state.dateFilterPreset = val;
    state.dateFilterActive = val !== "all";
    if (rmDateSelect) rmDateSelect.value = val;
    if (rmQuickDate) rmQuickDate.value = val;
    if (typeof renderRows === "function") renderRows();
    updateRightmoveResultsCount();
  };
  rmDateSelect?.addEventListener("change", (e) => handleDateChange(e.target.value));
  rmQuickDate?.addEventListener("change", (e) => handleDateChange(e.target.value));

  // 8. Modern AI Match Score Slider
  initRmFitSlider();

  // 9. Status pills
  const statusContainer = $("rmStatusPills");
  if (statusContainer) {
    statusContainer.querySelectorAll(".rm-pill").forEach(pill => {
      pill.addEventListener("click", () => {
        statusContainer.querySelectorAll(".rm-pill").forEach(p => p.classList.remove("active"));
        pill.classList.add("active");
        const st = pill.dataset.status || "opportunities";
        state.statusFilter = st;
        const chkOpp = $("chkOpportunities");
        const chkAwarded = $("chkAwarded");
        if (chkOpp && chkAwarded) {
          if (st === "opportunities") { chkOpp.checked = true; chkAwarded.checked = false; }
          else if (st === "awarded") { chkOpp.checked = false; chkAwarded.checked = true; }
          else { chkOpp.checked = true; chkAwarded.checked = true; }
        }
        lsSet(LS_STATUS_FILTER, state.statusFilter);
        savePrefsToServer({ status_filter: state.statusFilter });
        if (typeof renderRows === "function") renderRows();
        updateRightmoveResultsCount();
      });
    });
  }
}

function updateRightmoveResultsCount() {
  const countEl = $("rmResultsCount");
  if (!countEl) return;
  const rows = typeof filteredAndSortedRows === "function" ? filteredAndSortedRows() : (state.rows || []);
  countEl.textContent = `${rows.length.toLocaleString()} results`;
}

function toggleShowAllRmCountries(show) {
  state.showAllRmCountries = !!show;
  renderRightmoveFocusFilters();
}

function renderRightmoveFocusFilters() {
  // A. Render Country Pills (Top 5 + 6th More button)
  const countryPillsContainer = $("rmCountryPills");
  if (countryPillsContainer) {
    const activeCountries = Array.isArray(state.managedCountries) && state.managedCountries.length > 0
      ? state.managedCountries
      : DEFAULT_MANAGED_COUNTRIES;
    const available = getAvailableCountries().filter(c => activeCountries.includes(c.name));
    const showAll = !!state.showAllRmCountries;
    const countriesToRender = showAll ? available : available.slice(0, 5);

    let html = "";
    for (const c of countriesToRender) {
      const isSelected = state.managedCountries.includes(c.name);
      const flagHtml = getFlagImgHtml(c.code, c.name);
      html += `
        <button type="button" class="rm-pill ${isSelected ? "active" : ""}" onclick="toggleRightmoveCountry('${esc(c.name)}')">
          ${flagHtml} ${esc(c.name)}
        </button>
      `;
    }

    html += `
      <button type="button" class="rm-pill" onclick="openProfile('countries')" title="Manage all international countries in My Profile">
        ⚙️ Manage in Profile
      </button>
    `;
    countryPillsContainer.innerHTML = html;
  }

  // B. Render County Selector (Multi-Select)
  const ukGrp = $("rmUkCountyGroup");
  const countyLabel = $("rmCountyLabel");
  if (ukGrp) {
    const hasUk = state.managedCountries.includes("United Kingdom");
    const hasIreland = state.managedCountries.includes("Ireland");

    if ((hasUk || hasIreland) && typeof UK_COUNTIES !== "undefined") {
      ukGrp.classList.remove("hidden");
      if (countyLabel) countyLabel.textContent = "County";
      renderRmCountyMultiSelect(hasUk, hasIreland);
    } else {
      ukGrp.classList.add("hidden");
    }
  }

  // C. Render Portal Pills
  const portalPillsContainer = $("rmPortalPills");
  if (portalPillsContainer) {
    let portalHtml = "";
    let activePortals = PORTALS;
    if (state.managedCountries && state.managedCountries.length > 0) {
      activePortals = PORTALS.filter(p => state.managedCountries.includes(p.country));
      if (activePortals.length === 0) activePortals = PORTALS;
    }
    for (const p of activePortals) {
      const isSelected = !_selectedPortals || _selectedPortals.has(p.id);
      const flagHtml = typeof getPortalFlagImgHtml === "function" ? getPortalFlagImgHtml(p) : (p.flag || "🌐");
      const displayLabel = p.label || p.id;
      portalHtml += `
        <button type="button" class="rm-pill ${isSelected ? "active" : ""}" onclick="toggleRightmovePortal('${esc(p.id)}')">
          ${flagHtml}<span>${esc(displayLabel)}</span>
        </button>
      `;
    }
    portalPillsContainer.innerHTML = portalHtml;
  }

  // D. Sync Values
  if ($("rmSearchInput")) $("rmSearchInput").value = state.q || "";
  if ($("rmSearchKeywordInput")) $("rmSearchKeywordInput").value = state.q || "";
  if ($("rmValueMin")) $("rmValueMin").value = state.valueMin !== null ? String(state.valueMin) : "";
  if ($("rmValueMax")) $("rmValueMax").value = state.valueMax !== null ? String(state.valueMax) : "";
  if (typeof syncAllDatePills === "function") syncAllDatePills(state.dateFilterPreset || "all");
  if ($("rmQuickDate")) $("rmQuickDate").value = state.dateFilterPreset || "all";
  if (typeof renderSearchChips === "function") renderSearchChips();

  // E. Update Count
  updateRightmoveResultsCount();
}

function toggleRightmoveCountry(countryName) {
  toggleManagedCountry(countryName);
  renderRightmoveFocusFilters();
  if (typeof renderRows === "function") renderRows();
}

function toggleRightmovePortal(portalId) {
  if (!_selectedPortals) {
    _selectedPortals = new Set(PORTALS.map(p => p.id));
  }
  if (_selectedPortals.has(portalId)) {
    _selectedPortals.delete(portalId);
  } else {
    _selectedPortals.add(portalId);
  }
  savePortalSelection();
  renderRightmoveFocusFilters();
  if (typeof renderRows === "function") renderRows();
  if (typeof updateResultsTotal === "function") updateResultsTotal();
  if (typeof updateRightmoveResultsCount === "function") updateRightmoveResultsCount();
}

function initCollapsiblePanels() {
  const handleToggleSidebar = () => {
    if (state.focusMode) {
      toggleFocusMode(false);
      setSidebarCollapsed(false);
      localStorage.setItem(storageKey(LS_SIDEBAR_COLLAPSED), "0");
      savePrefsToServer({ sidebar_collapsed: "0" });
      return;
    }
    
    const sidebar = $("filterSidebar");
    const next = !sidebar?.classList.contains("sidebar--collapsed");
    setSidebarCollapsed(next);
    const val = next ? "1" : "0";
    localStorage.setItem(storageKey(LS_SIDEBAR_COLLAPSED), val);
    savePrefsToServer({ sidebar_collapsed: val });
  };

  $("btnToggleSidebar")?.addEventListener("click", handleToggleSidebar);
  $("btnExpandSidebarTopbar")?.addEventListener("click", () => {
    if (state.focusMode) {
      toggleFocusMode(false);
      return;
    }
    setSidebarCollapsed(false);
    localStorage.setItem(storageKey(LS_SIDEBAR_COLLAPSED), "0");
    savePrefsToServer({ sidebar_collapsed: "0" });
  });

  $("btnFocusMode")?.addEventListener("click", () => toggleFocusMode());
  $("btnFocusModeTopbar")?.addEventListener("click", () => toggleFocusMode());
  $("btnResetAllFilters")?.addEventListener("click", resetAllFilters);
  $("btnResetAllFiltersFocus")?.addEventListener("click", resetAllFilters);

  initRightmoveFocusFilters();
}

function resetAllFilters() {
  // 1. Search keyword & scope
  state.q = "";
  state.keywordScope = "all";
  lsSet(LS_KEYWORD_SCOPE, "all");
  if ($("keywordScopeSelect")) $("keywordScopeSelect").value = "all";
  if ($("rmKeywordScopeSelect")) $("rmKeywordScopeSelect").value = "all";
  if (typeof updateScopeLabelAndHint === "function") updateScopeLabelAndHint("all");
  _collapsedMatchGroups.clear();
  const qInput = $("q");
  if (qInput) qInput.value = "";
  if ($("rmSearchInput")) $("rmSearchInput").value = "";
  if ($("rmSearchKeywordInput")) $("rmSearchKeywordInput").value = "";
  if (typeof updateActiveSearchKeywordBadge === "function") updateActiveSearchKeywordBadge();

  // 2. Portals/Countries picker selection
  state.managedCountries = [...DEFAULT_MANAGED_COUNTRIES];
  lsSet(LS_MANAGED_COUNTRIES, state.managedCountries);
  savePrefsToServer({ managed_countries: JSON.stringify(state.managedCountries) });

  state.selectedUkCounties = typeof UK_COUNTIES !== "undefined" ? UK_COUNTIES.map(c => c.name) : [];
  lsSet(LS_UK_COUNTIES, state.selectedUkCounties);
  state._portalsSectionExpanded = false;
  state._countySectionExpanded = false;
  if (typeof updatePortalsAccordionState === "function") updatePortalsAccordionState();
  if (typeof updateCountyAccordionState === "function") updateCountyAccordionState();
  if (typeof updateUkCountyFilterVisibility === "function") updateUkCountyFilterVisibility();

  _selectedPortals = null;
  lsSet(LS_PORTAL, null);
  if (state.meta) state.meta.source_counts = {};

  renderCountryBadges();
  renderManageCountriesList("");
  renderPortalsInCountries();

  if (typeof syncNativeScope === "function") syncNativeScope();
  if (typeof updatePickerLabel === "function") updatePickerLabel();

  // 3. Match Profile / Fit
  state.activeProfileId = "";
  if ($("fitProfileSelect")) $("fitProfileSelect").value = "";
  if ($("rmCompanyProfileSelect")) $("rmCompanyProfileSelect").value = "";
  state.fitMin = null;
  updateRmFitSliderUI(0);
  const slider = $("fitThresholdSlider");
  if (slider) slider.value = 0;
  const valLabel = $("fitThresholdVal");
  if (valLabel) valLabel.textContent = "All";
  $("fitControls")?.classList.add("hidden");
  $("fitHint")?.classList.remove("hidden");

  // 4. Status Filter (Show)
  const chkOpp = $("chkOpportunities");
  const chkAwarded = $("chkAwarded");
  if (chkOpp && chkAwarded) {
    chkOpp.checked = true;
    chkAwarded.checked = false;
  }
  state.statusFilter = "opportunities";
  lsSet(LS_STATUS_FILTER, "opportunities");
  savePrefsToServer({ status_filter: "opportunities" });

  // 5. Date filter
  const dateContainer = $("datePillsContainer");
  if (dateContainer) {
    dateContainer.querySelectorAll(".pill").forEach(p => {
      if (p.dataset.days === "all") p.classList.add("active");
      else p.classList.remove("active");
    });
  }
  state.dateFilterPreset = "all";
  state.dateFilterActive = false;
  state.dateFilterValueMin = null;
  state.dateFilterValueMax = null;

  const sliderStart = $("dateSliderStart");
  const sliderEnd = $("dateSliderEnd");
  if (sliderStart && sliderEnd) {
    sliderStart.value = sliderStart.min;
    sliderEnd.value = sliderEnd.max;
  }
  if (typeof updateDateSliderDisplay === "function") updateDateSliderDisplay();

  // 6. Source Filter
  state.sourceFilter = "all";
  if ($("sourceFilter")) $("sourceFilter").value = "all";

  // 7. Value range
  state.valueMin = null;
  state.valueMax = null;
  if ($("valueMin")) $("valueMin").value = "";
  if ($("valueMax")) $("valueMax").value = "";
  const btnClear = $("btnClearValue");
  if (btnClear) btnClear.disabled = true;

  // 8. Update summaries & trigger rendering
  if (typeof updateExplanationText === "function") updateExplanationText();
  updateFilterSidebarSummary();

  renderRightmoveFocusFilters();

  if (typeof renderRows === "function") renderRows();
  if (typeof updateResultsTotal === "function") updateResultsTotal();
}

function maybeShowWelcomeDashboard() {
  const params = new URLSearchParams(window.location.search);
  if (params.get("welcome") === "1") {
    history.replaceState({}, "", window.location.pathname);
  }
}

// Stripe's billing portal "Return to tender" link lands here (see
// create_portal_session's return_url) — reopen the in-app pricing modal
// instead of leaving the user on a bare page.
function maybeOpenBillingFromReturn() {
  const params = new URLSearchParams(window.location.search);
  if (params.get("openBilling") === "1") {
    history.replaceState({}, "", window.location.pathname);
    if (typeof openPricingModal === "function") openPricingModal();
    return;
  }

  // Checkout's success_url / cancel_url, and the direct-downgrade redirect, all land back
  // here too (see create_checkout_session) — same reasoning: land back in the app the user
  // was using, not the standalone pricing.html page, with a toast confirming what happened.
  if (params.get("billing_success") === "1") {
    const sessionId = params.get("session_id");
    history.replaceState({}, "", window.location.pathname);
    if (sessionId) {
      fetch("/api/billing/confirm", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ session_id: sessionId }),
      })
        .then(res => res.json())
        .then(data => {
          if (data?.ok) {
            cpShowToast(`Payment successful! You now have ${data.balance} credits.`, "success");
            refreshCredits();
          } else {
            showToastError(data?.error || "Payment received, but we couldn't confirm it automatically — check Billing & credits.");
          }
        })
        .catch(() => showToastError("Payment received, but we couldn't confirm it automatically — check Billing & credits."))
        .finally(() => { if (typeof openPricingModal === "function") openPricingModal(); });
    } else if (typeof openPricingModal === "function") {
      openPricingModal();
    }
  } else if (params.get("billing_cancelled") === "1") {
    history.replaceState({}, "", window.location.pathname);
    cpShowToast("Payment cancelled — no changes were made.", "info");
    if (typeof openPricingModal === "function") openPricingModal();
  } else if (params.get("billing_downgraded") === "1") {
    const plan = params.get("plan") || "";
    history.replaceState({}, "", window.location.pathname);
    cpShowToast(`Your plan will switch to ${plan ? plan.charAt(0).toUpperCase() + plan.slice(1) : "the new plan"} at the end of your current billing period.`, "success");
    refreshCredits();
    if (typeof openPricingModal === "function") openPricingModal();
  }
}

// ── Pipeline ─────────────────────────────────────────────────────────────────
const PIPELINE_STAGES = ["watching", "bidding", "submitted", "won", "lost"];
const STAGE_LABEL = {
  watching: "Watching",
  bidding: "Bidding",
  submitted: "Submitted",
  won: "Won",
  lost: "Lost",
};
const STAGE_COLOR = {
  watching: "stage--watching",
  bidding: "stage--bidding",
  submitted: "stage--submitted",
  won: "stage--won",
  lost: "stage--lost",
};

async function loadPipeline() {
  try {
    const res = await fetch("/api/pipeline");
    if (!res.ok) return;
    const data = await res.json();
    state.pipeline = {};
    for (const item of (data.items || [])) {
      state.pipeline[item.tender_key] = item;
    }
  } catch {/* ignore */ }
}

async function trackTender(row, stage) {
  const key = rowKey(row);
  const fit = state.fitCache[key]?.deep || state.fitCache[key]?.quick || null;
  const body = {
    tender_key: key,
    stage,
    title: row.title || "",
    source: row.source || "",
    contracting_authority: row.contracting_authority || "",
    submission_deadline: row.submission_deadline || "",
    estimated_value: String(row.estimated_value_eur || row.estimated_value || ""),
    fit_score: fit?.score ?? null,
    fit_band: fit?.band ?? null,
  };
  const res = await fetch("/api/pipeline", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (res.ok) {
    state.pipeline[key] = { ...body, notes: state.pipeline[key]?.notes || "" };
    renderRows();
    renderPipelineBoard();
    // Refresh the track panel in the details panel if this is the active tender.
    if (state.activeKey === key && window._detailRow) refreshTrackPanel(window._detailRow);
  }
}

async function untrackTender(key) {
  const res = await fetch(`/api/pipeline/${encodeURIComponent(key)}`, { method: "DELETE" });
  if (res.ok) {
    delete state.pipeline[key];
    renderRows();
    renderPipelineBoard();
    if (state.activeKey === key && window._detailRow) refreshTrackPanel(window._detailRow);
  }
}

async function savePipelineNotes(key, notes) {
  state.pipeline[key].notes = notes;
  await fetch(`/api/pipeline/${encodeURIComponent(key)}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ notes }),
  });
}

function pipelineStageOf(key) {
  return state.pipeline[key]?.stage || null;
}

// HTML for the track/stage button used in rows and cards
function trackBtnHtml(row) {
  const key = rowKey(row);
  const stage = pipelineStageOf(key);
  if (stage) {
    return `<button class="track-btn track-btn--active ${STAGE_COLOR[stage]}" data-key="${esc(key)}"
      title="Change stage or remove">${STAGE_LABEL[stage]}</button>`;
  }
  return `<button class="track-btn" data-key="${esc(key)}" title="Track this tender">＋ Track</button>`;
}

function watchlistBtnHtml(row) {
  const key = rowKey(row);
  const stage = pipelineStageOf(key);
  const isWatching = stage === "watching";
  return `<button class="watchlist-btn${isWatching ? " watchlist-btn--active" : ""}" data-key="${esc(key)}" title="${isWatching ? "Remove from watchlist" : "Add to watchlist"}">${isWatching ? "★" : "☆"}</button>`;
}

// Show a popover to pick stage or remove
function showStagePopover(anchorEl, row) {
  document.querySelectorAll(".stage-popover").forEach(p => p.remove());
  const key = rowKey(row);
  const current = pipelineStageOf(key);

  const pop = document.createElement("div");
  pop.className = "stage-popover";

  if (current) {
    const removeBtn = document.createElement("button");
    removeBtn.className = "stage-popover__remove";
    removeBtn.textContent = "✕ Remove from pipeline";
    removeBtn.addEventListener("click", () => { pop.remove(); untrackTender(key); });
    pop.appendChild(removeBtn);
    const sep = document.createElement("div");
    sep.className = "stage-popover__sep";
    pop.appendChild(sep);
  }

  for (const s of PIPELINE_STAGES) {
    const btn = document.createElement("button");
    btn.className = `stage-popover__item ${STAGE_COLOR[s]}${s === current ? " stage-popover__item--active" : ""}`;
    btn.textContent = STAGE_LABEL[s];
    btn.addEventListener("click", () => { pop.remove(); trackTender(row, s); });
    pop.appendChild(btn);
  }

  document.body.appendChild(pop);
  const rect = anchorEl.getBoundingClientRect();
  pop.style.top = (rect.bottom + window.scrollY + 4) + "px";
  pop.style.left = (rect.left + window.scrollX) + "px";

  const dismiss = (e) => { if (!pop.contains(e.target) && e.target !== anchorEl) { pop.remove(); document.removeEventListener("click", dismiss, true); } };
  setTimeout(() => document.addEventListener("click", dismiss, true), 0);
}

function pushRecentSearch(q, scope) {
  const term = (q || "").trim();
  if (!term) return;
  const entry = { q: term, scope: scope || "all", id: null, emailAlertsEnabled: true, lastRefreshedAt: null };

  // If term already exists in recent searches, maintain stable consistent order and never reorder
  const existingIdx = state.recentSearches.findIndex(
    (r) => r.q.toLowerCase() === term.toLowerCase()
  );
  if (existingIdx !== -1) {
    if (scope && state.recentSearches[existingIdx].scope !== scope) {
      state.recentSearches[existingIdx].scope = scope;
      lsSet(LS_RECENT, state.recentSearches);
    }
    updateActiveChipHighlight();
    return;
  }

  // Only prepend brand new search terms
  state.recentSearches = [
    entry,
    ...state.recentSearches,
  ].slice(0, 8);
  lsSet(LS_RECENT, state.recentSearches);
  renderSearchChips();
  // Persist to server so recent searches survive browser switches, and pick up
  // the durable server-assigned ids (needed for the fast cached-results path).
  fetch("/api/recent-searches", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ searches: state.recentSearches }),
  }).then(r => r.json()).then(data => {
    if (Array.isArray(data.searches)) {
      const byKey = new Map(data.searches.map(s => [`${s.q.toLowerCase()}::${(s.scope || "all").toLowerCase()}`, s]));
      state.recentSearches = state.recentSearches.map(r => {
        const match = byKey.get(`${r.q.toLowerCase()}::${(r.scope || "all").toLowerCase()}`);
        if (!match) return r;
        return { ...r, id: match.id, emailAlertsEnabled: !!match.emailAlertsEnabled, lastRefreshedAt: match.lastRefreshedAt || null };
      });
      lsSet(LS_RECENT, state.recentSearches);
      renderSearchChips();
    }
  }).catch(() => {/* non-critical */ });
}

function currentFilterSnapshot() {
  return {
    sourceFilter: state.sourceFilter,
    statusFilter: state.statusFilter,
    dateFilterPreset: state.dateFilterPreset,
    dateFilterType: state.dateFilterType,
    valueMin: state.valueMin,
    valueMax: state.valueMax,
  };
}

async function loadServerRecentSearches() {
  try {
    const res = await fetch("/api/recent-searches");
    if (!res.ok) return;
    const data = await res.json();
    if (Array.isArray(data.searches)) {
      state.recentSearches = data.searches.map(s => ({
        id: s.id,
        q: s.q,
        scope: s.scope || "all",
        emailAlertsEnabled: !!s.emailAlertsEnabled,
        lastRefreshedAt: s.lastRefreshedAt || null,
      })).slice(0, 8);
      lsSet(LS_RECENT, state.recentSearches);
      renderSearchChips();
    }
  } catch {/* ignore */ }
}

async function loadServerSavedSearches() {
  try {
    const res = await fetch("/api/saved-searches");
    if (!res.ok) return;
    const data = await res.json();
    if (Array.isArray(data.searches)) {
      state.savedSearches = data.searches.map(s => ({
        id: s.id,
        q: s.query,
        scope: s.scope,
        filters: s.filters || {},
        savedAt: new Date(s.created_at).getTime(),
      }));
      lsSet(LS_SAVED, state.savedSearches);
      renderSearchChips();
      if (typeof syncSaveSearchButtonStates === "function") syncSaveSearchButtonStates();
    }
  } catch {/* ignore */ }
}

function syncSaveSearchButtonStates() {
  const activeQ = (state.q || "").trim();
  const scope = state.scope || "all";
  const isSearchOn = Boolean(
    activeQ ||
    state.searchPhase === "loading" ||
    (state.searchPhase === "complete" && state.rows && state.rows.length > 0)
  );

  const isSaved = isSearchOn && activeQ ? state.savedSearches.some(
    (s) => s.q.toLowerCase() === activeQ.toLowerCase() && s.scope === scope
  ) : false;

  const saveBtns = [
    $("btnSaveSearch"),
    $("btnRmSaveSearch")
  ].filter(Boolean);

  saveBtns.forEach(btn => {
    // Compact buttons (the search filter bar) show only the star; the words go to aria-label
    const setLabel = (text) => {
      btn.textContent = btn.dataset.compact === "true" ? text.charAt(0) : text;
      btn.setAttribute("aria-label", text.slice(2));
    };
    if (!isSearchOn) {
      btn.disabled = true;
      btn.style.opacity = "0.45";
      btn.style.cursor = "not-allowed";
      btn.style.pointerEvents = "none";
      btn.title = "Run a search first to enable Save search";
      btn.classList.remove("btn--save-search-active", "active");
      setLabel("☆ Save search");
    } else {
      btn.disabled = false;
      btn.style.opacity = "1";
      btn.style.cursor = "pointer";
      btn.style.pointerEvents = "auto";
      if (isSaved) {
        setLabel("★ Saved search");
        btn.classList.add("btn--save-search-active", "active");
        btn.title = "Click to remove from saved search presets";
      } else {
        setLabel("☆ Save search");
        btn.classList.remove("btn--save-search-active", "active");
        btn.title = "Save this filter preset for quick access";
      }
    }
  });
}

async function saveCurrentSearch() {
  const activeQ = (state.q || "").trim();
  const isSearchOn = Boolean(
    activeQ ||
    state.searchPhase === "loading" ||
    (state.searchPhase === "complete" && state.rows && state.rows.length > 0)
  );
  if (!isSearchOn || !activeQ) {
    _showToast("Please run a tender search first to save search filters.", "error");
    return;
  }
  const q = activeQ;
  const scope = state.scope || "all";
  const filters = currentFilterSnapshot();
  const name = q; // use query as name for simplicity
  // Optimistic local update
  const exists = state.savedSearches.some(
    (s) => s.q.toLowerCase() === q.toLowerCase() && s.scope === scope
  );
  if (exists) {
    // Unsave — remove locally and from server
    const toRemove = state.savedSearches.find(
      (s) => s.q.toLowerCase() === q.toLowerCase() && s.scope === scope
    );
    state.savedSearches = state.savedSearches.filter(
      (s) => !(s.q.toLowerCase() === q.toLowerCase() && s.scope === scope)
    );
    lsSet(LS_SAVED, state.savedSearches);
    renderSearchChips();
    syncSaveSearchButtonStates();
    _showToast(`Removed "${q}" from saved search presets.`);
    if (toRemove?.id) {
      fetch(`/api/saved-searches/${toRemove.id}`, { method: "DELETE" }).catch(() => { });
    }
  } else {
    const entry = { q, scope, filters, savedAt: Date.now() };
    state.savedSearches = [entry, ...state.savedSearches].slice(0, 30);
    lsSet(LS_SAVED, state.savedSearches);
    renderSearchChips();
    syncSaveSearchButtonStates();
    _showToast(`Saved "${q}" search preset!`, "success");
    fetch("/api/saved-searches", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name, query: q, scope, filters }),
    }).then(r => r.json()).then(data => {
      if (data.id) {
        const idx = state.savedSearches.findIndex(s => s.q === q && s.scope === scope);
        if (idx !== -1) state.savedSearches[idx].id = data.id;
        lsSet(LS_SAVED, state.savedSearches);
      }
    }).catch(() => { });
  }
}

function removeSavedSearch(q, scope) {
  const toRemove = state.savedSearches.find(
    (s) => s.q.toLowerCase() === q.toLowerCase() && s.scope === scope
  );
  state.savedSearches = state.savedSearches.filter(
    (s) => !(s.q.toLowerCase() === q.toLowerCase() && s.scope === scope)
  );
  lsSet(LS_SAVED, state.savedSearches);
  renderSearchChips();
  if (toRemove?.id) {
    fetch(`/api/saved-searches/${toRemove.id}`, { method: "DELETE" }).catch(() => { });
  }
}

function removeRecentSearch(q, scope) {
  state.recentSearches = state.recentSearches.filter(
    (r) => !(r.q.toLowerCase() === q.toLowerCase() && (r.scope || "all") === (scope || "all"))
  );
  lsSet(LS_RECENT, state.recentSearches);
  renderSearchChips();
  // Sync to server so deletions propagate
  const url = `/api/recent-searches?q=${encodeURIComponent(q)}&scope=${encodeURIComponent(scope || "all")}`;
  fetch(url, { method: "DELETE" }).catch(() => { });
}

function clearAllRecent() {
  state.recentSearches = [];
  lsSet(LS_RECENT, state.recentSearches);
  renderSearchChips();
  // Sync to server
  fetch("/api/recent-searches", { method: "DELETE" }).catch(() => { });
}

