// how a buyer or supplier name is shown (web/name-format.js); stored names and search keys are untouched
function displayName(name) { return typeof NameFormat !== "undefined" ? NameFormat.display(name) : String(name ?? ""); }

function esc(s) {
  return String(s ?? "").replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c])
  );
}
function escapeHtml(s) {
  return esc(s);
}

// Builds a shareable URL that deep-links straight into a buyer's or supplier's profile
// (read by the "open" param handler in initAll()). In-app cross-navigation links call
// openBuyerProfileDrawer/openSupplierIntelligenceForTender directly instead of following
// this href, so switching profiles stays in the current tab; the href itself remains as
// a copyable/shareable link and a plain-navigation fallback.
function buyerDeepLinkUrl(authorityName) {
  return `${location.origin}${location.pathname}?open=buyer&name=${encodeURIComponent(authorityName || "")}`;
}
function supplierDeepLinkUrl(supplierName) {
  return `${location.origin}${location.pathname}?open=supplier&q=${encodeURIComponent(supplierName || "")}`;
}

// Custom Alert/Confirm Modals
window.showAlert = function (message, title = "Alert") {
  return new Promise((resolve) => {
    const modal = document.getElementById("customAlertModal");
    const titleEl = document.getElementById("customAlertTitle");
    const msgEl = document.getElementById("customAlertMessage");
    const btnOk = document.getElementById("btnCustomAlertOk");

    if (!modal || !msgEl || !btnOk) {
      window.alert(message);
      resolve();
      return;
    }

    if (titleEl) titleEl.innerText = title;
    msgEl.innerHTML = esc(message).replace(/\n/g, "<br>");

    modal.classList.remove("hidden");

    const cleanup = () => {
      modal.classList.add("hidden");
      btnOk.removeEventListener("click", onOk);
      document.removeEventListener("keydown", onKey);
    };

    const onOk = () => {
      cleanup();
      resolve();
    };

    const onKey = (e) => {
      if (e.key === "Enter" || e.key === "Escape") {
        e.preventDefault();
        onOk();
      }
    };

    btnOk.addEventListener("click", onOk);
    document.addEventListener("keydown", onKey);
  });
};

// options: { okText, cancelText, danger } — all optional, defaulting to the classic
// destructive-confirm look ("OK" / "Cancel", red OK button) so existing callers are unaffected.
window.showConfirm = function (message, title = "Confirm", options = {}) {
  const { okText = "OK", cancelText = "Cancel", danger = true } = options;
  return new Promise((resolve) => {
    const modal = document.getElementById("customConfirmModal");
    const titleEl = document.getElementById("customConfirmTitle");
    const msgEl = document.getElementById("customConfirmMessage");
    const btnOk = document.getElementById("btnCustomConfirmOk");
    const btnCancel = document.getElementById("btnCustomConfirmCancel");

    if (!modal || !msgEl || !btnOk || !btnCancel) {
      const res = window.confirm(message);
      resolve(res);
      return;
    }

    if (titleEl) titleEl.innerText = title;
    msgEl.innerHTML = esc(message).replace(/\n/g, "<br>");
    btnOk.textContent = okText;
    btnCancel.textContent = cancelText;
    btnOk.style.backgroundColor = danger ? "#ef4444" : "var(--primary, #2563eb)";

    modal.classList.remove("hidden");

    const cleanup = () => {
      modal.classList.add("hidden");
      btnOk.removeEventListener("click", onOk);
      btnCancel.removeEventListener("click", onCancel);
      document.removeEventListener("keydown", onKey);
    };

    const onOk = () => {
      cleanup();
      resolve(true);
    };

    const onCancel = () => {
      cleanup();
      resolve(false);
    };

    const onKey = (e) => {
      if (e.key === "Enter") {
        e.preventDefault();
        onOk();
      } else if (e.key === "Escape") {
        e.preventDefault();
        onCancel();
      }
    };

    btnOk.addEventListener("click", onOk);
    btnCancel.addEventListener("click", onCancel);
    document.addEventListener("keydown", onKey);
  });
};

// In-page replacement for window.prompt (which blocks the whole tab and can't be styled or
// driven by tests). Resolves with the entered string, or null if cancelled.
window.showPrompt = function (message, defaultValue = "", title = "Enter a value") {
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "modal-overlay";
    overlay.setAttribute("role", "dialog");
    overlay.setAttribute("aria-modal", "true");
    overlay.style.zIndex = "20000";
    overlay.innerHTML = `
      <div class="modal modal--dialog">
        <div class="modal__header modal__header--dialog"><h2 class="modal__title">${esc(title)}</h2></div>
        <div class="modal__body modal__body--dialog">
          <label for="tfPromptInput" style="display:block;margin-bottom:8px">${esc(message)}</label>
          <input id="tfPromptInput" class="input" type="text" style="width:100%" value="${esc(defaultValue)}" />
        </div>
        <div class="modal__actions-row" style="margin-top:16px;justify-content:flex-end;gap:8px;width:100%">
          <button type="button" data-act="cancel" class="btn btn--dialog btn--secondary" style="min-width:80px">Cancel</button>
          <button type="button" data-act="ok" class="btn btn--dialog btn--primary" style="min-width:80px">OK</button>
        </div>
      </div>`;
    document.body.appendChild(overlay);
    const input = overlay.querySelector("#tfPromptInput");
    const finish = (value) => {
      document.removeEventListener("keydown", onKey);
      overlay.remove();
      resolve(value);
    };
    const onKey = (e) => {
      if (e.key === "Enter") { e.preventDefault(); finish(input.value); }
      else if (e.key === "Escape") { e.preventDefault(); finish(null); }
    };
    overlay.addEventListener("click", (e) => {
      const act = e.target.closest("[data-act]")?.dataset.act;
      if (act === "ok") finish(input.value);
      else if (act === "cancel" || e.target === overlay) finish(null);
    });
    document.addEventListener("keydown", onKey);
    input.focus();
    input.select();
  });
};

function formatDeadline(row) {
  return esc(row.submission_deadline || "—");
}

function formatDaysLeft(row) {
  const days = row.days_until_deadline;
  const urgency = row.deadline_urgency || "unknown";
  const deadline = row.submission_deadline || "";

  if (days == null || urgency === "unknown") {
    const pubDate = parseDate(row.date_published);
    const pubYear = pubDate ? pubDate.getFullYear() : null;
    const pubText = pubYear && pubYear < new Date().getFullYear() ? ` · Published ${pubYear}` : "";
    return `<span class="days-badge days-badge--unknown" title="${esc(deadline || "No deadline stated")}">No deadline stated${esc(pubText)}</span>`;
  }
  if (urgency === "past") {
    return `<span class="days-badge days-badge--past" title="Deadline: ${esc(deadline)}">Closed</span>`;
  }

  const label = days === 0 ? "Today" : days === 1 ? "1 day" : `${days} days`;
  const cls = urgency === "critical" ? "days-badge--critical"
    : urgency === "soon" ? "days-badge--soon"
      : "days-badge--normal";
  return `<span class="days-badge ${cls}" title="Deadline: ${esc(deadline)}">${esc(label)}</span>`;
}

function parseDate(str) {
  if (!str) return null;
  const s = String(str).trim();
  if (!s || s === "—" || s.toLowerCase() === "tbc" || s.toLowerCase() === "n/a") return null;

  // Try YYYY-MM-DD
  let match = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (match) {
    return new Date(parseInt(match[1]), parseInt(match[2]) - 1, parseInt(match[3]));
  }

  // Try DD/MM/YYYY
  match = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (match) {
    return new Date(parseInt(match[3]), parseInt(match[2]) - 1, parseInt(match[1]));
  }

  // Try DD-MM-YYYY
  match = s.match(/^(\d{1,2})-(\d{1,2})-(\d{4})/);
  if (match) {
    return new Date(parseInt(match[3]), parseInt(match[2]) - 1, parseInt(match[1]));
  }

  // Fallback to standard Date parsing
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

function isDeadlinePassed(row) {
  if (!row) return false;
  if (row.deadline_urgency === "past") return true;
  if (row.days_until_deadline != null && row.days_until_deadline < 0) return true;

  const dlStr = row.submission_deadline || row.deadline_date || row.deadline;
  if (!dlStr || dlStr === "—" || dlStr.toLowerCase() === "tbc" || dlStr.toLowerCase() === "n/a") return false;

  const d = parseDate(dlStr);
  if (d) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return d < today;
  }

  return false;
}

function getDeadlinePassedBannerHtml(row) {
  if (!isDeadlinePassed(row)) return "";
  const dlStr = row?.submission_deadline || row?.deadline_date || row?.deadline || "Closed";
  return `
    <div class="deadline-passed-banner" style="background: #fef2f2; border: 1px solid #fecaca; border-left: 4px solid #ef4444; color: #991b1b; padding: 10px 12px; border-radius: 8px; margin-bottom: 14px; box-shadow: 0 2px 6px rgba(239,68,68,0.06);">
      <div style="display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap; margin-bottom: 4px;">
        <div style="display: flex; align-items: center; gap: 6px; font-weight: 800; font-size: 12px; color: #b91c1c; text-transform: uppercase; letter-spacing: 0.3px;">
          <span style="font-size: 15px; line-height: 1;">⚠️</span>
          <span>Deadline Passed</span>
        </div>
        <span style="background: #ef4444; color: #fff; font-size: 10px; font-weight: 800; padding: 2px 8px; border-radius: 12px; text-transform: uppercase; letter-spacing: 0.3px; white-space: nowrap;">Closed</span>
      </div>
      <div style="font-size: 11.5px; color: #7f1d1d; line-height: 1.4;">
        Official Deadline: <strong>${esc(dlStr)}</strong>. Submissions may no longer be accepted.
      </div>
    </div>
  `;
}

// The currency a portal quotes in, for a value that arrives as bare digits ("100,000" from Contracts Finder).
const CURRENCY_BY_SOURCE = {
  etenders_ie: "€", boamp: "€", bund: "€", eu_ted: "€",
  find_tender: "£", contracts_finder: "£", etenders_ni: "£", pcs: "£", sell2wales: "£", procontract: "£", gca_agreements: "£",
  sam_gov: "$", canadabuys: "$",
};

// One format for every portal: currency symbol, thousands separators, no pence ("£6,699,997.00" from ProContract
// and a bare "100,000" from Contracts Finder both used to be shown as they came). Anything with words in it
// ("TBC", "£1m - £2m") is left exactly as published.
function formatValue(v, source) {
  const s = String(v).trim();
  const withSymbol = s.match(/^([£€$])\s*([\d.,\s]+)$/);
  if (!withSymbol && /[^\d.,\s]/.test(s)) return s;
  const n = parseFloat((withSymbol ? withSymbol[2] : s).replace(/[,\s]/g, ""));
  if (isNaN(n)) return s;
  const prefix = withSymbol ? withSymbol[1] : (CURRENCY_BY_SOURCE[source] || "");
  return prefix + n.toLocaleString("en-GB", { maximumFractionDigits: 0 });
}

// Parse a value string to a number for sorting; returns -1 for blanks (sink to bottom).
function parseValueNum(row) {
  const raw = String(row.estimated_value_eur || row.estimated_value || "").trim();
  if (!raw) return -1;
  const n = parseFloat(raw.replace(/[^\d.]/g, ""));
  return isNaN(n) ? -1 : n;
}

// ── Fit Score (Phase 2) ───────────────────────────────────────────────────
// Tier 1: instant, rules-based "quick fit". Tier 2: AI "deep fit" on open.

const NACE_KEYWORDS = {
  A: ["agriculture", "farming", "forestry", "fishing", "crop", "livestock"],
  B: ["mining", "quarrying", "extraction", "mineral"],
  C: ["manufacturing", "production", "fabrication", "assembly", "factory"],
  D: ["electricity", "gas", "steam", "energy", "power", "utility"],
  E: ["water", "sewerage", "waste", "recycling", "remediation"],
  F: ["construction", "building", "civil engineering", "refurbishment", "works", "demolition"],
  G: ["wholesale", "retail", "trade", "supply of goods", "distribution"],
  H: ["transport", "logistics", "haulage", "freight", "storage", "warehousing"],
  I: ["accommodation", "catering", "food service", "hospitality", "hotel"],
  J: ["software", "ict", "it ", "information", "communication", "digital", "data", "cyber", "telecom", "technology"],
  K: ["financial", "insurance", "banking", "investment"],
  L: ["real estate", "property", "letting"],
  M: ["consultancy", "consulting", "professional services", "legal", "accounting", "engineering", "architecture", "research", "scientific", "technical", "advisory", "analysis"],
  N: ["administrative", "support services", "facilities", "cleaning", "security", "recruitment", "staffing"],
  O: ["public administration", "defence", "government"],
  P: ["education", "training", "school", "learning", "teaching"],
  Q: ["health", "social work", "care", "medical", "nursing", "wellbeing"],
  R: ["arts", "entertainment", "recreation", "culture", "sport"],
  S: ["repair", "other service", "membership"],
  T: ["household"],
  U: ["extraterritorial"],
};

const SOURCE_COUNTRY = {
  etenders_ie: "IE",
  etenders_ni: "GB",
  sell2wales: "GB",
  pcs: "GB",
  find_tender: "GB",
  contracts_finder: "GB",
};

const ENTERPRISE_TURNOVER_GUIDE = {
  micro: 2,    // ~€M practical ceiling for comfortable delivery
  small: 10,
  medium: 50,
  large: 1000,
};

const STOPWORDS = new Set(
  ("the a an and or of for to in on with by from provision services service supply "
    + "contract tender framework agreement public sector ltd limited plc and/or our "
    + "we are is will be this that these those new solution solutions management system "
    + "systems business development support project projects delivery deliver provider "
    + "provide contractor client customer requirement requirements capability capabilities "
    + "experience team teams process processes partner partners industry industries "
    + "company profile context customize core past performance information description "
    + "details general standards quality work works").split(/\s+/)
);

function getActiveProfile() {
  if (!state.activeProfileId) return null;
  return (
    state.companyProfiles.find((p) => String(p.id) === String(state.activeProfileId)) || null
  );
}

function getActiveProfileMeta() {
  const p = getActiveProfile();
  if (!p) return null;
  let meta = {};
  try { meta = JSON.parse(p.meta_json || "{}"); } catch { meta = {}; }
  return { ...meta, _text: p.profile_text || "", _name: p.name || "" };
}

function profileKeywords(meta) {
  const text = `${meta._text || ""} ${meta._name || ""}`.toLowerCase();
  const words = text
    .replace(/[^a-z0-9\s]/g, " ")
    .split(/\s+/)
    .filter((w) => w.length >= 4 && !STOPWORDS.has(w));
  const set = new Set(words);
  // Add NACE sector keywords for the chosen business type
  const sector = meta.business_type;
  if (sector && NACE_KEYWORDS[sector]) {
    for (const kw of NACE_KEYWORDS[sector]) set.add(kw.trim());
  }
  return set;
}

function computeQuickFit(row, meta) {
  if (!meta) return null;
  const reasons = [];
  const gaps = [];

  const hay = `${row.title || ""} ${row.description || ""} ${row.contracting_authority || ""}`.toLowerCase();

  // 1) Sector / capability keyword overlap (0–45)
  const kws = profileKeywords(meta);
  let hits = 0;
  const matched = [];
  for (const kw of kws) {
    if (kw && hay.includes(kw)) {
      hits++;
      if (matched.length < 4) matched.push(kw);
    }
  }
  let kwScore = 0;
  if (kws.size > 0) {
    kwScore = Math.min(45, hits * 6);
  }
  if (hits >= 1) reasons.push(`Matches your focus: ${matched.join(", ")}`);
  else gaps.push("No obvious sector/keyword overlap with your profile");

  // 2) Geography (0–20)
  let geoScore = 10;
  const tenderCountry = SOURCE_COUNTRY[row.source] || "";
  const cov = (meta.cov_country || "").toUpperCase();
  const home = (meta.country || "").toUpperCase();
  if (cov === "WORLDWIDE" || cov === "EU") {
    geoScore = 20;
    reasons.push("Within your stated market coverage");
  } else if (tenderCountry && (cov === tenderCountry || home === tenderCountry)) {
    geoScore = 20;
    reasons.push(`In your home/coverage region (${tenderCountry})`);
  } else if (tenderCountry && (home || cov)) {
    geoScore = 6;
    gaps.push(`Outside your usual region (${tenderCountry})`);
  }

  // 3) Value vs capacity (0–20)
  let valScore = 12;
  const val = parseValueNum(row);
  const turnover = parseFloat(meta.turnover || "");
  const cap = !isNaN(turnover) && turnover > 0
    ? turnover * 1_000_000
    : (ENTERPRISE_TURNOVER_GUIDE[meta.enterprise_type] || 0) * 1_000_000;
  if (val <= 0) {
    valScore = 12; // unknown value — neutral
  } else if (cap > 0) {
    const ratio = val / cap;
    if (ratio <= 0.75) { valScore = 20; reasons.push("Contract value within your capacity"); }
    else if (ratio <= 1.5) { valScore = 12; }
    else { valScore = 4; gaps.push("Contract value is large vs your turnover"); }
  }

  // 4) Deadline feasibility (0–15)
  let dlScore = 10;
  const days = row.days_until_deadline;
  const urgency = row.deadline_urgency || "unknown";
  if (urgency === "past" || (typeof days === "number" && days < 0)) {
    dlScore = 0;
    gaps.push("Submission deadline has passed");
  } else if (typeof days === "number") {
    if (days >= 14) { dlScore = 15; }
    else if (days >= 5) { dlScore = 11; }
    else { dlScore = 6; gaps.push(`Tight deadline (${days} day${days === 1 ? "" : "s"} left)`); }
  }

  let score = Math.round(kwScore + geoScore + valScore + dlScore);
  score = Math.max(0, Math.min(100, score));
  const band = score >= 80 ? "strong" : score >= 50 ? "possible" : "weak";
  return { score, band, reasons: reasons.slice(0, 4), gaps: gaps.slice(0, 4), tier: "quick" };
}

function getRowFit(row) {
  const key = rowKey(row);
  const cached = state.fitCache[key];
  if (cached?.deep) return cached.deep;
  if (cached?.quick) return cached.quick;
  const meta = getActiveProfileMeta();
  if (!meta) return null;
  const quick = computeQuickFit(row, meta);
  state.fitCache[key] = { ...(state.fitCache[key] || {}), quick };
  return quick;
}

function getQuickFit(row) {
  const key = rowKey(row);
  const cached = state.fitCache[key];
  if (cached?.quick) return cached.quick;
  const meta = getActiveProfileMeta();
  if (!meta) return null;
  const quick = computeQuickFit(row, meta);
  state.fitCache[key] = { ...(state.fitCache[key] || {}), quick };
  return quick;
}

function fitBarHtml(fit, key) {
  if (!fitActive()) return `<span class="fit-bar-empty" title="Select a profile to calculate fit score">—</span>`;
  if (!fit) return `<span class="fit-bar-empty">—</span>`;

  const score = fit.score || 0;
  const band = fit.band || (score >= 70 ? "strong" : score >= 40 ? "possible" : "weak");

  let colorClass = "fit-bar--weak";
  if (band === "strong" || score >= 70) colorClass = "fit-bar--strong";
  else if (band === "possible" || score >= 40) colorClass = "fit-bar--possible";

  const isDeep = fit.tier === "deep";
  const labelPrefix = isDeep ? "⚡ Recalculated AI Deep Score" : "Quick Fit";
  const star = isDeep ? "⚡ " : "";

  const reasons = (fit.reasons || []).map(r => '+ ' + r).join('\n');
  const gaps = (fit.gaps || []).map(g => '– ' + g).join('\n');
  // Quick Fit is a free keyword match against whatever text we have for this tender — the
  // search-results list only carries a short summary, so this number can (and often does)
  // move once you open the tender and the full description is matched instead. Said here
  // so that change reads as "more data arrived," not as the score being unstable.
  const dataNote = isDeep ? "" : "\n\n(Based on the summary shown in this list — opening the tender re-checks this against its full description.)";
  const tip = `${labelPrefix}: ${score}/100\n${reasons ? '\nReasons:\n' + reasons : ''}${gaps ? '\nGaps:\n' + gaps : ''}${dataNote}`;

  return `
    <div class="fit-bar-cell" title="${esc(tip)}">
      <span class="fit-bar-score ${colorClass}-text" style="font-weight:700;">${star}${score}</span>
      <div class="fit-bar-track">
        <div class="fit-bar-fill ${colorClass}" style="width: ${score}%"></div>
      </div>
    </div>
  `;
}

function fitQuickHtml(fit) {
  if (!fitActive()) return `<span class="fit-badge fit-badge--weak" title="Select a profile to calculate fit score">—</span>`;
  if (!fit) return `<span class="fit-badge fit-badge--weak">—</span>`;
  const dot = fit.band === "strong" ? "🟢" : fit.band === "possible" ? "🟡" : "🔴";
  const badgeClass = `fit-badge fit-badge--${fit.band} fit-badge--quick`;
  const tip = `Quick fit — ${fit.score}/100 (quick estimate)`;
  return `
    <div class="fit-quick-col" title="${esc(tip)}">
      <span class="${badgeClass}">
        <span class="fit-badge__dot">${dot}</span>
        <span class="fit-badge__score">${fit.score}</span>
      </span>
      <span class="fit-quick-sub">KEYWORD</span>
    </div>`;
}

function fitDeepHtml(fit, key) {
  if (!fitActive()) return `<span class="fit-badge fit-badge--weak">—</span>`;
  const cached = state.fitCache[key];
  if (cached?.deep) {
    const d = cached.deep;
    const label = d.band === "strong" ? "Strong" : d.band === "possible" ? "Possible" : "Weak";
    const tip = `AI deep score — ${d.score}/100 (${label} fit)\n${(d.reasons || []).map(r => '+ ' + r).join('\n')}\n${(d.gaps || []).map(g => '– ' + g).join('\n')}`;
    return `<span class="fit-badge-deep-pill fit-badge-deep-pill--${d.band}" title="${esc(tip)}">★ ${d.score}/100</span>`;
  }
  return `<span class="fit-deep-not-scored">Not scored yet</span>`;
}

function fitBadgeHtml(fit) {
  if (!fit) return "";
  const dot = fit.band === "strong" ? "🟢" : fit.band === "possible" ? "🟡" : "🔴";
  const label = fit.band === "strong" ? "Strong" : fit.band === "possible" ? "Possible" : "Weak";
  const tierMark = fit.tier === "deep" ? "★" : "";
  const tip = [
    `${label} fit — ${fit.score}/100 (${fit.tier === "deep" ? "AI deep score" : "quick estimate"})`,
    ...(fit.reasons || []).map((r) => `+ ${r}`),
    ...(fit.gaps || []).map((g) => `– ${g}`),
  ].join("\n");
  const tierClass = fit.tier === "deep" ? "fit-badge--deep" : "fit-badge--quick";
  return `<span class="fit-badge fit-badge--${fit.band} ${tierClass}" title="${esc(tip)}">`
    + `<span class="fit-badge__dot">${dot}</span>`
    + `<span class="fit-badge__score">${fit.score}${tierMark}</span></span>`;
}

function fitActive() {
  return Boolean(state.activeProfileId && getActiveProfile());
}

// The portal's own status ("Active") is not updated when the deadline passes, so a closed notice read
// "Active" next to a "Closed" badge. An open-looking status on a tender past its deadline reads "Closed".
function statusLabel(row) {
  const status = String((row && row.status) || "");
  if (/^(active|open|live)$/i.test(status.trim()) && isClosedTender(row)) return "Closed";
  return status;
}

function isClosedTender(row) {
  if (!row) return false;

  // Explicit past urgency tag
  const urgency = String(row.deadline_urgency || "").toLowerCase();
  if (urgency === "past" || urgency === "closed" || urgency === "expired") return true;

  // Days until deadline: negative number means deadline passed
  const days = row.days_until_deadline;
  if (typeof days === "number" && days < 0) return true;

  // Check if deadline date has passed via date parsing
  if (typeof isDeadlinePassed === "function" && isDeadlinePassed(row)) {
    return true;
  }

  // Comprehensive status string matching for closed/awarded tenders
  const status = String(row.status || "").toLowerCase().trim();
  if (
    status.includes("closed") ||
    status.includes("award") ||
    status.includes("complete") ||
    status.includes("cancel") ||
    status.includes("past") ||
    status.includes("archive") ||
    status.includes("expire") ||
    status.includes("terminate") ||
    status.includes("conclude") ||
    status.includes("ended") ||
    status.includes("decision") ||
    status.includes("finish") ||
    status.includes("result") ||
    status.includes("evaluate") ||
    status.includes("evaluation") ||
    status.includes("history") ||
    status.includes("historical") ||
    status.includes("unsuccessful")
  ) {
    return true;
  }

  return false;
}

function extractTextFromField(val) {
  if (!val) return "";
  if (typeof val === "string") return val;
  if (Array.isArray(val)) {
    return val.map(item => {
      if (typeof item === "string") return item;
      if (item && typeof item === "object") {
        return (item.name || item.supplier_name || item.title || JSON.stringify(item));
      }
      return String(item);
    }).join(" ");
  }
  if (typeof val === "object") {
    return (val.name || val.supplier_name || val.title || JSON.stringify(val));
  }
  return String(val);
}

function parseKeywordQuery(rawInput, defaultScope = "all") {
  const str = String(rawInput || "").trim();
  if (!str) return { query: "", scope: defaultScope || "all", hasPrefix: false };
  const prefixMatch = str.match(/^(supplier|winner|contractor|buyer|authority|title):\s*(.*)$/i);
  if (prefixMatch) {
    const rawPrefix = prefixMatch[1].toLowerCase();
    let scope = "all";
    if (["supplier", "winner", "contractor"].includes(rawPrefix)) scope = "supplier";
    else if (["buyer", "authority"].includes(rawPrefix)) scope = "buyer";
    else if (rawPrefix === "title") scope = "title";
    return {
      query: prefixMatch[2].trim(),
      scope: scope,
      hasPrefix: true
    };
  }
  return {
    query: str,
    scope: defaultScope || "all",
    hasPrefix: false
  };
}

const MATCH_ROLES = {
  title: { id: "title", label: "Matched as Title", order: 0, icon: "📄" },
  supplier: { id: "supplier", label: "Matched as Supplier / Winner", order: 1, icon: "🏆" },
  buyer: { id: "buyer", label: "Matched as Buyer / Authority", order: 2, icon: "🏛️" },
  scope: { id: "scope", label: "Matched in Description / Scope", order: 3, icon: "📝" },
  // rows a portal returned for this search whose own text does not show the word (its match is on text the list row lacks)
  portal: { id: "portal", label: "Returned by the portal", order: 4, icon: "🔎" },
};

function getRowMatchRole(row) {
  if (!row) return null;
  const r = (row._match_reason || "").toLowerCase();
  if (r === "title") return "title";
  if (r === "supplier name" || r === "subcontractor") return "supplier";
  if (r === "authority" || r === "buyer") return "buyer";
  if (r === "scope text" || r === "description") return "scope";
  if (r === "portal") return "portal";
  return null;
}

function shouldGroupMatchRoles(rows, scope, query) {
  const parsed = parseKeywordQuery(query, scope || state.keywordScope || "all");
  if (parsed.scope !== "all") return false;
  if (!parsed.query || parsed.query === "all" || parsed.query === "*") return false;
  if (!rows || rows.length < 2) return false;

  const rolesFound = new Set();
  for (const r of rows) {
    const role = getRowMatchRole(r);
    if (role) rolesFound.add(role);
    if (rolesFound.size >= 2) return true;
  }
  return false;
}

const _collapsedMatchGroups = new Set();
window.toggleMatchGroupCollapse = function (role) {
  if (_collapsedMatchGroups.has(role)) {
    _collapsedMatchGroups.delete(role);
  } else {
    _collapsedMatchGroups.add(role);
  }
  const isCollapsed = _collapsedMatchGroups.has(role);
  document.querySelectorAll(`[data-match-group-chevron="${role}"]`).forEach((el) => {
    el.classList.toggle("collapsed", isCollapsed);
  });
  document.querySelectorAll(`[data-match-group-row="${role}"]`).forEach((el) => {
    el.style.display = isCollapsed ? "none" : "";
  });
};

function getContractDuration(row) {
  if (!row) return "Not available";
  const direct = row.contract_duration_in_months_or_years_including_any_options_and_renewals ||
                 row.contract_duration ||
                 row.duration ||
                 row.duration_str;
  if (direct && String(direct).trim()) {
    const s = String(direct).trim();
    if (s.toLowerCase() !== "null" && s.toLowerCase() !== "undefined") {
      return s;
    }
  }
  if (row.duration_months != null && row.duration_months !== "" && !isNaN(row.duration_months)) {
    const m = parseInt(row.duration_months, 10);
    return m === 1 ? "1 month" : `${m} months`;
  }
  if (row.duration_days != null && row.duration_days !== "" && !isNaN(row.duration_days)) {
    const d = parseInt(row.duration_days, 10);
    if (d >= 30 && d % 30 === 0) {
      const m = Math.round(d / 30);
      return m === 1 ? "1 month" : `${m} months`;
    }
    return d === 1 ? "1 day" : `${d} days`;
  }
  const startRaw = row.contract_start_date || row.start_date || row.award_start_date;
  const endRaw = row.contract_end_date || row.end_date || row.award_end_date;
  if (startRaw && endRaw) {
    const dtStart = new Date(startRaw);
    const dtEnd = new Date(endRaw);
    if (!isNaN(dtStart.getTime()) && !isNaN(dtEnd.getTime()) && dtEnd > dtStart) {
      const diffDays = Math.round((dtEnd - dtStart) / (1000 * 60 * 60 * 24));
      const diffMonths = Math.round(diffDays / 30.4375);
      if (diffMonths >= 12 && diffMonths % 12 === 0) {
        const y = diffMonths / 12;
        return y === 1 ? "1 year" : `${y} years`;
      }
      if (diffMonths >= 1) {
        return diffMonths === 1 ? "1 month" : `${diffMonths} months`;
      }
      return `${diffDays} days`;
    }
  }
  return "Not available";
}

function getAwardDate(row) {
  if (!row) return "Not available";
  const raw = row.award_date ||
              row.contract_award_date ||
              row.date_signed ||
              row.date_awarded ||
              row.awarded_date ||
              row.award_notice_date;
  if (raw && String(raw).trim()) {
    const str = String(raw).trim().split(" ")[0].split("T")[0];
    if (str && str.toLowerCase() !== "null" && str.toLowerCase() !== "undefined") {
      return str;
    }
  }
  const isAward = (row.status || "").toLowerCase() === "awarded" ||
                  (row.notice_type || "").toLowerCase().includes("award");
  if (isAward && row.date_published) {
    const str = String(row.date_published).trim().split(" ")[0].split("T")[0];
    if (str) return str;
  }
  return "Not available";
}

function getProcurementRoute(row) {
  if (!row) return "Not available";
  const raw = row.procurement_route ||
              row.procedure ||
              row.procurement_type ||
              row.award_procedure ||
              row.procurement_method ||
              row.procurementMethodDetails;
  if (raw && String(raw).trim()) {
    const s = String(raw).trim();
    if (s.toLowerCase() !== "null" && s.toLowerCase() !== "undefined") {
      if (s.toLowerCase() === "open") return "Open competition";
      if (s.toLowerCase() === "directaward" || s.toLowerCase() === "direct_award") return "Direct award";
      return s;
    }
  }
  return "Not available";
}

function getContractValue(row) {
  if (!row) return "Not available";
  const v = row.contract_value || row.awarded_can_value || row.estimated_value_eur || row.estimated_value;
  if (v != null && String(v).trim() && String(v).trim() !== "0" && String(v).trim() !== "-1") {
    const formatted = formatValue(v, row.source);
    if (formatted) return formatted;
  }
  return "Not available";
}

function getAwardedSupplier(row) {
  if (!row) return "Not available";
  const s = row.supplier_name ||
            row.awarded_supplier ||
            row.awarded_to ||
            row.winner ||
            row.winning_bidder ||
            row.contractor ||
            row.company_name;
  if (s && String(s).trim()) {
    const str = extractTextFromField(s).trim();
    if (str && str.toLowerCase() !== "null" && str.toLowerCase() !== "undefined") {
      return str;
    }
  }
  return "Not available";
}

function getBuyerAuthority(row) {
  if (!row) return "Not available";
  const a = row.contracting_authority ||
            row.authority_name ||
            row.authority ||
            row.buyer ||
            row.buyer_name ||
            row.published_by ||
            row.customer_name;
  if (a && String(a).trim()) {
    const str = extractTextFromField(a).trim();
    if (str && str.toLowerCase() !== "null" && str.toLowerCase() !== "undefined") {
      return str;
    }
  }
  return "Not available";
}

function getActiveTableScope() {
  const rawQ = (state.q || "").trim();
  const parsed = parseKeywordQuery(rawQ, state.keywordScope || "all");
  if (parsed.scope === "supplier" || parsed.scope === "buyer") {
    return parsed.scope;
  }
  return "all";
}

