// Mirror disabled state of main panel buttons onto expand modal buttons.
function syncExpandActionButtons() {
  const states = [
    ["btnSummary", "btnExpandSummary"],
    ["btnAnalyse", "btnExpandAnalyse"],
    ["btnReadyBid", "btnExpandReadyBid"],
  ];
  for (const [srcId, dstId] of states) {
    const src = $(srcId);
    const dst = $(dstId);
    if (src && dst) dst.disabled = src.disabled;
  }
}

