// Guard flag to prevent circular input event triggers
let _isUpdatingSearchInputs = false;

$("q")?.addEventListener("keydown", (e) => {
  if (e.key === "Enter") search();
});
$("q")?.addEventListener("input", (e) => {
  if (_isUpdatingSearchInputs) return; // Prevent circular trigger
  _isUpdatingSearchInputs = true;
  
  $("q").classList.remove("input--invalid");
  state.q = e.target.value;
  syncKeywordScopeFromInput(e.target.value);
  if ($("rmSearchKeywordInput") && $("rmSearchKeywordInput").value !== e.target.value) {
    $("rmSearchKeywordInput").value = e.target.value;
  }
  if ($("rmSearchInput") && $("rmSearchInput").value !== e.target.value) {
    $("rmSearchInput").value = e.target.value;
  }
  syncSaveSearchButtonStates();
  if (typeof updateActiveChipHighlight === "function") updateActiveChipHighlight();
  if (typeof updateRightmoveResultsCount === "function") updateRightmoveResultsCount();
  
  _isUpdatingSearchInputs = false;
});
$("rmSearchKeywordInput")?.addEventListener("input", (e) => {
  if (_isUpdatingSearchInputs) return; // Prevent circular trigger
  _isUpdatingSearchInputs = true;
  
  state.q = e.target.value;
  syncKeywordScopeFromInput(e.target.value);
  if ($("q") && $("q").value !== e.target.value) {
    $("q").value = e.target.value;
  }
  if ($("rmSearchInput") && $("rmSearchInput").value !== e.target.value) {
    $("rmSearchInput").value = e.target.value;
  }
  syncSaveSearchButtonStates();
  if (typeof updateActiveChipHighlight === "function") updateActiveChipHighlight();
  if (typeof updateRightmoveResultsCount === "function") updateRightmoveResultsCount();
  
  _isUpdatingSearchInputs = false;
});
