// ── Tender Analysis ──────────────────────────────────────────────────────

function startLoadingTextRotation(elementId, messages) {
  let idx = 0;
  const interval = setInterval(() => {
    idx = (idx + 1) % messages.length;
    const el = document.getElementById(elementId);
    if (el) {
      el.innerHTML = messages[idx];
    } else {
      clearInterval(interval);
    }
  }, 3000);
  return interval;
}

let _analyseRow = null;

function openAnalyseModal(row) {
  const rkey = rowKey(row);
  const existing = state.tasks.find(t => t.id === "analysis-" + rkey);
  if (existing) {
    viewTask(existing.id);
    return;
  }
  _analyseRow = row;
  _activeModalTaskId = null;
  $("modalTitle").textContent = "Tender Clarification Analysis";
  
  const btnRun = $("btnRunAnalysis");
  if (btnRun) {
    btnRun.disabled = false;
    btnRun.textContent = "🔍 Run Clarification Analysis";
    btnRun.classList.remove("hidden");
  }
  $("btnReRunSummary")?.classList.add("hidden");
  $("btnReRunAnalysis")?.classList.add("hidden");
  $("modalBody").innerHTML = '<p class="modal-placeholder">Click Run Clarification Analysis — documents will be fetched automatically from the portal.</p>';

  // Reset inputs and uploaded files state
  state.uploadedFiles = [];
  const fileList = $("fileList");
  if (fileList) fileList.innerHTML = "";
  loadCompanyProfiles();
  const filesInput = $("tenderFiles");
  if (filesInput) filesInput.value = "";

  // Show doc status
  const docRow = $("docStatusRow");
  const source = row.source || "";
  const rid = row.resource_id || "";
  if (source && rid && source.startsWith("etenders")) {
    docRow.className = "modal__doc-status";
    docRow.innerHTML = `<span class="doc-status-loading">⏳ Checking for tender documents on portal…</span>`;
    docRow.classList.remove("hidden");
    _checkPortalDocs(source, rid, docRow);
  } else {
    docRow.classList.add("hidden");
  }
  $("analyseModal").classList.remove("hidden");
}

async function _checkPortalDocs(source, rid, docRow) {
  try {
    const res = await fetch(`/api/tender-docs/${encodeURIComponent(source)}/${encodeURIComponent(rid)}`);
    const data = await res.json();
    if (!data.supported) {
      docRow.classList.add("hidden");
      return;
    }
    if (data.count === 0) {
      docRow.innerHTML = `<span class="doc-status-none">📭 No tender documents found on portal — analysis will use description only</span>`;
    } else {
      const names = (data.docs || []).map(d => `<span class="file-chip">📄 ${esc(d.filename || d.title)}</span>`).join("");
      docRow.innerHTML = `<span class="doc-status-found">📋 ${data.count} tender document${data.count > 1 ? "s" : ""} found — will be read automatically:</span><div class="file-list" style="margin-top:6px">${names}</div>`;
    }
  } catch {
    docRow.classList.add("hidden");
  }
}

function closeAnalyseModal() {
  const taskId = _analyseRow ? "analysis-" + rowKey(_analyseRow) : null;
  const runningTask = taskId ? state.tasks.find(t => t.id === taskId && t.status === "running") : null;

  $("analyseModal").classList.add("hidden");
  const btnRun = $("btnRunAnalysis");
  if (btnRun) {
    btnRun.disabled = false;
    btnRun.textContent = "🔍 Run Clarification Analysis";
    btnRun.classList.remove("hidden");
  }
  _analyseRow = null;
  _activeModalTaskId = null;

  if (runningTask) {
    cpShowToast("Analysis is running in the background. Monitor it in the Active Tasks panel.", "info");
  }
}

async function openSummaryModal(row, isRefresh = false) {
  _analyseRow = row;
  $("modalTitle").textContent = "Tender Summary & Overview";
  $("docStatusRow").classList.add("hidden");
  $("btnRunAnalysis").classList.add("hidden");
  $("btnReRunSummary")?.classList.add("hidden");
  $("btnReRunAnalysis")?.classList.add("hidden");
  $("analyseModal").classList.remove("hidden");
  // Unlike openAnalyseModal/openBidModal, this modal previously never
  // resynced the shared "Bidding Company Profile" dropdown, so it kept
  // showing whichever company was last rendered into it instead of the
  // currently active one.
  loadCompanyProfiles();

  $("modalBody").innerHTML = `
    <div class="analysis-loading">
      <div class="shimmer-container">
        <div class="shimmer-line"></div>
        <div class="shimmer-line"></div>
        <div class="shimmer-line"></div>
        <div class="shimmer-line"></div>
      </div>
      <div style="margin-top: 15px; display: flex; flex-direction: column; align-items: center; gap: 6px;">
        <span id="summaryLoadingText" class="blink-cursor">⏳ Reading tender details...</span>
        <span id="summaryLoadingTimer" style="font-size: 12px; font-weight: 600; color: var(--primary);">Time elapsed: 0.0s</span>
      </div>
    </div>`;

  const messages = [
    "⏳ Reading tender details and metadata...",
    "🧠 Analyzing scope of work and key deliverables...",
    "🔍 Checking suitability and eligibility criteria...",
    "📝 Structuring the summary dashboard...",
    "✨ Polishing output format..."
  ];
  const textInterval = startLoadingTextRotation("summaryLoadingText", messages);

  const startTime = Date.now();
  const timerInterval = setInterval(() => {
    const elapsed = ((Date.now() - startTime) / 1000).toFixed(1);
    const timerEl = $("summaryLoadingTimer");
    if (timerEl) {
      timerEl.textContent = `Time elapsed: ${elapsed}s`;
    }
  }, 100);

  try {
    let activeRow = { ...row };
    if (isRefresh) {
      try {
        const source = row.source;
        const rid = row.resource_id;
        if (source && rid) {
          const langParam = state.lang ? `?lang=${state.lang}` : "";
          const refreshUrl = `/api/tender/${encodeURIComponent(source)}/${encodeURIComponent(rid)}${langParam}${langParam ? '&' : '?'}refresh=1`;
          const detailsRes = await fetch(refreshUrl);
          if (detailsRes.ok) {
            const freshData = await detailsRes.json();
            activeRow = { ...row, ...freshData };
            _analyseRow = activeRow;
          }
        }
      } catch (e) {
        console.warn("Failed to fetch fresh tender details for summary:", e);
      }
    }

    const langParam = state.lang ? `?lang=${state.lang}` : "";
    const res = await fetch(`/api/summary${langParam}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ tender: activeRow, refresh: isRefresh }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Failed to generate summary");
    refreshCredits();

    $("modalBody").innerHTML = renderSummary(data.summary, activeRow);
  } catch (err) {
    $("modalBody").innerHTML = `<p style="color:#b91c1c;padding:10px 0">Error: ${esc(String(err))}</p>`;
  } finally {
    clearInterval(textInterval);
    clearInterval(timerInterval);
  }
}

