async function runAnalysis() {
  if (!_analyseRow) return;
  const company = ($("companyName")?.value || "").trim();
  const files = state.uploadedFiles || [];

  const taskId = "analysis-" + rowKey(_analyseRow);
  if (state.tasks.find(t => t.id === taskId && t.status === "running")) {
    await showAlert("An analysis is already running for this tender.");
    return;
  }

  state.tasks = state.tasks.filter(t => t.id !== taskId);

  const task = {
    id: taskId,
    type: "analysis",
    title: _analyseRow.title || "Custom Tender",
    row: { ..._analyseRow },
    company,
    files,
    status: "running",
    stage: 1,
    message: "Downloading and parsing tender documents...",
    elapsedSeconds: 0,
    startTime: Date.now(),
    analysis: null,
    docs_found: 0,
    docs_used: [],
    error: null
  };

  state.tasks.push(task);

  const panel = $("tasksPanel");
  if (panel) {
    state.tasksPanelUserClosed = false;
    panel.classList.remove("hidden");
    panel.classList.remove("tasks-panel--collapsed");
    const chevron = $("tasksPanelChevron");
    if (chevron) chevron.textContent = "▼";
  }
  updateTasksUI();

  const btn = $("btnRunAnalysis");
  if (btn) {
    btn.disabled = true;
    btn.textContent = "Analysing…";
  }

  _activeModalTaskId = task.id;
  updateActiveModalAnalysisProgress(task);
  executeAnalysisTask(task);
}

async function executeAnalysisTask(task) {
  const timerInterval = setInterval(() => {
    task.elapsedSeconds = (Date.now() - task.startTime) / 1000;
    updateTasksUI();
    if (_activeModalTaskId === task.id) {
      // Only update the timer text — avoid full innerHTML replace to prevent flickering
      const timerEl = document.getElementById("analysisProgressTimer");
      if (timerEl) {
        timerEl.textContent = `Time elapsed: ${task.elapsedSeconds.toFixed(1)}s`;
      } else {
        // Structure not yet built, do a full render
        updateActiveModalAnalysisProgress(task);
      }
    }
  }, 100);

  const messages = [
    "⏳ Downloading and parsing tender documents...",
    "🧠 Dissecting evaluation criteria and weightings...",
    "🔍 Scanning for mandatory vs. desirable requirements...",
    "📝 Compiling checklist items and signable forms...",
    "💡 Formulating strategic bidder advice...",
    "✨ Preparing full analysis report..."
  ];
  let msgIdx = 0;
  const rotateInterval = setInterval(() => {
    if (task.status === "running") {
      msgIdx = (msgIdx + 1) % messages.length;
      task.message = messages[msgIdx];
      updateTasksUI();
      if (_activeModalTaskId === task.id) {
        // Update just the message text node to avoid flickering
        const msgEl = document.getElementById("analysisProgressMsg");
        if (msgEl) {
          msgEl.textContent = task.message;
        } else {
          updateActiveModalAnalysisProgress(task);
        }
      }
    }
  }, 3500);

  try {
    const langParam = state.lang ? `?lang=${state.lang}` : "";
    const res = await fetch(`/api/analyse${langParam}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ tender: task.row, company: task.company, files: task.files }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Analysis failed");

    task.analysis = data.analysis;
    task.docs_found = data.docs_found || 0;
    task.docs_used = data.docs_used || [];
    task.elapsedSeconds = (Date.now() - task.startTime) / 1000;
    task.status = "completed";
    updateTasksUI();

    if (_activeModalTaskId === task.id) {
      state.lastAnalysis = task.analysis;
      state.questionnaireAnswers = {};
      $("modalBody").innerHTML = renderAnalysis(task.analysis, task.row, task.docs_found, task.docs_used);
      wireQuestionnaireButtons();
      $("btnRunAnalysis")?.classList.add("hidden");
      const btnReRun = $("btnReRunAnalysis");
      if (btnReRun) {
        btnReRun.classList.remove("hidden");
        btnReRun.disabled = false;
        btnReRun.textContent = "🔄 Re-run Analysis";
        btnReRun.onclick = () => {
          reRunAnalysis(task.row, task.company, task.files);
        };
      }
    }
    refreshCredits();
  } catch (err) {
    task.elapsedSeconds = (Date.now() - task.startTime) / 1000;
    task.status = "failed";
    task.error = String(err.message || err);
    updateTasksUI();
    if (_activeModalTaskId === task.id) {
      $("modalBody").innerHTML = `
        <div style="background:#fef2f2;border:1px solid #fca5a5;padding:16px;border-radius:8px;margin-top:10px;">
          <p style="color:#b91c1c;margin:0 0 12px 0;font-weight:600;font-size:14px;line-height:1.5;">Error: ${esc(task.error)}</p>
          <button id="btnRetryAnalysis" class="btn btn--primary" style="display:inline-flex;align-items:center;gap:6px;font-size:13px;padding:6px 14px;">🔄 Retry Analysis</button>
        </div>`;
      $("btnRetryAnalysis")?.addEventListener("click", () => {
        runAnalysis();
      });
      const btn = $("btnRunAnalysis");
      if (btn) {
        btn.disabled = false;
        btn.textContent = "🔍 Run Clarification Analysis";
      }
    }
  } finally {
    clearInterval(timerInterval);
    clearInterval(rotateInterval);
    updateTasksUI();
  }
}

function updateActiveModalAnalysisProgress(task) {
  // If the progress structure already exists, only update text nodes (avoids flicker)
  const existingMsg = document.getElementById("analysisProgressMsg");
  if (existingMsg) {
    existingMsg.textContent = task.message;
    const timerEl = document.getElementById("analysisProgressTimer");
    if (timerEl) timerEl.textContent = `Time elapsed: ${task.elapsedSeconds.toFixed(1)}s`;
    return;
  }
  // First render: build the full structure
  $("modalBody").innerHTML = `
    <div class="analysis-loading">
      <div class="shimmer-container">
        <div class="shimmer-line"></div>
        <div class="shimmer-line"></div>
        <div class="shimmer-line"></div>
        <div class="shimmer-line"></div>
      </div>
      <div style="margin-top: 15px; display: flex; flex-direction: column; align-items: center; gap: 6px;">
        <span id="analysisProgressMsg" class="blink-cursor">${esc(task.message)}</span>
        <span id="analysisProgressTimer" style="font-size: 12px; font-weight: 600; color: var(--primary);">Time elapsed: ${task.elapsedSeconds.toFixed(1)}s</span>
        <button type="button" class="btn btn--small" onclick="closeAnalyseModal()" style="margin-top: 10px;">Run in Background</button>
      </div>
    </div>`;
}

async function handleFileSelect(e) {
  const files = e.target.files;
  if (!files || !files.length) return;

  const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB

  for (let i = 0; i < files.length; i++) {
    const file = files[i];
    if (file.size > MAX_FILE_SIZE) {
      await showAlert(`File ${file.name} is too large. Max size is 5MB.`);
      continue;
    }

    const reader = new FileReader();
    reader.onload = function (evt) {
      const arrayBuffer = evt.target.result;
      let binary = "";
      const bytes = new Uint8Array(arrayBuffer);
      const len = bytes.byteLength;
      for (let j = 0; j < len; j++) {
        binary += String.fromCharCode(bytes[j]);
      }
      const base64 = btoa(binary);
      if (!state.uploadedFiles.some(f => f.filename === file.name)) {
        state.uploadedFiles.push({
          filename: file.name,
          content: base64
        });
        renderUploadedFiles();
      }
    };
    reader.readAsArrayBuffer(file);
  }
  e.target.value = "";
}

function renderUploadedFiles() {
  const container = $("fileList");
  if (!container) return;
  container.innerHTML = "";
  state.uploadedFiles.forEach((file, index) => {
    const chip = document.createElement("div");
    chip.className = "file-chip";
    chip.innerHTML = `${esc(file.filename)} <span class="remove-file" data-index="${index}" style="margin-left: 6px; cursor: pointer; font-weight: bold; color: #b91c1c;">×</span>`;
    container.appendChild(chip);
  });
  container.querySelectorAll(".remove-file").forEach(btn => {
    btn.addEventListener("click", (e) => {
      const index = parseInt(e.target.dataset.index);
      state.uploadedFiles.splice(index, 1);
      renderUploadedFiles();
    });
  });
}

function renderAnalysis(a, row, docCount = 0, docNames = []) {
  const modalTitle = $("modalTitle");
  if (modalTitle) {
    modalTitle.textContent = "Tender Clarification Analysis";
  }

  let html = getDeadlinePassedBannerHtml(row);

  if (docCount > 0) {
    const names = docNames.map(n => `<span class="file-chip">📄 ${esc(n)}</span>`).join("");
    html += `<div class="analysis-doc-badge">📋 Analysis based on <strong>${docCount}</strong> tender document${docCount > 1 ? "s" : ""} fetched from portal${names ? `:<div class="file-list" style="margin-top:6px">${names}</div>` : ""}</div>`;
  } else {
    html += `<div class="analysis-doc-badge analysis-doc-badge--none">ℹ️ No tender documents found on portal — analysis based on tender description</div>`;
  }

  if (a.submission_instructions) {
    const where = a.submission_instructions.where_to_submit || "Not specified in the tender documents";
    const how = a.submission_instructions.how_to_submit || "Not specified in the tender documents";
    html += `<div class="clarification-instructions">
      <h3 style="margin-top: 0; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--muted); margin-bottom: 10px;">How & Where to Submit Clarification Questions</h3>
      <div class="instructions-grid">
        <div class="instruction-card">
          <div class="instruction-card__title">📬 Where to Submit</div>
          <div class="instruction-card__content">${esc(where)}</div>
        </div>
        <div class="instruction-card">
          <div class="instruction-card__title">🛠️ How to Submit</div>
          <div class="instruction-card__content">${esc(how)}</div>
        </div>
      </div>
    </div>`;
  } else {
    html += `<div class="clarification-instructions">
      <h3 style="margin-top: 0; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--muted); margin-bottom: 10px;">How & Where to Submit Clarification Questions</h3>
      <div class="instruction-card__content" style="font-style: italic; color: var(--muted); font-size: 13px;">
        Submission instructions are not available for this cached analysis. Run a new analysis to extract submission details from the documents.
      </div>
    </div>`;
  }

  // Executive Summary
  if (a.executive_summary) {
    html += `<div class="analysis-section">
      <h3>Executive Summary</h3>
      <div class="analysis-summary" style="margin-bottom: 0; color: #1e293b; border-color: #cbd5e1; background-color: #f8fafc;">${esc(a.executive_summary)}</div>
    </div>`;
  }

  // Validation Checklist Matrix
  if (a.checklist && Object.keys(a.checklist).length > 0) {
    html += `<div class="analysis-section">
      <h3>📋 Tender Validation Checklist</h3>
      <div style="display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 8px; margin-top: 8px;">`;
    for (const [key, val] of Object.entries(a.checklist)) {
      let badgeStyle = "background: #f1f5f9; color: #475569; border: 1px solid #cbd5e1;";
      let statusIcon = "🟡";
      const lower = String(val).toLowerCase();
      if (lower.includes("fully") || lower.includes("clear") || lower.includes("defined") || lower.includes("available") || lower.includes("specified")) {
        badgeStyle = "background: #f0fdf4; color: #166534; border: 1px solid #bbf7d0;";
        statusIcon = "🟢";
      } else if (lower.includes("not") || lower.includes("none") || lower.includes("missing")) {
        badgeStyle = "background: #fef2f2; color: #991b1b; border: 1px solid #fecaca;";
        statusIcon = "🔴";
      }
      html += `
        <div style="padding: 8px 12px; border-radius: 6px; font-size: 11.5px; ${badgeStyle} display: flex; justify-content: space-between; align-items: center;">
          <strong style="font-weight: 700;">${esc(key)}</strong>
          <span style="font-size: 10.5px; font-weight: 600;">${statusIcon} ${esc(val)}</span>
        </div>
      `;
    }
    html += `</div></div>`;
  }

  // Clarification Questions Table
  if (a.questions_table && a.questions_table.length) {
    html += `<div class="analysis-section">
      <h3>Clarification Questions (${a.questions_table.length})</h3>
      <div style="overflow-x: auto;">
        <table class="clarification-table">
          <thead>
            <tr>
              <th style="width: 40px; text-align: center;">No.</th>
              <th style="width: 85px; text-align: center;">Priority</th>
              <th style="width: 140px;">Category & Agent</th>
              <th style="width: 140px;">Reference</th>
              <th>Issue / Gap Identified</th>
              <th>Clarification Question</th>
              <th style="width: 160px;">Business Rationale / Impact</th>
            </tr>
          </thead>
          <tbody>`;
    a.questions_table.forEach(q => {
      let priorityStyle = "background: #fef3c7; color: #92400e; border: 1px solid #fde68a;";
      const p = (q.priority || "Medium").toLowerCase();
      if (p === "critical") {
        priorityStyle = "background: #fef2f2; color: #991b1b; border: 1px solid #fca5a5;";
      } else if (p === "high") {
        priorityStyle = "background: #fff7ed; color: #c2410c; border: 1px solid #ffedd5;";
      } else if (p === "low") {
        priorityStyle = "background: #f1f5f9; color: #475569; border: 1px solid #cbd5e1;";
      }

      const agentBadge = q.agent ? `<div style="font-size: 9px; color: #475569; font-weight: 600; margin-top: 2px;">👤 ${esc(q.agent)}</div>` : "";
      const subCat = q.sub_category ? `<div style="font-size: 9.5px; color: #64748b; font-style: italic;">${esc(q.sub_category)}</div>` : "";
      const rationaleText = q.bid_impact || q.priority_reason || "";

      html += `<tr>
        <td style="font-weight: 700; text-align: center;">${esc(q.no)}</td>
        <td style="text-align: center;">
          <span style="display:inline-block;padding:2px 6px;border-radius:4px;font-size:9.5px;font-weight:800;text-transform:uppercase;${priorityStyle}">${esc(q.priority || "Medium")}</span>
        </td>
        <td>
          <span class="category-badge">${esc(q.category)}</span>
          ${subCat}
          ${agentBadge}
        </td>
        <td style="font-style: italic; color: #475569;">${esc(q.reference)}</td>
        <td>${esc(q.issue)}</td>
        <td style="font-weight: 600; color: #1e3a8a;">${esc(q.question)}</td>
        <td style="font-size: 11px; color: #334155;">${esc(rationaleText)}</td>
      </tr>`;
    });
    html += `</tbody>
        </table>
      </div>
    </div>`;
  }

  // Priority Questions
  if (a.priority_questions) {
    const hasCrit = a.priority_questions.critical && a.priority_questions.critical.length;
    const hasHigh = a.priority_questions.high && a.priority_questions.high.length;
    const hasMed = a.priority_questions.medium && a.priority_questions.medium.length;

    if (hasCrit || hasHigh || hasMed) {
      html += `<div class="analysis-section">
        <h3>Priority Questions Overview</h3>
        <div class="priority-list">`;
      if (hasCrit) {
        a.priority_questions.critical.forEach(q => {
          html += `<div class="priority-item priority-item--critical">
            <span class="risk-badge risk-badge--high" style="margin-top: 0;">Critical</span>
            <div style="font-weight: 600; color: #991b1b; font-size: 12px; line-height: 1.4;">${esc(q)}</div>
          </div>`;
        });
      }
      if (hasHigh) {
        a.priority_questions.high.forEach(q => {
          html += `<div class="priority-item priority-item--high">
            <span class="risk-badge risk-badge--medium" style="margin-top: 0;">High</span>
            <div style="font-weight: 600; color: #9a3412; font-size: 12px; line-height: 1.4;">${esc(q)}</div>
          </div>`;
        });
      }
      if (hasMed) {
        a.priority_questions.medium.forEach(q => {
          html += `<div class="priority-item priority-item--medium">
            <span class="risk-badge risk-badge--low" style="margin-top: 0; background: #e2e8f0; color: #475569;">Medium</span>
            <div style="font-weight: 600; color: #44403c; font-size: 12px; line-height: 1.4;">${esc(q)}</div>
          </div>`;
        });
      }
      html += `</div></div>`;
    }
  }

  // Questions to Avoid
  if (a.questions_to_avoid && a.questions_to_avoid.length) {
    html += `<div class="analysis-section">
      <h3>Questions to Avoid (Already Answered in Documents)</h3>
      <div class="avoid-box">`;
    a.questions_to_avoid.forEach(q => {
      html += `<div class="avoid-item">
        <div style="font-weight: 600; color: #64748b; text-decoration: line-through; font-size: 12px;">${esc(q.question)}</div>
        <div style="font-size: 11px; margin-top: 6px; color: #0f766e; background: #f0fdfa; border: 1px solid #ccfbf1; padding: 6px 10px; border-radius: 6px; line-height: 1.4;">
          <strong>Answered in:</strong> ${esc(q.answered_in)}<br>
          <strong>Answer:</strong> ${esc(q.answer)}
        </div>
      </div>`;
    });
    html += `</div></div>`;
  }

  // Final Recommended Clarification Document (Draft Letter)
  if (a.final_draft) {
    html += `<div class="analysis-section">
      <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;">
        <h3 style="margin: 0; font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--muted);">Final Recommended Clarification Document</h3>
        <div style="display: flex; gap: 8px;">
          <button id="btnCopyQuestionnaire" class="btn btn--small" style="padding: 4px 8px; font-size: 11px; border-radius: 6px; font-weight: 600;">📋 Copy Draft</button>
          <button id="btnDownloadQuestionnaire" class="btn btn--small" style="padding: 4px 8px; font-size: 11px; border-radius: 6px; font-weight: 600;">📥 Download (.docx)</button>
        </div>
      </div>
      <div class="draft-box" id="draftBox">${esc(a.final_draft)}</div>
    </div>`;
  }

  return html;
}

function wireQuestionnaireButtons() {
  $("btnCopyQuestionnaire")?.addEventListener("click", () => {
    copyQuestionnaireToClipboard();
  });
  $("btnDownloadQuestionnaire")?.addEventListener("click", () => {
    downloadQuestionnaireDoc();
  });
}

async function copyQuestionnaireToClipboard() {
  if (!_analyseRow || !state.lastAnalysis?.final_draft) return;
  const text = state.lastAnalysis.final_draft;

  const showSuccess = () => {
    const btn = $("btnCopyQuestionnaire");
    if (btn) {
      const old = btn.textContent;
      btn.textContent = "✓ Copied!";
      setTimeout(() => { btn.textContent = old; }, 2000);
    }
  };

  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(showSuccess).catch(() => fallbackCopy(text));
  } else {
    await fallbackCopy(text);
  }

  async function fallbackCopy(str) {
    const textArea = document.createElement("textarea");
    textArea.value = str;
    textArea.style.position = "fixed";
    textArea.style.top = "0";
    textArea.style.left = "0";
    textArea.style.opacity = "0";
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();
    try {
      const successful = document.execCommand('copy');
      if (successful) showSuccess();
      else await showAlert("Failed to copy to clipboard.");
    } catch (err) {
      await showAlert("Failed to copy to clipboard.");
    }
    document.body.removeChild(textArea);
  }
}

async function downloadQuestionnaireDoc() {
  if (!_analyseRow || !state.lastAnalysis?.final_draft) return;
  const title = _analyseRow.title || "Unknown Tender";
  const authority = _analyseRow.contracting_authority || "Unknown Authority";

  try {
    const res = await fetch("/api/download-questionnaire", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: title,
        authority: authority,
        final_draft: state.lastAnalysis.final_draft
      })
    });
    if (!res.ok) {
      throw new Error(`Failed to generate DOCX (${res.status})`);
    }
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    const sanitizedTitle = title.replace(/[^a-z0-9]/gi, '_').toLowerCase();
    a.download = `${sanitizedTitle}_clarifications.docx`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  } catch (err) {
    await showAlert("Failed to download DOCX: " + err.message);
  }
}

function updateReadiness(answers) {
  const total = document.querySelectorAll(".q-item").length;
  if (!total) return;
  const yesCount = Object.values(answers).filter(v => v === "yes").length;
  const pct = Math.round((yesCount / total) * 100);
  const fill = $("readinessFill");
  const label = $("readinessLabel");
  if (fill) {
    fill.style.width = pct + "%";
    fill.style.background = pct >= 80 ? "#16a34a" : pct >= 50 ? "#d97706" : "#b91c1c";
  }
  if (label) {
    const answered = Object.keys(answers).length;
    label.textContent = answered < total
      ? `${answered}/${total} answered — ${pct}% ready`
      : pct >= 80
        ? `${pct}% ready — Strong position to bid`
        : pct >= 50
          ? `${pct}% ready — Address gaps before bidding`
          : `${pct}% ready — Significant gaps, consider carefully`;
  }
}

