// ── Date Filter Preset Pills & Slider Helper Functions & Event Handlers ──

function syncAllDatePills(preset) {
  state.dateFilterPreset = preset || "all";
  const containers = [$("datePillsContainer"), $("rmDatePills")].filter(Boolean);
  containers.forEach(container => {
    const pills = container.querySelectorAll(".pill, .rm-pill");
    pills.forEach(p => {
      const days = p.dataset.days || "all";
      if (days === state.dateFilterPreset) {
        p.classList.add("active");
      } else {
        p.classList.remove("active");
      }
    });
  });

  const sliderContainers = [$("customSliderContainer"), $("rmCustomSliderContainer")].filter(Boolean);
  if (state.dateFilterPreset === "custom") {
    sliderContainers.forEach(sc => sc.classList.remove("hidden"));
    state.dateFilterActive = true;
    updateDateSliderBounds();
    const rmContainer = $("rmCustomSliderContainer");
    if (rmContainer && !rmContainer.classList.contains("hidden")) {
      setTimeout(() => {
        rmContainer.scrollIntoView({ behavior: "smooth", block: "nearest" });
      }, 50);
    }
  } else {
    sliderContainers.forEach(sc => sc.classList.add("hidden"));
    state.dateFilterActive = state.dateFilterPreset !== "all";
    state.dateFilterValueMin = null;
    state.dateFilterValueMax = null;
  }

  if (typeof updateExplanationText === "function") updateExplanationText();
  if (typeof renderRows === "function") renderRows();
  if (typeof updateRightmoveResultsCount === "function") updateRightmoveResultsCount();
  if (typeof updateResultsTotal === "function") updateResultsTotal();
  if (typeof updateFiltersPanelSummary === "function") updateFiltersPanelSummary();
}

function initDatePills() {
  const containers = [$("datePillsContainer"), $("rmDatePills")].filter(Boolean);
  if (containers.length === 0) return;

  containers.forEach(container => {
    const pills = container.querySelectorAll(".pill, .rm-pill");
    pills.forEach(pill => {
      pill.addEventListener("click", () => {
        const days = pill.dataset.days || "all";
        const isAlreadyActive = pill.classList.contains("active") && days !== "all";
        const newPreset = isAlreadyActive ? "all" : days;
        syncAllDatePills(newPreset);
      });
    });
  });
}

function updateExplanationText() {
  const el = $("filterExplanation");
  if (!el) return;
  if (state.dateFilterPreset === "all") {
    el.textContent = "Showing all tenders";
  } else if (state.dateFilterPreset === "custom") {
    const sliderStart = $("dateSliderStart");
    const sliderEnd = $("dateSliderEnd");
    if (sliderStart && sliderEnd && state.dateFilterActive && state.dateFilterValueMin !== null && state.dateFilterValueMax !== null) {
      const dStart = new Date(state.dateFilterValueMin);
      const dEnd = new Date(state.dateFilterValueMax);
      const fmtStart = dStart.toLocaleDateString("en-GB", { day: 'numeric', month: 'short', year: 'numeric' });
      const fmtEnd = dEnd.toLocaleDateString("en-GB", { day: 'numeric', month: 'short', year: 'numeric' });
      el.textContent = `Showing tenders: ${state.dateFilterType === "published" ? "published" : "deadline"} from ${fmtStart} to ${fmtEnd}`;
    } else {
      el.textContent = `Showing all tenders (custom date range)`;
    }
  } else {
    el.textContent = `Showing tenders: ${state.dateFilterType === "published" ? "published" : "deadline"} within ${state.dateFilterPreset} days`;
  }
  updateFiltersPanelSummary();
}

function updateDateSliderBounds() {
  const dateType = $("dateFilterType")?.value || "deadline";
  state.dateFilterType = dateType;

  // Update label text
  const labelEl = $("datePillsLabel");
  if (labelEl) {
    labelEl.textContent = dateType === "published"
      ? "Published within"
      : "Deadline within";
  }

  // Extract all valid dates from state.rows
  const dates = (state.rows || []).map(row => {
    const dateStr = dateType === "published"
      ? row.date_published
      : (row.deadline_date || row.submission_deadline);
    return parseDate(dateStr);
  }).filter(Boolean);

  const sliderStart = $("dateSliderStart");
  const sliderEnd = $("dateSliderEnd");

  if (!sliderStart || !sliderEnd) return;

  let minTime, maxTime;
  if (dates.length > 0) {
    const timestamps = dates.map(d => d.getTime());
    minTime = Math.min(...timestamps);
    maxTime = Math.max(...timestamps);
  } else {
    const now = new Date();
    minTime = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
    maxTime = minTime + (30 * 24 * 60 * 60 * 1000);
  }

  // Set sliders min/max/step
  sliderStart.min = minTime;
  sliderStart.max = maxTime;
  sliderStart.step = 24 * 60 * 60 * 1000;

  sliderEnd.min = minTime;
  sliderEnd.max = maxTime;
  sliderEnd.step = 24 * 60 * 60 * 1000;

  // If slider values haven't been set, or are out of bounds
  if (state.dateFilterValueMin === null || state.dateFilterValueMin < minTime || state.dateFilterValueMin > maxTime) {
    sliderStart.value = minTime;
    state.dateFilterValueMin = minTime;
  } else {
    sliderStart.value = state.dateFilterValueMin;
  }

  if (state.dateFilterValueMax === null || state.dateFilterValueMax < minTime || state.dateFilterValueMax > maxTime) {
    sliderEnd.value = maxTime;
    state.dateFilterValueMax = maxTime;
  } else {
    sliderEnd.value = state.dateFilterValueMax;
  }

  // Update slider container visibility
  const sliderContainer = $("customSliderContainer");
  if (sliderContainer) {
    if (state.dateFilterPreset === "custom") {
      sliderContainer.classList.remove("hidden");
    } else {
      sliderContainer.classList.add("hidden");
    }
  }

  updateDateSliderDisplay();
  updateExplanationText();
}

function updateDateSliderDisplay() {
  const sliderStart = $("dateSliderStart");
  const sliderEnd = $("dateSliderEnd");
  const valStartSpan = $("dateSliderStartVal");
  const valEndSpan = $("dateSliderEndVal");
  if (!sliderStart || !sliderEnd || !valStartSpan || !valEndSpan) return;
  const valStart = parseInt(sliderStart.value);
  const valEnd = parseInt(sliderEnd.value);

  const dStart = new Date(valStart);
  const fmtStart = dStart.toLocaleDateString("en-GB", { day: 'numeric', month: 'short', year: 'numeric' });
  valStartSpan.textContent = fmtStart;

  const dEnd = new Date(valEnd);
  const fmtEnd = dEnd.toLocaleDateString("en-GB", { day: 'numeric', month: 'short', year: 'numeric' });
  valEndSpan.textContent = fmtEnd;

  // Update dynamic floating tooltips above the thumbs
  const tooltipStart = $("dateSliderStartTooltip");
  const tooltipEnd = $("dateSliderEndTooltip");
  if (tooltipStart && tooltipEnd) {
    const min = parseInt(sliderStart.min) || valStart;
    const max = parseInt(sliderStart.max) || valEnd;
    const range = max - min || 1;
    const startPercent = ((valStart - min) / range) * 100;
    const endPercent = ((valEnd - min) / range) * 100;

    tooltipStart.textContent = fmtStart;
    tooltipStart.style.left = `calc(${startPercent}% + ${(8 - startPercent * 0.16)}px)`;

    tooltipEnd.textContent = fmtEnd;
    tooltipEnd.style.left = `calc(${endPercent}% + ${(8 - endPercent * 0.16)}px)`;

    // Avoid overlap if thumbs are close
    const isClose = (endPercent - startPercent) < 15;
    if (isClose) {
      tooltipEnd.style.bottom = "42px";
    } else {
      tooltipEnd.style.bottom = "24px";
    }
    tooltipStart.style.bottom = "24px";
  }

  const btnReset = $("btnResetDate");
  if (btnReset) {
    const isDefault = valStart === parseInt(sliderStart.min) && valEnd === parseInt(sliderEnd.max);
    btnReset.disabled = !state.dateFilterActive || isDefault;
  }
}

// Wire date slider events
function handleDateSliderStartInput(e) {
  const val = parseInt(e.target.value);
  const maxVal = state.dateFilterValueMax || val;
  if (val > maxVal) {
    e.target.value = maxVal;
    state.dateFilterValueMin = maxVal;
  } else {
    state.dateFilterValueMin = val;
  }
  state.dateFilterActive = true;
  [$("dateSliderStart"), $("rmDateSliderStart")].forEach(s => { if (s) s.value = state.dateFilterValueMin; });
  updateDateSliderDisplay();
  updateExplanationText();
  renderRows();
  updateResultsTotal();
}

function handleDateSliderEndInput(e) {
  const val = parseInt(e.target.value);
  const minVal = state.dateFilterValueMin || val;
  if (val < minVal) {
    e.target.value = minVal;
    state.dateFilterValueMax = minVal;
  } else {
    state.dateFilterValueMax = val;
  }
  state.dateFilterActive = true;
  [$("dateSliderEnd"), $("rmDateSliderEnd")].forEach(s => { if (s) s.value = state.dateFilterValueMax; });
  updateDateSliderDisplay();
  updateExplanationText();
  renderRows();
  updateResultsTotal();
}

$("dateSliderStart")?.addEventListener("input", handleDateSliderStartInput);
$("rmDateSliderStart")?.addEventListener("input", handleDateSliderStartInput);
$("dateSliderEnd")?.addEventListener("input", handleDateSliderEndInput);
$("rmDateSliderEnd")?.addEventListener("input", handleDateSliderEndInput);

$("dateFilterType")?.addEventListener("change", () => {
  // Reset active pill to "All" when filter type changes
  const container = $("datePillsContainer");
  if (container) {
    container.querySelectorAll(".pill").forEach(p => {
      if (p.dataset.days === "all") p.classList.add("active");
      else p.classList.remove("active");
    });
  }
  state.dateFilterPreset = "all";
  state.dateFilterActive = false;
  state.dateFilterValueMin = null;
  state.dateFilterValueMax = null;

  updateDateSliderBounds();
  renderRows();
  updateResultsTotal();
});

$("btnResetDate")?.addEventListener("click", () => {
  const container = $("datePillsContainer");
  if (container) {
    container.querySelectorAll(".pill").forEach(p => {
      if (p.dataset.days === "all") p.classList.add("active");
      else p.classList.remove("active");
    });
  }
  state.dateFilterPreset = "all";
  state.dateFilterActive = false;
  state.dateFilterValueMin = null;
  state.dateFilterValueMax = null;

  const sliderStart = $("dateSliderStart");
  if (sliderStart) {
    sliderStart.value = sliderStart.min;
  }
  const sliderEnd = $("dateSliderEnd");
  if (sliderEnd) {
    sliderEnd.value = sliderEnd.max;
  }

  const sliderContainer = $("customSliderContainer");
  if (sliderContainer) {
    sliderContainer.classList.add("hidden");
  }

  updateDateSliderDisplay();
  updateExplanationText();
  renderRows();
  updateResultsTotal();
});

function initStatusPills() {
  const chkOpp = $("chkOpportunities");
  const chkAwarded = $("chkAwarded");
  if (!chkOpp || !chkAwarded) return;

  const currentFilter = state.statusFilter || lsGet(LS_STATUS_FILTER, "opportunities");
  state.statusFilter = currentFilter;
  syncStatusFilterUI();

  const updateStatusFilter = () => {
    if (chkOpp.checked && chkAwarded.checked) {
      state.statusFilter = "all";
    } else if (chkOpp.checked) {
      state.statusFilter = "opportunities";
    } else if (chkAwarded.checked) {
      state.statusFilter = "awards";
    } else {
      state.statusFilter = "none";
    }
    lsSet(LS_STATUS_FILTER, state.statusFilter);
    savePrefsToServer({ status_filter: state.statusFilter });
    renderRows();
    updateResultsTotal();
  };

  chkOpp.removeEventListener("change", updateStatusFilter);
  chkAwarded.removeEventListener("change", updateStatusFilter);
  chkOpp.addEventListener("change", updateStatusFilter);
  chkAwarded.addEventListener("change", updateStatusFilter);
}

// Auto-run on script load to sync status filter checkboxes
initStatusPills();

function initValueRangeStep() {
  const valMin = $("valueMin");
  const valMax = $("valueMax");
  const forceMin1000 = (input) => {
    input.addEventListener("keydown", (e) => {
      if (e.key === "ArrowUp" && !input.value) {
        e.preventDefault();
        input.value = 1000;
        input.dispatchEvent(new Event("input"));
      }
    });
  };
  if (valMin) forceMin1000(valMin);
  if (valMax) forceMin1000(valMax);
}

// Run pill initialization
initDatePills();
initStatusPills();
initValueRangeStep();

// ── Fit Score controls (Phase 2) ──────────────────────────────────────────
function populateFitProfileSelect() {
  const sel = $("fitProfileSelect");
  const rmSel = $("rmCompanyProfileSelect");
  const selects = [sel, rmSel].filter(Boolean);
  if (selects.length === 0) return;
  const defaultProf = (state.companyProfiles || []).find(p => p.is_default) || (state.companyProfiles || [])[0];
  const defaultId = defaultProf ? String(defaultProf.id) : "";
  // The saved default decides what a visit starts with (the remembered "active" profile can be stale);
  // once the user picks a profile during the visit, that pick stands.
  const prev = (state.profileChosenThisVisit ? state.activeProfileId : "") || defaultId || state.activeProfileId || "";
  const hasProfiles = state.companyProfiles && state.companyProfiles.length > 0;
  selects.forEach(s => {
    s.innerHTML = hasProfiles
      ? '<option value="">Select Company Profile</option>'
      : '<option value="">None — select to score</option>';
    for (const p of state.companyProfiles || []) {
      const opt = document.createElement("option");
      opt.value = p.id;
      opt.textContent = p.is_default ? `${p.name} (Default)` : p.name;
      s.appendChild(opt);
    }
    const addOpt = document.createElement("option");
    addOpt.value = "__add_new__";
    addOpt.textContent = "＋ Add new profile...";
    s.appendChild(addOpt);
  });

  if ((state.companyProfiles || []).some((p) => String(p.id) === String(prev))) {
    state.activeProfileId = String(prev);
    selects.forEach(s => s.value = String(prev));
  } else if (defaultId) {
    state.activeProfileId = defaultId;
    selects.forEach(s => s.value = defaultId);
  } else {
    state.activeProfileId = "";
    selects.forEach(s => s.value = "");
  }
  updateFitControlsVisibility();
  updateProfileSelectHighlight();
}

// Auto-select a profile in fitProfileSelect and flash a highlight ring
function autoSelectFitProfile(profileId) {
  if (!profileId) return;
  const idStr = String(profileId);
  handleCompanyProfileSelectionChange(idStr);
  const sel = $("fitProfileSelect");
  const rmSel = $("rmCompanyProfileSelect");
  [sel, rmSel].forEach(s => {
    if (!s) return;
    s.classList.remove("profile-select--highlight");
    void s.offsetWidth;
    s.classList.add("profile-select--highlight");
    setTimeout(() => s.classList.remove("profile-select--highlight"), 1500);
  });
}

function updateProfileSelectHighlight() {
  const sel = $("fitProfileSelect");
  const rmSel = $("rmCompanyProfileSelect");
  const hasProfiles = state.companyProfiles && state.companyProfiles.length > 0;
  const isSelected = Boolean(state.activeProfileId);
  [sel, rmSel].forEach(s => {
    if (!s) return;
    if (hasProfiles && !isSelected) {
      s.classList.add("profile-select--attention");
    } else {
      s.classList.remove("profile-select--attention");
    }
  });
}

function updateFitControlsVisibility() {
  const on = fitActive();
  const controls = $("fitControls");
  const hint = $("fitHint");
  if (controls) controls.classList.toggle("hidden", !on);
  if (hint) {
    if (!state.companyProfiles || state.companyProfiles.length === 0) {
      hint.innerHTML = `<span style="color: #ea580c; font-weight: 500;">⚠️ You haven't created a company profile yet. Select <strong>＋ Add new profile...</strong> in the dropdown above to get started!</span>`;
    } else {
      hint.textContent = on
        ? "Quick fit shown on each tender · open a tender for an AI deep score (★)."
        : "Pick a company profile to see how well each tender fits.";
    }
  }
}

// `makeDefault` (the default) saves the choice as the account's default company profile, remembered
// across sessions: that is what picking a company in the filter bar means. The pickers inside other
// screens (bids, analysis, history, documents, answer bank) are views onto one profile, not a request to
// change the account default, so they pass { makeDefault: false }: the choice then lasts for this page
// view only. They used to rewrite the default every time, which is how "Civenta (Default)" kept
// coming back after a session (Round 27).
function handleCompanyProfileSelectionChange(val, { makeDefault = true } = {}) {
  if (val === "__add_new__") {
    const activeVal = state.activeProfileId || "";
    if ($("fitProfileSelect")) $("fitProfileSelect").value = activeVal;
    if ($("rmCompanyProfileSelect")) $("rmCompanyProfileSelect").value = activeVal;
    openCpModal();
    return;
  }
  const idStr = String(val || "");
  state.activeProfileId = idStr;
  state.profileChosenThisVisit = true; // from now on the page keeps this pick rather than the saved default
  if (makeDefault) {
    lsSet(LS_PROFILE, idStr);
    savePrefsToServer({ active_profile: idStr });
  }

  if (idStr && makeDefault) {
    state.defaultProfileId = idStr;

    // 1. Update is_default on local state.companyProfiles
    (state.companyProfiles || []).forEach(p => {
      p.is_default = (String(p.id) === idStr);
    });

    // 2. Persist to server database as default
    try {
      fetch(`/api/company-profiles/${idStr}/set-default`, { method: "POST" })
        .catch(err => console.error("Error setting default profile:", err));
    } catch (e) {
      console.error(e);
    }

    const prof = (state.companyProfiles || []).find(p => String(p.id) === idStr);
    const compName = (prof && prof.name) || "Company";

    // 3. Immediately update dropdown option labels and values across all selects synchronously
    const selects = [
      $("fitProfileSelect"),
      $("rmCompanyProfileSelect"),
      $("bidCompanyProfileSelect"),
      $("analyseCompanyProfileSelect")
    ].filter(Boolean);

    selects.forEach(s => {
      Array.from(s.options).forEach(opt => {
        if (!opt.value || opt.value === "__add_new__") return;
        const p = (state.companyProfiles || []).find(p => String(p.id) === String(opt.value));
        if (p) {
          opt.textContent = p.is_default ? `${p.name} (Default)` : p.name;
        }
      });
      s.value = idStr;
    });

    if (typeof syncAnalyseCompanyNameInput === "function") syncAnalyseCompanyNameInput();

    // 4. Update Documents filter selector in DOM immediately
    const docsFilter = $("userDocsCompanyFilter");
    if (docsFilter) {
      Array.from(docsFilter.options).forEach(opt => {
        if (!opt.value || opt.value === "all" || opt.value === "global") return;
        const p = (state.companyProfiles || []).find(p => String(p.id) === String(opt.value));
        if (p) {
          opt.textContent = p.is_default ? `${p.name} (Default)` : p.name;
        }
      });
      docsFilter.value = idStr;
      const isDocsOpen = $("userDocumentsModal") && !$("userDocumentsModal").classList.contains("hidden");
      if (isDocsOpen && typeof filterAndRenderUserDocuments === "function") {
        filterAndRenderUserDocuments();
      }
    }

    // 5. Update History filter selector in DOM immediately
    state.historyCompanyFilter = compName;
    const historyFilter = $("historyCompanyFilter");
    if (historyFilter) {
      Array.from(historyFilter.options).forEach(opt => {
        if (!opt.value || opt.value === "all" || opt.value === "__none__") return;
        const p = (state.companyProfiles || []).find(p => p.name === opt.value);
        if (p) {
          opt.textContent = p.is_default ? `${p.name} (Default)` : p.name;
        }
      });
      historyFilter.value = compName;
      const isHistoryOpen = $("historyModal") && !$("historyModal").classList.contains("hidden");
      if (isHistoryOpen && typeof renderHistoryList === "function") {
        renderHistoryList();
      }
    }

    // 6. Update Answer Bank filter immediately
    const abFilter = $("abProfileFilter");
    if (abFilter) abFilter.value = idStr;
    const abFld = $("abFldProfile");
    if (abFld) abFld.value = idStr;

    // 7. If Buyer or Supplier Intelligence modal is currently open on screen, refresh it
    const isBuyerOpen = $("buyerIntelligenceModal") && !$("buyerIntelligenceModal").classList.contains("hidden");
    if (isBuyerOpen && typeof refreshBuyerIntelligenceView === "function") {
      refreshBuyerIntelligenceView();
    }
    const isSupplierOpen = $("supplierIntelligenceModal") && !$("supplierIntelligenceModal").classList.contains("hidden");
    if (isSupplierOpen && typeof refreshSupplierIntelligenceView === "function") {
      refreshSupplierIntelligenceView();
    }

    // 8. Re-render Company Profiles cards list ONLY if company profiles modal is currently open
    const isCpOpen = $("cpModal") && !$("cpModal").classList.contains("hidden");
    if (isCpOpen && typeof renderCpProfilesList === "function") {
      renderCpProfilesList();
    }

    // 9. Show toast confirmation
    if (typeof cpShowToast === "function") {
      cpShowToast(`"${compName}" set as default company profile — applied everywhere`, "info");
    }
  } else {
    if ($("fitProfileSelect")) $("fitProfileSelect").value = idStr;
    if ($("rmCompanyProfileSelect")) $("rmCompanyProfileSelect").value = idStr;
    if ($("bidCompanyProfileSelect")) $("bidCompanyProfileSelect").value = idStr;
    if ($("analyseCompanyProfileSelect")) $("analyseCompanyProfileSelect").value = idStr;
    if (typeof syncAnalyseCompanyNameInput === "function") syncAnalyseCompanyNameInput();
  }

  // Reset fit-derived view state when profile changes
  state.fitCache = {};
  if (!fitActive()) {
    state.fitMin = null;
    if (state.sort === "fit_deep_desc") state.sort = null;
  }
  updateFitControlsVisibility();
  updateProfileSelectHighlight();
  renderRows();
  updateResultsTotal();
  updateFiltersPanelSummary();

  // A tender's details panel may already be open — refresh its fit score for
  // the newly selected profile instead of leaving the old score on screen.
  if (state.activeKey && window._detailRow) {
    refreshFitPanel(window._detailRow);
    if (fitActive()) loadDeepFit(window._detailRow, null);
  }
}

$("fitProfileSelect")?.addEventListener("change", (e) => handleCompanyProfileSelectionChange(e.target.value));
$("rmCompanyProfileSelect")?.addEventListener("change", (e) => handleCompanyProfileSelectionChange(e.target.value));

const FIT_STEPS = [null, 40, 60, 80];
const FIT_LABELS = ["All", "40+", "60+", "80+"];

const RM_FIT_VALS = [0, 50, 60, 70, 80, 90];
const RM_FIT_BADGES = ["All Scores", "50%+ Match", "60%+ Match", "70%+ Match", "80%+ Match", "90%+ Match"];

function updateRmFitSliderUI(valIdx) {
  const idx = Math.max(0, Math.min(5, parseInt(valIdx || 0, 10)));
  const slider = $("rmFitSlider");
  const badge = $("rmFitSliderValBadge");
  const ticks = document.querySelectorAll(".rm-tick");

  if (slider) {
    slider.value = idx;
    const pct = (idx / 5) * 100;
    slider.style.setProperty("--slider-pct", `${pct}%`);
  }
  if (badge) {
    badge.textContent = RM_FIT_BADGES[idx];
  }
  ticks.forEach(tick => {
    const step = parseInt(tick.dataset.step || "0", 10);
    tick.classList.toggle("active", step === idx);
  });

  const fitVal = RM_FIT_VALS[idx];
  state.fitMin = fitVal > 0 ? fitVal : null;
}

function initRmFitSlider() {
  const slider = $("rmFitSlider");
  if (!slider) return;

  updateRmFitSliderUI(slider.value || 0);

  slider.addEventListener("input", (e) => {
    updateRmFitSliderUI(e.target.value);
    if (typeof renderRows === "function") renderRows();
    if (typeof updateRightmoveResultsCount === "function") updateRightmoveResultsCount();
    if (typeof updateFiltersPanelSummary === "function") updateFiltersPanelSummary();
  });

  document.querySelectorAll(".rm-tick").forEach(tick => {
    tick.addEventListener("click", () => {
      const step = parseInt(tick.dataset.step || "0", 10);
      updateRmFitSliderUI(step);
      if (typeof renderRows === "function") renderRows();
      if (typeof updateRightmoveResultsCount === "function") updateRightmoveResultsCount();
      if (typeof updateFiltersPanelSummary === "function") updateFiltersPanelSummary();
    });
  });
}

function initFitThresholdSlider() {
  const slider = $("fitThresholdSlider");
  const valLabel = $("fitThresholdVal");
  if (!slider) return;

  slider.addEventListener("input", (e) => {
    const idx = parseInt(e.target.value, 10);
    state.fitMin = FIT_STEPS[idx];
    if (valLabel) {
      valLabel.textContent = FIT_LABELS[idx];
    }
    // Sync with Filter mode slider if active
    const fitVal = state.fitMin || 0;
    let rmIdx = 0;
    if (fitVal >= 90) rmIdx = 5;
    else if (fitVal >= 80) rmIdx = 4;
    else if (fitVal >= 70) rmIdx = 3;
    else if (fitVal >= 60) rmIdx = 2;
    else if (fitVal >= 50) rmIdx = 1;
    updateRmFitSliderUI(rmIdx);

    renderRows();
    updateResultsTotal();
    updateFiltersPanelSummary();
  });
}
initFitThresholdSlider();

$("btnSortFit")?.addEventListener("click", () => {
  if (!fitActive()) return;
  state.sort = state.sort === "fit_deep_desc" ? null : "fit_deep_desc";
  renderRows();
});

$("thFit")?.addEventListener("click", () => {
  if (!fitActive() || !state.rows.length) return;
  state.sort = state.sort === "fit_deep_desc" ? null : "fit_deep_desc";
  renderRows();
});

// initCollapsiblePanels sets up button listeners only — preferences are loaded
// inside loadCurrentUser() after the user identity is resolved, so that data
// from a previous account never bleeds into the current session.
initCollapsiblePanels();
// Load company profiles and pipeline in parallel with user identity resolution.
// loadCurrentUser() also fetches saved + recent searches from server after username is set.
Promise.all([loadCompanyProfiles(), loadPipeline(), loadCurrentUser()]).then(() => {
  renderRows();
  if (typeof maybeShowWelcomeDashboard === "function") {
    maybeShowWelcomeDashboard();
  }
  if (typeof maybeOpenBillingFromReturn === "function") {
    maybeOpenBillingFromReturn();
  }
});

// Load answer bank count for the badge silently on startup
fetch("/api/answer-bank").then(r => r.json()).then(d => {
  abState.items = d.items || [];
  abUpdateCountBadge();
}).catch(() => { });
renderRows();

// ── Bid Application Response Assistant ─────────────────────────────────────

let _bidRow = null;
let _lastProposal = null;

function openBidModal(row) {
  const rkey = rowKey(row);
  const existing = state.tasks.find(t => t.id === "proposal-" + rkey);
  if (existing) {
    viewTask(existing.id);
    return;
  }
  _bidRow = row;
  _lastProposal = null;
  _methodologyData = null;
  _activeMethodologyStyle = null;
  _activeVisualStyle = 'corporate';
  _ganttPhases = [];
  _ganttUnit = 'weeks';
  _ganttSvgStr = '';
  state.bidUploadedFiles = [];
  state.bidCompanyFiles = [];
  state.resolvedPlaceholders = {};

  $("bidModalTitle").textContent = "Bid Application Response Assistant";
  const subheader = $("bidModalSubheader");
  if (subheader) subheader.textContent = "All checked points below will be included to generate your bid response";
  const hint = $("bidModalHint");
  if (hint) hint.textContent = "Tender documents will be fetched automatically from the portal.";

  const btnRun = $("btnRunBidAssistant");
  if (btnRun) {
    btnRun.disabled = false;
    btnRun.textContent = "📝 Generate Bid Response";
    btnRun.classList.remove("hidden");
  }
  $("btnReRunBidAssistant")?.classList.add("hidden");
  // bidCompanyName removed — company name comes from selected profile
  const filesInput = $("bidTenderFiles");
  if (filesInput) filesInput.value = "";
  const bidTenderText = $("bidTenderText");
  if (bidTenderText) bidTenderText.value = "";
  const fileList = $("bidFileList");
  if (fileList) fileList.innerHTML = "";

  const companyFilesInput = $("bidCompanyFiles");
  if (companyFilesInput) companyFilesInput.value = "";
  const companyFileList = $("bidCompanyFileList");
  if (companyFileList) companyFileList.innerHTML = "";

  const profileSelect = $("bidCompanyProfileSelect");
  if (profileSelect && state.activeProfileId) {
    profileSelect.value = String(state.activeProfileId);
  }
  loadCompanyProfiles();
  
  // Ensure all steps start collapsed (no persisted expand state)
  collapseAllBidSteps();
  
  // Reload server preferences before loading document checklist and step check states
  loadPrefsFromServer().then(() => {
    loadBidStepCheckStates();
    loadBidUserDocsChecklist();
    loadBidWinningBids();
  });

  $("bidModalBody").innerHTML = renderBidModalPlaceholder();
  $("bidModal").classList.remove("hidden");

  // Restore saved proposal from DB if available
  fetch(`/api/proposals/latest?tender_key=${encodeURIComponent(rkey)}`)
    .then(r => r.json())
    .then(data => {
      if (data && data.ok && data.proposal && _bidRow && rowKey(_bidRow) === rkey) {
        _lastProposal = data.proposal;
        if (data.proposal.methodology) _methodologyData = data.proposal.methodology;
        if (data.proposal.gantt) {
          _ganttPhases = data.proposal.gantt.phases || [];
          _ganttUnit = data.proposal.gantt.unit || 'weeks';
        }
        showProposalResultInModal({ id: "proposal-" + rkey, row: row, proposal: data.proposal });
      }
    })
    .catch(err => console.warn("Could not load saved proposal:", err));
}

async function saveProposalToServer(proposalData, tenderKey) {
  if (!proposalData || !tenderKey) return;
  try {
    await fetch('/api/proposals/save', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ tender_key: tenderKey, proposal: proposalData })
    });
  } catch (e) {
    console.warn("Failed to save proposal to server:", e);
  }
}

function renderBidModalPlaceholder() {
  return `
    <div class="bid-modal-placeholder-card" style="padding: 24px; text-align: center; background: var(--surface-2, #f8fafc); border: 1px dashed var(--border, #cbd5e1); border-radius: 12px; margin-top: 12px;">
      <div style="font-size: 32px; margin-bottom: 8px;">📝</div>
      <div style="font-size: 12.5px; color: var(--muted, #64748b); max-width: 480px; margin: 0 auto; line-height: 1.5;">
        Click <strong>Generate Bid Response</strong> to compile the checklist and draft proposal covering letter.
      </div>
    </div>
  `;
}

