  _lastProposal = null;
  _methodologyData = null;
  _ganttPhases = [];
  _ganttUnit = 'weeks';
  _ganttSvgStr = '';
  _ganttTotalUnits = null;
  _ganttDurationStr = '';
  _ganttSubmissionDeadline = '';
