async function downloadClarificationsDoc() {
  if (!_bidRow || !_lastProposal?.clarifications) return;
  const title = _bidRow.title || "Unknown Tender";
  const authority = _bidRow.contracting_authority || "Unknown Authority";

  try {
    const res = await fetch("/api/download-clarifications", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: title,
        authority: authority,
        clarifications: _lastProposal.clarifications
      })
    });
    if (!res.ok) throw new Error("Docx creation failed");
    refreshCredits();
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    const sanitizedTitle = title.replace(/[^a-z0-9]/gi, '_').toLowerCase();
    a.download = `${sanitizedTitle}_clarifications.docx`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  } catch (err) {
    await showAlert("Failed to download DOCX: " + err.message);
  }
}

async function handleBidFileSelect(e) {
  const files = e.target.files;
  if (!files || !files.length) return;

  const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB

  for (let i = 0; i < files.length; i++) {
    const file = files[i];
    if (file.size > MAX_FILE_SIZE) {
      await showAlert(`File ${file.name} is too large. Max size is 5MB.`);
      continue;
    }

    const reader = new FileReader();
    reader.onload = function (evt) {
      const arrayBuffer = evt.target.result;
      let binary = "";
      const bytes = new Uint8Array(arrayBuffer);
      const len = bytes.byteLength;
      for (let j = 0; j < len; j++) {
        binary += String.fromCharCode(bytes[j]);
      }
      const base64 = btoa(binary);
      if (!state.bidUploadedFiles.some(f => f.filename === file.name)) {
        state.bidUploadedFiles.push({
          filename: file.name,
          content: base64
        });
        renderBidUploadedFiles();
      }
    };
    reader.readAsArrayBuffer(file);
  }
  e.target.value = "";
}

window.saveBidSupportingDocs = function() {
  try {
    lsSet("tf_bid_uploaded_files", JSON.stringify(state.bidUploadedFiles || []));
    const textVal = $("bidTenderText")?.value || "";
    lsSet("tf_bid_tender_text", textVal);
  } catch (err) {
    console.error("Error saving supporting docs:", err);
  }
};

window.loadBidSupportingDocs = function() {
  try {
    const savedFiles = lsGet("tf_bid_uploaded_files", null);
    if (savedFiles) {
      try {
        state.bidUploadedFiles = JSON.parse(savedFiles) || [];
      } catch {}
    }
    const savedText = lsGet("tf_bid_tender_text", null);
    const textarea = $("bidTenderText");
    if (textarea && savedText !== null && savedText !== undefined) {
      textarea.value = savedText;
    }
    renderBidUploadedFiles();
  } catch (err) {
    console.error("Error loading supporting docs:", err);
  }
};

function renderBidUploadedFiles() {
  const container = $("bidFileList");
  if (container) {
    container.innerHTML = "";
    (state.bidUploadedFiles || []).forEach((file, index) => {
      const chip = document.createElement("div");
      chip.className = "file-chip";
      chip.innerHTML = `${esc(file.filename)} <span class="remove-bid-file" data-index="${index}" style="margin-left: 6px; cursor: pointer; font-weight: bold; color: #b91c1c;">×</span>`;
      container.appendChild(chip);
    });
    container.querySelectorAll(".remove-bid-file").forEach(btn => {
      btn.addEventListener("click", (e) => {
        const index = parseInt(e.target.dataset.index);
        state.bidUploadedFiles.splice(index, 1);
        saveBidSupportingDocs();
        renderBidUploadedFiles();
      });
    });
  }
  saveBidSupportingDocs();
  const text = $("bidTenderText")?.value.trim();
  const hasFiles = state.bidUploadedFiles && state.bidUploadedFiles.length > 0;
  const chk4 = $("bidStepCheck4");
  if (chk4) {
    if (hasFiles || text) {
      chk4.disabled = false;
    } else {
      chk4.checked = false;
      chk4.disabled = true;
    }
  }
  if (typeof updateBidStepSummary === "function") updateBidStepSummary(4);
  if (typeof saveBidStepCheckStates === "function") saveBidStepCheckStates();
}

