function _setupDragAndDrop(labelSelector, inputId, processFilesFn) {
  const label = document.querySelector(labelSelector);
  const input = document.getElementById(inputId);
  if (!label || !input) return;

  ['dragenter', 'dragover', 'dragleave', 'drop'].forEach(eventName => {
    label.addEventListener(eventName, e => {
      e.preventDefault();
      e.stopPropagation();
    }, false);
  });

  ['dragenter', 'dragover'].forEach(eventName => {
    label.addEventListener(eventName, () => {
      label.classList.add('drag-over');
    }, false);
  });

  ['dragleave', 'drop'].forEach(eventName => {
    label.addEventListener(eventName, () => {
      label.classList.remove('drag-over');
    }, false);
  });

  label.addEventListener('drop', e => {
    const dt = e.dataTransfer;
    const files = dt.files;
    if (files && files.length) {
      processFilesFn({ target: { files: files } });
    }
  }, false);
}

// Initialize drag & drop for all upload zones
_setupDragAndDrop('label[for="tenderFiles"]', 'tenderFiles', handleFileSelect);
_setupDragAndDrop('label[for="bidTenderFiles"]', 'bidTenderFiles', handleBidFileSelect);
_setupDragAndDrop('label[for="bidCompanyFiles"]', 'bidCompanyFiles', handleBidCompanyDocUpload);
