async function cpSaveProfileAndNext() {
  const missing = cpValidateAll();
  if (missing.length > 0) {
    const banner = $("cpValBanner");
    const bannerText = $("cpValBannerText");
    if (banner) banner.classList.add("visible");
    if (bannerText) bannerText.textContent = "Please fill in: " + missing.join(", ");
    return;
  }

  const data = cpCollectData();
  if (!data.name) { await showAlert("Profile Name is required."); return; }
  if (!data.profile_text) { await showAlert("AI Context is required."); return; }

  const isDefaultChecked = document.getElementById("cpIsDefault") ? document.getElementById("cpIsDefault").checked : false;

  try {
    const body = {
      id: cpState.editId ? parseInt(cpState.editId) : null,
      name: data.name,
      profile_text: data.profile_text,
      meta_json: data.meta_json,
      is_default: isDefaultChecked,
    };
    const res = await fetch("/api/company-profiles", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    const result = await res.json();
    if (!res.ok) {
      throw new Error(result.error || "Save failed");
    }
    if (result.ok && result.id) {
      cpState.editId = result.id;
    }
    cpState.dirty = false;
    await loadCompanyProfiles();
    // Auto-select the saved profile in the fit bar dropdown and highlight it
    if (result.ok && result.id) {
      if (isDefaultChecked || result.is_default || !state.activeProfileId) {
        state.defaultProfileId = String(result.id);
        state.activeProfileId = String(result.id);
        lsSet(LS_PROFILE, String(result.id));
        state.historyCompanyFilter = data.name;
        if (typeof populateHistoryCompanyFilter === "function") populateHistoryCompanyFilter();
        const docsFilter = $("userDocsCompanyFilter");
        if (docsFilter) {
          docsFilter.value = String(result.id);
          if (typeof filterAndRenderUserDocuments === "function") filterAndRenderUserDocuments();
        }
        if (typeof populateFitProfileSelect === "function") populateFitProfileSelect();
        if (typeof populateCompanyProfileDropdown === "function") populateCompanyProfileDropdown();
        if (typeof abPopulateProfileFilterSelect === "function") abPopulateProfileFilterSelect();
        if (typeof abPopulateProfileSelect === "function") abPopulateProfileSelect(String(result.id));
        if (typeof swrClearPrefix === "function") {
          swrClearPrefix("buyer_feed");
          swrClearPrefix("buyer_radar");
        }
        if (typeof refreshBuyerIntelligenceView === "function") refreshBuyerIntelligenceView();
        if (typeof refreshSupplierIntelligenceView === "function") refreshSupplierIntelligenceView();
        autoSelectFitProfile(result.id); // only when it is becoming the default (see the other save handler)
      }
    }
    cpShowToast(isDefaultChecked ? "Profile saved and set as default — applied everywhere" : "Profile saved successfully", "success");

    // Return to list view
    cpShowListView();
  } catch (err) {
    await showAlert("Error saving profile: " + err.message);
  }
}

/* ── Document Issue & Expiry Date Helpers ── */
function formatDocDate(dStr) {
  if (!dStr) return "";
  try {
    const d = new Date(dStr + (dStr.includes("T") ? "" : "T00:00:00"));
    if (isNaN(d.getTime())) return dStr;
    return d.toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" });
  } catch {
    return dStr;
  }
}

function getExpiryBadgeHtml(expiryDateStr) {
  if (!expiryDateStr) return "";
  try {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const exp = new Date(expiryDateStr + (expiryDateStr.includes("T") ? "" : "T00:00:00"));
    if (isNaN(exp.getTime())) return "";

    const diffDays = Math.ceil((exp - today) / (1000 * 60 * 60 * 24));
    
    if (diffDays < 0) {
      const ago = Math.abs(diffDays);
      return `<span class="doc-expiry-badge doc-expiry-badge--expired" title="Expired ${ago} day(s) ago (${formatDocDate(expiryDateStr)})">🔴 Expired (${ago}d ago)</span>`;
    } else if (diffDays === 0) {
      return `<span class="doc-expiry-badge doc-expiry-badge--critical" title="Expires TODAY (${formatDocDate(expiryDateStr)})">🚨 Expires TODAY!</span>`;
    } else if (diffDays === 1) {
      return `<span class="doc-expiry-badge doc-expiry-badge--critical" title="Expires tomorrow (${formatDocDate(expiryDateStr)})">🚨 Expires Tomorrow (1d)</span>`;
    } else if (diffDays === 2) {
      return `<span class="doc-expiry-badge doc-expiry-badge--critical" title="Expires in 2 days (${formatDocDate(expiryDateStr)})">🚨 Expires in 2 days</span>`;
    } else if (diffDays === 3) {
      return `<span class="doc-expiry-badge doc-expiry-badge--critical" title="Expires in 3 days (${formatDocDate(expiryDateStr)})">🚨 Expires in 3 days</span>`;
    } else if (diffDays <= 7) {
      return `<span class="doc-expiry-badge doc-expiry-badge--urgent" title="Expires in ${diffDays} days (${formatDocDate(expiryDateStr)})">⚠️ Expires in ${diffDays}d</span>`;
    } else if (diffDays <= 15) {
      return `<span class="doc-expiry-badge doc-expiry-badge--warning" title="Expires in ${diffDays} days (${formatDocDate(expiryDateStr)})">⚠️ Expires in ${diffDays}d</span>`;
    } else if (diffDays <= 30) {
      return `<span class="doc-expiry-badge doc-expiry-badge--notice" title="Expires in ${diffDays} days (${formatDocDate(expiryDateStr)})">🟡 Expires in ${diffDays}d</span>`;
    } else {
      return `<span class="doc-expiry-badge doc-expiry-badge--valid" title="Document is valid (${formatDocDate(expiryDateStr)})">🟢 Valid</span>`;
    }
  } catch {
    return "";
  }
}

function renderDocExpiryAlertsBanner(documents, containerId = "userDocsAlertBanner") {
  const container = document.getElementById(containerId);
  if (!container) return;

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const alerts = [];

  (documents || []).forEach(doc => {
    if (!doc.expiry_date) return;
    try {
      const exp = new Date(doc.expiry_date + (doc.expiry_date.includes("T") ? "" : "T00:00:00"));
      if (isNaN(exp.getTime())) return;

      const diffDays = Math.ceil((exp - today) / (1000 * 60 * 60 * 24));
      
      if (diffDays < 0) {
        const ago = Math.abs(diffDays);
        alerts.push({
          level: "critical",
          icon: "🔴",
          doc,
          message: `Document <strong>"${esc(doc.filename)}"</strong> expired ${ago} day(s) ago (${formatDocDate(doc.expiry_date)}). Please update!`
        });
      } else if (diffDays === 0) {
        alerts.push({
          level: "critical",
          icon: "🚨",
          doc,
          message: `Urgent Alert: <strong>"${esc(doc.filename)}"</strong> expires <strong>TODAY</strong> (${formatDocDate(doc.expiry_date)})!`
        });
      } else if (diffDays === 1) {
        alerts.push({
          level: "critical",
          icon: "🚨",
          doc,
          message: `Urgent Alert: <strong>"${esc(doc.filename)}"</strong> expires <strong>tomorrow (1 day left)</strong> (${formatDocDate(doc.expiry_date)})!`
        });
      } else if (diffDays === 2 || diffDays === 3) {
        alerts.push({
          level: "critical",
          icon: "🚨",
          doc,
          message: `Critical Warning: <strong>"${esc(doc.filename)}"</strong> expires in <strong>${diffDays} days</strong> (${formatDocDate(doc.expiry_date)})!`
        });
      } else if (diffDays <= 7) {
        alerts.push({
          level: "urgent",
          icon: "⚠️",
          doc,
          message: `High Priority: <strong>"${esc(doc.filename)}"</strong> expires in <strong>${diffDays} days</strong> (${formatDocDate(doc.expiry_date)}).`
        });
      } else if (diffDays <= 15) {
        alerts.push({
          level: "warning",
          icon: "⚠️",
          doc,
          message: `Warning: <strong>"${esc(doc.filename)}"</strong> expires in <strong>${diffDays} days</strong> (${formatDocDate(doc.expiry_date)}).`
        });
      } else if (diffDays <= 30) {
        alerts.push({
          level: "notice",
          icon: "🟡",
          doc,
          message: `Notice: <strong>"${esc(doc.filename)}"</strong> expires in <strong>${diffDays} days</strong> (${formatDocDate(doc.expiry_date)}).`
        });
      }
    } catch (e) {}
  });

  if (alerts.length === 0) {
    container.innerHTML = "";
    container.classList.add("hidden");
    return;
  }

  const levelOrder = { critical: 1, urgent: 2, warning: 3, notice: 4 };
  alerts.sort((a, b) => levelOrder[a.level] - levelOrder[b.level]);

  const hasCritical = alerts.some(a => a.level === "critical");
  const hasUrgent = alerts.some(a => a.level === "urgent");
  const bannerClass = hasCritical ? "doc-alert-banner--critical" : hasUrgent ? "doc-alert-banner--urgent" : "doc-alert-banner--warning";

  container.className = `doc-alert-banner ${bannerClass}`;
  container.innerHTML = `
    <div class="doc-alert-header">
      <span class="doc-alert-title">🔔 Document Expiry Alerts (${alerts.length})</span>
      <button type="button" class="doc-alert-dismiss" onclick="this.closest('.doc-alert-banner').classList.add('hidden')">×</button>
    </div>
    <div class="doc-alert-list">
      ${alerts.map(a => `
        <div class="doc-alert-item doc-alert-item--${a.level}">
          <span class="doc-alert-icon">${a.icon}</span>
          <span class="doc-alert-text">${a.message}</span>
          <button type="button" class="btn-alert-edit-dates" data-id="${a.doc.id}" data-type="${a.doc.type}" data-profile="${a.doc.profile_id || ''}">📅 Update Dates</button>
        </div>
      `).join("")}
    </div>
  `;
  container.classList.remove("hidden");

  // Attach button listeners
  container.querySelectorAll(".btn-alert-edit-dates").forEach(btn => {
    btn.addEventListener("click", () => {
      const docId = btn.getAttribute("data-id");
      const docType = btn.getAttribute("data-type");
      const pId = btn.getAttribute("data-profile");
      const targetDoc = documents.find(d => String(d.id) === String(docId));
      if (targetDoc) {
        openDocDatesModal(targetDoc, docType, pId);
      }
    });
  });
}

async function openDocDatesModal(doc, type = 'profile', profileId = null) {
  const existingModal = document.getElementById("docDatesModal");
  if (existingModal) existingModal.remove();

  const modal = document.createElement("div");
  modal.id = "docDatesModal";
  modal.className = "modal-overlay";
  modal.style.zIndex = "10000";

  const targetProfileId = profileId || doc.profile_id || (typeof cpState !== "undefined" ? cpState.editId : null);

  modal.innerHTML = `
    <div class="modal-card" style="max-width: 420px; padding: 22px; border-radius: 12px; background: var(--surface, #fff); border: 1px solid var(--border, #cbd5e1); box-shadow: 0 20px 25px -5px rgba(0,0,0,0.1), 0 10px 10px -5px rgba(0,0,0,0.04);">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:14px;">
        <h3 style="margin:0; font-size:15px; font-weight:700; color:var(--text, #0f172a); display:flex; align-items:center; gap:6px;">
          <span>📅</span> Document Dates & Metadata
        </h3>
        <button type="button" class="btn-close-modal" style="background:none; border:none; cursor:pointer; font-size:20px; color:var(--muted, #64748b); padding:0 4px;">×</button>
      </div>
      <div style="font-size:12px; color:var(--muted, #64748b); margin-bottom:16px; padding:8px 12px; background:var(--surface-2, #f8fafc); border-radius:6px; word-break:break-all; border:1px solid var(--border, #e2e8f0);">
        📄 <strong>${esc(doc.filename)}</strong>
      </div>
      <form id="docDatesForm">
        <div style="margin-bottom: 14px;">
          <label style="display:block; font-size:12px; font-weight:600; color:var(--text, #334155); margin-bottom:5px;">Issue Date</label>
          <input type="date" id="docIssueDateInput" value="${doc.issue_date || ''}" style="width:100%; padding:8px 10px; border:1px solid var(--border, #cbd5e1); border-radius:6px; font-size:13px; box-sizing:border-box; background:var(--surface, #fff); color:var(--text, #0f172a);" />
        </div>
        <div style="margin-bottom: 18px;">
          <label style="display:block; font-size:12px; font-weight:600; color:var(--text, #334155); margin-bottom:5px;">Expiry Date</label>
          <input type="date" id="docExpiryDateInput" value="${doc.expiry_date || ''}" style="width:100%; padding:8px 10px; border:1px solid var(--border, #cbd5e1); border-radius:6px; font-size:13px; box-sizing:border-box; background:var(--surface, #fff); color:var(--text, #0f172a);" />
        </div>
        <div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
          <button type="button" class="btn-auto-detect" style="padding:6px 12px; border-radius:6px; border:1px solid #cbd5e1; background:#f8fafc; font-size:11.5px; font-weight:600; color:var(--primary, #2563eb); cursor:pointer;" title="Scan document text for issue & expiry dates">✨ Auto-Detect from File</button>
          <div style="display:flex; gap:8px;">
            <button type="button" class="btn-cancel" style="padding:7px 14px; border-radius:6px; border:1px solid var(--border, #cbd5e1); background:var(--surface-2, #f1f5f9); font-size:12.5px; font-weight:500; cursor:pointer;">Cancel</button>
            <button type="submit" class="btn-save" style="padding:7px 16px; border-radius:6px; border:none; background:linear-gradient(135deg, #2563eb, #1d4ed8); color:#fff; font-size:12.5px; font-weight:600; cursor:pointer; box-shadow:0 2px 4px rgba(37,99,235,0.2);">Save Dates</button>
          </div>
        </div>
      </form>
    </div>
  `;

  document.body.appendChild(modal);

  const closeModal = () => modal.remove();
  modal.querySelector(".btn-close-modal").addEventListener("click", closeModal);
  modal.querySelector(".btn-cancel").addEventListener("click", closeModal);

  modal.querySelector(".btn-auto-detect")?.addEventListener("click", async () => {
    const isProfileDoc = (type === 'profile' || doc.type === 'profile' || !!targetProfileId);
    const autoUrl = isProfileDoc
      ? `/api/company-profiles/${targetProfileId}/documents/${doc.id}/auto-dates`
      : `/api/user-documents/${doc.id}/auto-dates`;

    const autoBtn = modal.querySelector(".btn-auto-detect");
    if (autoBtn) autoBtn.disabled = true;
    try {
      const res = await fetch(autoUrl, { method: "POST" });
      const text = await res.text();
      let data;
      try {
        data = JSON.parse(text);
      } catch (e) {
        throw new Error("Server returned non-JSON response (" + res.status + "). Please ensure live server is running latest code.");
      }
      if (data.ok) {
        if (data.issue_date) modal.querySelector("#docIssueDateInput").value = data.issue_date;
        if (data.expiry_date) modal.querySelector("#docExpiryDateInput").value = data.expiry_date;
        if (!data.issue_date && !data.expiry_date) {
          await showAlert("No explicit issue or expiry dates found in document text.");
        } else {
          cpShowToast("Dates auto-extracted successfully!", "success");
        }
      } else {
        await showAlert("Auto-detect failed: " + data.error);
      }
    } catch (err) {
      await showAlert("Error auto-detecting dates: " + err.message);
    } finally {
      if (autoBtn) autoBtn.disabled = false;
    }
  });

  modal.querySelector("#docDatesForm").addEventListener("submit", async (e) => {
    e.preventDefault();
    const issue_date = modal.querySelector("#docIssueDateInput").value;
    const expiry_date = modal.querySelector("#docExpiryDateInput").value;

    const isProfileDoc = (type === 'profile' || doc.type === 'profile' || !!targetProfileId);
    const url = isProfileDoc
      ? `/api/company-profiles/${targetProfileId}/documents/${doc.id}/dates`
      : `/api/user-documents/${doc.id}/dates`;

    try {
      const res = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ issue_date, expiry_date })
      });
      const data = await res.json();
      if (data.ok) {
        doc.issue_date = issue_date;
        doc.expiry_date = expiry_date;
        closeModal();
        if (typeof loadUserDocuments === "function") loadUserDocuments();
        if (typeof loadProfileDocuments === "function") loadProfileDocuments();
        if (typeof loadBidUserDocsChecklist === "function") loadBidUserDocsChecklist();
      } else {
        await showAlert("Failed to update dates: " + data.error);
      }
    } catch (err) {
      await showAlert("Error updating dates: " + err.message);
    }
  });
}

async function loadProfileDocuments() {
  const list = $("cpDocsList");
  if (!list) return;
  if (!cpState.editId) {
    list.innerHTML = `<div class="cp-doc-empty">Please save the profile first to manage documents.</div>`;
    return;
  }

  list.innerHTML = `<div class="cp-doc-loading"><span class="fit-card__spinner" style="margin-right:8px; vertical-align: middle;"></span>Loading documents…</div>`;
  try {
    const res = await fetch(`/api/company-profiles/${cpState.editId}/documents`);
    if (!res.ok) throw new Error("Failed to load documents");
    const data = await res.json();
    if (data.ok) {
      renderProfileDocuments(data.documents || []);
    } else {
      list.innerHTML = `<div class="cp-doc-error">Error: ${esc(data.error)}</div>`;
    }
  } catch (err) {
    list.innerHTML = `<div class="cp-doc-error">Error: ${esc(err.message)}</div>`;
  }
}

function renderProfileDocuments(docs) {
  const list = $("cpDocsList");
  if (!list) return;
  renderDocExpiryAlertsBanner(docs, "cpDocsAlertBanner");
  if (docs.length === 0) {
    list.innerHTML = `<div class="cp-doc-empty">No documents uploaded yet. Add files to help tailor bid proposals. Once you upload files above, they will be displayed here.</div>`;
    return;
  }

  list.innerHTML = "";
  docs.forEach(doc => {
    const row = document.createElement("div");
    row.className = "cp-doc-row";

    const issueStr = doc.issue_date ? `<span>📅 Issued: ${formatDocDate(doc.issue_date)}</span>` : "";
    const expiryStr = doc.expiry_date ? `<span>⏳ Expires: ${formatDocDate(doc.expiry_date)}</span>` : "";
    const datesText = [issueStr, expiryStr].filter(Boolean).join("<span style='margin:0 4px; opacity:0.5;'>•</span>");
    const expiryBadge = getExpiryBadgeHtml(doc.expiry_date);
    const datesRowHtml = (datesText || expiryBadge)
      ? `<div class="doc-dates-row" style="font-size:11px; color:var(--text-secondary, #64748b); margin-top:2px;">${datesText} ${expiryBadge}</div>`
      : `<div class="doc-dates-row doc-dates-prompt" style="font-size:11px; color:#94a3b8; margin-top:2px; cursor:pointer;" title="Click calendar to set issue & expiry dates">📅 Click calendar to set dates</div>`;

    row.innerHTML = `
      <div class="cp-doc-row__icon">📄</div>
      <div class="cp-doc-row__info">
        <a class="cp-doc-row__name" href="/api/company-profiles/${cpState.editId}/documents/${doc.id}/download" target="_blank" title="Click to download">${esc(doc.filename)}</a>
        <div class="cp-doc-row__size">${cpFormatBytes(doc.file_size)}</div>
        ${datesRowHtml}
      </div>
      <div style="display: flex; align-items: center; gap: 4px;">
        <button type="button" class="btn-doc-action btn-doc-icon-btn btn-doc-edit-dates" title="Set Issue & Expiry Dates">📅</button>
        <a href="/api/company-profiles/${cpState.editId}/documents/${doc.id}/download" target="_blank" class="btn-doc-action btn-doc-icon-btn" title="Download Document">⬇️</a>
        <button type="button" class="btn-doc-action btn-doc-icon-btn cp-doc-row__delete" data-id="${doc.id}" title="Delete Document">🗑️</button>
      </div>
    `;

    row.querySelector(".btn-doc-edit-dates").addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      openDocDatesModal(doc, 'profile', cpState.editId);
    });

    row.querySelector(".doc-dates-prompt")?.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      openDocDatesModal(doc, 'profile', cpState.editId);
    });

    row.querySelector(".cp-doc-row__delete").addEventListener("click", () => {
      deleteProfileDocument(doc.id, doc.filename);
    });

    list.appendChild(row);
  });
}

async function deleteProfileDocument(docId, filename) {
  if (!await showConfirm(`Are you sure you want to delete the document "${filename}"?`)) return;
  try {
    const res = await fetch(`/api/company-profiles/${cpState.editId}/documents/${docId}`, {
      method: "DELETE"
    });
    if (!res.ok) throw new Error("Delete failed");
    const data = await res.json();
    if (data.ok) {
      cpShowToast("Document deleted", "info");
      loadProfileDocuments();
    } else {
      await showAlert("Delete failed: " + data.error);
    }
  } catch (err) {
    await showAlert("Error deleting document: " + err.message);
  }
}

async function uploadProfileDocument(file) {
  if (!cpState.editId) {
    await showAlert("Please save the profile first.");
    return;
  }

  if (file.size > 500 * 1024 * 1024) {
    await showAlert("File exceeds the 500MB size limit.");
    return;
  }

  const zone = $("cpUploadZone");
  const originalHtml = zone.innerHTML;

  zone.innerHTML = `
    <div class="cp-upload-loading">
      <div class="fit-card__spinner" style="margin-bottom:12px; width:28px; height:28px; border-width:3px;"></div>
      <div style="font-weight:600; font-size:13px;">Uploading ${esc(file.name)}…</div>
      <div style="color:var(--muted); font-size:11px; margin-top:4px;">Please do not close this window</div>
    </div>
  `;

  const formData = new FormData();
  formData.append("file", file);
  const issueInput = $("cpDocIssueDate") || $("userDocsIssueDate");
  const expiryInput = $("cpDocExpiryDate") || $("userDocsExpiryDate");
  if (issueInput && issueInput.value) {
    formData.append("issue_date", issueInput.value);
  }
  if (expiryInput && expiryInput.value) {
    formData.append("expiry_date", expiryInput.value);
  }

  try {
    const res = await fetch(`/api/company-profiles/${cpState.editId}/documents`, {
      method: "POST",
      body: formData
    });
    if (!res.ok) {
      const d = await res.json();
      throw new Error(d.error || "Upload failed");
    }
    const data = await res.json();
    if (data.ok) {
      cpShowToast("Document uploaded successfully", "success");
    } else {
      await showAlert("Upload failed: " + data.error);
    }
  } catch (err) {
    await showAlert("Upload error: " + err.message);
  } finally {
    zone.innerHTML = originalHtml;
    cpBindUploadTriggers();
    loadProfileDocuments();
  }
}

function cpBindUploadTriggers() {
  const zone = $("cpUploadZone");
  const input = $("cpFileInput");
  if (zone && input) {
    zone.onclick = (e) => {
      if (e.target !== input) input.click();
    };
    input.onchange = () => {
      if (input.files && input.files[0]) {
        uploadProfileDocument(input.files[0]);
      }
    };
  }
}

function cpFormatBytes(bytes) {
  if (bytes === 0) return "0 Bytes";
  const k = 1024;
  const sizes = ["Bytes", "KB", "MB", "GB"];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + " " + sizes[i];
}

// ── Legacy profile modal shims (backward compat for bidModal dropdown) ────
// Profile dropdown change — no separate company name field; name is derived at submission time

async function loadCompanyProfiles() {
  try {
    const res = await fetch("/api/company-profiles");
    if (!res.ok) throw new Error("Failed to load company profiles");
    const data = await res.json();
    if (data.ok) {
      state.companyProfiles = data.profiles || [];
      const defaultProf = state.companyProfiles.find(p => p.is_default) || state.companyProfiles[0];
      state.defaultProfileId = defaultProf ? String(defaultProf.id) : "";

      // Prioritize the designated default profile from database across the whole app
      if (defaultProf && defaultProf.is_default) {
        state.activeProfileId = String(defaultProf.id);
        lsSet(LS_PROFILE, state.activeProfileId);
      } else {
        const hasActive = state.companyProfiles.some(p => String(p.id) === String(state.activeProfileId));
        if (!hasActive && defaultProf) {
          state.activeProfileId = String(defaultProf.id);
          lsSet(LS_PROFILE, state.activeProfileId);
        }
      }

      populateCompanyProfileDropdown();
      if (typeof populateFitProfileSelect === "function") populateFitProfileSelect();
      if (typeof populateHistoryCompanyFilter === "function") populateHistoryCompanyFilter();
      updateFiltersPanelSummary();
    }
  } catch (err) {
    console.error(err);
  }
}

function populateCompanyProfileDropdown() {
  const selects = [
    $("bidCompanyProfileSelect"),
    $("analyseCompanyProfileSelect")
  ].filter(Boolean);

  if (selects.length === 0) return;

  const defaultProf = (state.companyProfiles || []).find(p => p.is_default) || (state.companyProfiles || [])[0];
  const defaultId = defaultProf ? String(defaultProf.id) : "";
  const savedProfile = state.activeProfileId || lsGet("tf_active_profile", "") || defaultId;

  selects.forEach(select => {
    // state.activeProfileId (savedProfile) is the single source of truth for
    // which company is active. A select's own leftover DOM value must never
    // win over it — otherwise this dropdown can silently disagree with (and,
    // for bidCompanyProfileSelect below, even overwrite) the company chosen
    // via the main "Target/Filter" dropdown.
    const currentVal = savedProfile;
    select.innerHTML = "";

    if (!state.companyProfiles || state.companyProfiles.length === 0) {
      select.innerHTML = '<option value="">-- No Profile Created --</option>';
    } else {
      state.companyProfiles.forEach(p => {
        const opt = document.createElement("option");
        opt.value = String(p.id);
        opt.textContent = p.is_default ? `${p.name} (Default)` : p.name;
        select.appendChild(opt);
      });
    }

    // Add "+ Add new profile..." option
    const addOpt = document.createElement("option");
    addOpt.value = "__add_new__";
    addOpt.textContent = "＋ Add new profile...";
    select.appendChild(addOpt);

    if (state.companyProfiles && state.companyProfiles.some(p => String(p.id) === String(currentVal))) {
      select.value = String(currentVal);
      if (select.id === "bidCompanyProfileSelect") state.activeProfileId = String(currentVal);
    } else if (defaultId) {
      select.value = String(defaultId);
      if (select.id === "bidCompanyProfileSelect") state.activeProfileId = String(defaultId);
    } else {
      select.value = "__add_new__";
    }
  });

  syncAnalyseCompanyNameInput();

  if (typeof updateBidStepSummary === "function") {
    updateBidStepSummary(1);
    updateBidStepSummary(2);
  }

  // Update fitbar button label based on whether profiles exist
  const fitBarBtn = $("btnFitBarProfile");
  if (fitBarBtn) {
    if (state.companyProfiles.length > 0) {
      fitBarBtn.textContent = "＋ Add New Profile";
      fitBarBtn.title = "Add another company profile";
    } else {
      fitBarBtn.textContent = "＋ Add Profile";
      fitBarBtn.title = "Add or edit company profile";
    }
  }
}

function syncAnalyseCompanyNameInput() {
  const select = $("analyseCompanyProfileSelect");
  const input = $("companyName");
  if (!select || !input) return;
  const selectedProfile = state.companyProfiles?.find(p => String(p.id) === String(select.value));
  if (selectedProfile) {
    input.value = selectedProfile.name;
  } else {
    input.value = "";
  }
}

