// History Modal UI & operations
function openHistoryModal() {
  if ($("historySearchInput")) $("historySearchInput").value = "";
  $("historyModal").classList.remove("hidden");
  state.historyFilterType = "all";

  const defProfile = (state.companyProfiles || []).find(p => p.is_default) ||
                     (state.companyProfiles || []).find(p => String(p.id) === String(state.defaultProfileId || state.activeProfileId));
  const defName = defProfile?.name?.trim() || "";
  state.historyCompanyFilter = defName || "all";
  if ($("historyCompanyFilter")) {
    $("historyCompanyFilter").value = state.historyCompanyFilter;
    $("historyCompanyFilter").classList.toggle("is-set", state.historyCompanyFilter !== "all");
  }
  updateHistoryFilterPillsActive();
  loadHistory();
}

function closeHistoryModal() {
  $("historyModal").classList.add("hidden");
}

function updateHistoryFilterPillsActive() {
  const pills = document.querySelectorAll("#historyFilterPills .pill");
  pills.forEach(pill => {
    if (pill.dataset.type === state.historyFilterType) {
      pill.classList.add("active");
    } else {
      pill.classList.remove("active");
    }
  });
}

function populateHistoryCompanyFilter() {
  const sel = $("historyCompanyFilter");
  if (!sel) return;

  const defProfile = (state.companyProfiles || []).find(p => p.is_default) ||
                     (state.companyProfiles || []).find(p => String(p.id) === String(state.defaultProfileId || state.activeProfileId));
  const defName = defProfile?.name?.trim() || "";

  const currentVal = state.historyCompanyFilter || defName || "all";
  const companies = new Set();
  (state.companyProfiles || []).forEach(p => {
    if (p.name && p.name.trim()) companies.add(p.name.trim());
  });
  (state.historyItems || []).forEach(item => {
    if (item.company && item.company.trim()) companies.add(item.company.trim());
  });

  const sorted = Array.from(companies).sort((a, b) => a.localeCompare(b));
  const hasNoCompany = (state.historyItems || []).some(item => !item.company || !item.company.trim());

  let html = '<option value="all">🏢 All Companies</option>';
  sorted.forEach(c => {
    const isDef = (defName && c.toLowerCase() === defName.toLowerCase());
    html += `<option value="${esc(c)}">${esc(c)}${isDef ? " (Default)" : ""}</option>`;
  });
  if (hasNoCompany) {
    html += '<option value="__none__">📋 General / No Company</option>';
  }

  sel.innerHTML = html;
  if (currentVal === "all" || currentVal === "__none__" || companies.has(currentVal)) {
    sel.value = currentVal;
    state.historyCompanyFilter = currentVal;
  } else if (defName && companies.has(defName)) {
    sel.value = defName;
    state.historyCompanyFilter = defName;
  } else {
    sel.value = "all";
    state.historyCompanyFilter = "all";
  }
  sel.classList.toggle("is-set", sel.value !== "all");
}

async function loadHistory() {
  const container = $("historyCardList");
  const emptyState = $("historyEmptyState");
  const countLabel = $("historyCountLabel");
  if (!container) return;

  container.innerHTML = `<div style="text-align: center; padding: 20px; color: var(--muted);">⏳ Loading history...</div>`;
  emptyState.style.display = "none";
  if (countLabel) countLabel.textContent = "";

  try {
    const res = await fetch("/api/analyses");
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Failed to load history");

    state.historyItems = data.analyses || [];
    populateHistoryCompanyFilter();
    renderHistoryList();
  } catch (err) {
    container.innerHTML = `<div style="text-align: center; color: #b91c1c; padding: 20px;">Error: ${esc(String(err))}</div>`;
  }
}

function renderHistoryList() {
  const container = $("historyCardList");
  const emptyState = $("historyEmptyState");
  const countLabel = $("historyCountLabel");
  if (!container) return;

  container.innerHTML = "";

  const searchQuery = ($("historySearchInput")?.value || "").toLowerCase().trim();

  let filtered = state.historyFilterType === "all"
    ? state.historyItems
    : state.historyItems.filter(item => item.type === state.historyFilterType);

  if (state.historyCompanyFilter && state.historyCompanyFilter !== "all") {
    if (state.historyCompanyFilter === "__none__") {
      filtered = filtered.filter(item => !item.company || !item.company.trim());
    } else {
      const target = state.historyCompanyFilter.toLowerCase().trim();
      filtered = filtered.filter(item => (item.company || "").toLowerCase().trim() === target);
    }
  }

  if (searchQuery) {
    filtered = filtered.filter(item => {
      const title = (item.tender_title || "").toLowerCase();
      const company = (item.company || "").toLowerCase();
      const type = (item.type || "").toLowerCase();
      return title.includes(searchQuery) || company.includes(searchQuery) || type.includes(searchQuery);
    });
  }

  if (countLabel) {
    countLabel.textContent = `${filtered.length} ${filtered.length === 1 ? 'item' : 'items'}`;
  }

  if (filtered.length === 0) {
    if (searchQuery || (state.historyCompanyFilter && state.historyCompanyFilter !== "all") || state.historyFilterType !== "all") {
      emptyState.innerHTML = `<span style="font-size: 36px; display: block; margin-bottom: 10px;">🔍</span>No matching history items found for the selected filters. Try changing company or search query!`;
    } else {
      emptyState.innerHTML = `<span style="font-size: 36px; display: block; margin-bottom: 10px;">📭</span>No generation history found. Try summarizing, analyzing, or preparing a bid for a tender first!`;
    }
    emptyState.style.display = "block";
    return;
  }

  emptyState.style.display = "none";

  let html = "";
  filtered.forEach(item => {
    const formattedDate = new Date(item.created_at).toLocaleString();
    let typeLabel = "";
    let iconClass = "";
    let badgeClass = "";
    let iconEmoji = "";

    if (item.type === "analysis") {
      typeLabel = "Analysis";
      iconClass = "icon--analysis";
      badgeClass = "badge--analysis";
      iconEmoji = "🔍";
    } else if (item.type === "summary") {
      typeLabel = "Summary";
      iconClass = "icon--summary";
      badgeClass = "badge--summary";
      iconEmoji = "📋";
    } else if (item.type === "proposal") {
      typeLabel = "Proposal";
      iconClass = "icon--proposal";
      badgeClass = "badge--proposal";
      iconEmoji = "📝";
    }

    let detailsText = "";
    if (item.type === "analysis" || item.type === "proposal") {
      detailsText = item.company ? `Company: <span class="history-card__company">${esc(item.company)}</span>` : "Default Profile";
    } else {
      detailsText = "General Summary";
    }

    html += `
      <div class="history-card" data-id="${item.id}" style="cursor: pointer;">
        <div class="history-card__icon-wrapper ${iconClass}">
          ${iconEmoji}
        </div>
        <div class="history-card__info">
          <h4 class="history-card__title" title="${esc(item.tender_title)}">${esc(item.tender_title)}</h4>
          <div class="history-card__meta">
            <span class="history-card__badge ${badgeClass}">${typeLabel}</span>
            <span>${detailsText}</span>
            <span class="history-card__date">📅 ${formattedDate}</span>
          </div>
        </div>
        <div class="history-card__actions">
          <button class="btn-history-view" data-id="${item.id}">View</button>
          <button class="btn-history-delete" data-id="${item.id}" title="Delete history record">🗑️</button>
        </div>
      </div>
    `;
  });

  container.innerHTML = html;

  // Bind click event to card itself (excluding buttons)
  container.querySelectorAll(".history-card").forEach(card => {
    card.addEventListener("click", (e) => {
      if (e.target.closest("button")) return;
      loadHistoryItem(card.dataset.id);
    });
  });

  // Bind view action
  container.querySelectorAll(".btn-history-view").forEach(btn => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      loadHistoryItem(btn.dataset.id);
    });
  });

  // Bind delete events
  container.querySelectorAll(".btn-history-delete").forEach(btn => {
    btn.addEventListener("click", async (e) => {
      e.stopPropagation();
      const id = btn.dataset.id;
      if (await showConfirm("Are you sure you want to delete this history record?")) {
        await deleteHistoryItem(id);
      }
    });
  });
}

async function loadHistoryItem(id) {
  try {
    closeHistoryModal();
    const res = await fetch(`/api/analyses/${id}`);
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Failed to retrieve history item");

    const d = data.analysis;
    if (d.type === "analysis") {
      _analyseRow = { title: d.tender_title, source: d.source, resource_id: d.resource_id };
      const rkey = rowKey(_analyseRow);
      const isRunning = state.tasks.some(t => t.id === "analysis-" + rkey && t.status === "running");
      _activeModalTaskId = isRunning ? "analysis-" + rkey : null;

      $("modalTitle").textContent = "Tender Clarification Analysis";
      $("btnRunAnalysis").classList.add("hidden");
      $("btnReRunSummary")?.classList.add("hidden");
      const btnReRunAnalyse = $("btnReRunAnalysis");
      if (btnReRunAnalyse) {
        btnReRunAnalyse.classList.remove("hidden");
        btnReRunAnalyse.disabled = isRunning;
        btnReRunAnalyse.textContent = isRunning ? "Running Clarification Analysis…" : "🔄 Re-run Clarification Analysis";
        btnReRunAnalyse.onclick = () => {
          reRunAnalysis(_analyseRow, d.company, d.files_json);
        };
      }
      $("analyseModal").classList.remove("hidden");
      state.lastAnalysis = d.analysis_json;
      state.questionnaireAnswers = {};
      $("modalBody").innerHTML = renderAnalysis(d.analysis_json, _analyseRow, d.files_json ? d.files_json.length : 0, d.files_json ? d.files_json.map(f => f.filename) : []);
      wireQuestionnaireButtons();
    } else if (d.type === "summary") {
      _analyseRow = { title: d.tender_title, source: d.source, resource_id: d.resource_id };
      const rkey = rowKey(_analyseRow);
      const isRunning = state.tasks.some(t => t.id === "analysis-" + rkey && t.status === "running");
      _activeModalTaskId = isRunning ? "analysis-" + rkey : null;

      $("modalTitle").textContent = "Tender Summary & Overview";
      $("docStatusRow").classList.add("hidden");
      $("btnRunAnalysis").classList.add("hidden");
      $("btnReRunAnalysis")?.classList.add("hidden");
      const btnReRunSum = $("btnReRunSummary");
      if (btnReRunSum) {
        btnReRunSum.classList.remove("hidden");
        btnReRunSum.disabled = isRunning;
        btnReRunSum.textContent = isRunning ? "Generating…" : "🔄 Re-run Summary";
        btnReRunSum.onclick = () => {
          openSummaryModal(_analyseRow, true);
        };
      }
      $("analyseModal").classList.remove("hidden");
      $("modalBody").innerHTML = renderSummary(d.analysis_json, _analyseRow);
    } else if (d.type === "proposal") {
      _bidRow = { title: d.tender_title, source: d.source, resource_id: d.resource_id, company: d.company };
      const rkey = rowKey(_bidRow);
      const isRunning = state.tasks.some(t => t.id === "proposal-" + rkey && t.status === "running");
      _activeModalTaskId = isRunning ? "proposal-" + rkey : null;

      // Auto-discover placeholders and init state
      state.resolvedPlaceholders = {};
      if (d.analysis_json?.bid_response?.all_placeholders) {
        d.analysis_json.bid_response.all_placeholders.forEach(ph => {
          state.resolvedPlaceholders[ph.placeholder_text] = "";
        });
      }
      _lastProposal = d.analysis_json;

      $("bidModalTitle").textContent = "Bid Application Response Assistant";
      $("btnRunBidAssistant")?.classList.add("hidden");
      const btnReRunBid = $("btnReRunBidAssistant");
      if (btnReRunBid) {
        btnReRunBid.classList.remove("hidden");
        btnReRunBid.disabled = isRunning;
        btnReRunBid.textContent = isRunning ? "Generating…" : "🔄 Re-run Bid Response";
        btnReRunBid.onclick = () => {
          runBidAssistant(true);
        };
      }
      $("bidModal").classList.remove("hidden");
      $("bidModalBody").innerHTML = renderProposal(d.analysis_json, _bidRow);
      wireBidResultButtons();
      wireTabNavigation();
    }
  } catch (err) {
    await showAlert("Error loading cached record: " + err.message);
  }
}

async function reRunAnalysis(row, company, files) {
  let activeRow = { ...row };
  try {
    const source = row.source;
    const rid = row.resource_id;
    if (source && rid) {
      const langParam = state.lang ? `?lang=${state.lang}` : "";
      const refreshUrl = `/api/tender/${encodeURIComponent(source)}/${encodeURIComponent(rid)}${langParam}${langParam ? '&' : '?'}refresh=1`;
      const detailsRes = await fetch(refreshUrl);
      if (detailsRes.ok) {
        const freshData = await detailsRes.json();
        activeRow = { ...row, ...freshData };
        _analyseRow = activeRow;
      }
    }
  } catch (e) {
    console.warn("Failed to fetch fresh tender details for analysis re-run:", e);
  }

  const taskId = "analysis-" + rowKey(activeRow);
  if (state.tasks.find(t => t.id === taskId && t.status === "running")) {
    await showAlert("An analysis is already running for this tender.");
    return;
  }

  state.tasks = state.tasks.filter(t => t.id !== taskId);

  const task = {
    id: taskId,
    type: "analysis",
    title: activeRow.title || "Custom Tender",
    row: { ...activeRow },
    company: company || "",
    files: files || [],
    status: "running",
    stage: 1,
    message: "Downloading and parsing tender documents...",
    elapsedSeconds: 0,
    startTime: Date.now(),
    analysis: null,
    docs_found: 0,
    docs_used: [],
    error: null
  };

  state.tasks.push(task);

  const panel = $("tasksPanel");
  if (panel) {
    state.tasksPanelUserClosed = false;
    panel.classList.remove("hidden");
    panel.classList.remove("tasks-panel--collapsed");
    const chevron = $("tasksPanelChevron");
    if (chevron) chevron.textContent = "▼";
  }
  updateTasksUI();

  const btnRun = $("btnRunAnalysis");
  if (btnRun) btnRun.classList.add("hidden");
  const btnReRun = $("btnReRunAnalysis");
  if (btnReRun) {
    btnReRun.classList.remove("hidden");
    btnReRun.disabled = true;
    btnReRun.textContent = "Analysing…";
  }

  _activeModalTaskId = task.id;

  // Show loading spinner in modalBody
  $("modalBody").innerHTML = `
    <div class="analysis-loading">
      <div class="shimmer-container">
        <div class="shimmer-line"></div>
        <div class="shimmer-line"></div>
        <div class="shimmer-line"></div>
        <div class="shimmer-line"></div>
      </div>
      <div style="margin-top: 15px; display: flex; flex-direction: column; align-items: center; gap: 6px;">
        <span id="analysisModalLoadingText" class="blink-cursor">⏳ Analysing tender...</span>
        <span id="analysisModalLoadingTimer" style="font-size: 12px; font-weight: 600; color: var(--primary);">Time elapsed: 0.0s</span>
      </div>
    </div>`;

  const messages = [
    "⏳ Downloading and parsing tender documents...",
    "🧠 Dissecting evaluation criteria and weightings...",
    "🔍 Scanning for mandatory vs. desirable requirements...",
    "📝 Compiling checklist items and signable forms...",
    "💡 Formulating strategic bidder advice...",
    "✨ Preparing full analysis report..."
  ];
  let msgIdx = 0;
  const rotateInterval = setInterval(() => {
    const textEl = $("analysisModalLoadingText");
    if (textEl) {
      msgIdx = (msgIdx + 1) % messages.length;
      textEl.textContent = messages[msgIdx];
    }
  }, 3500);

  const startTime = Date.now();
  const timerInterval = setInterval(() => {
    const elapsed = ((Date.now() - startTime) / 1000).toFixed(1);
    const timerEl = $("analysisModalLoadingTimer");
    if (timerEl) {
      timerEl.textContent = `Time elapsed: ${elapsed}s`;
    }
  }, 100);

  try {
    const langParam = state.lang ? `?lang=${state.lang}` : "";
    const res = await fetch(`/api/analyse${langParam}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ tender: activeRow, company: company || "", files: files || [], refresh: true }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Analysis failed");

    task.analysis = data.analysis;
    task.docs_found = data.docs_found || 0;
    task.docs_used = data.docs_used || [];
    task.elapsedSeconds = (Date.now() - task.startTime) / 1000;
    task.status = "completed";
    updateTasksUI();

    if (_activeModalTaskId === task.id) {
      state.lastAnalysis = data.analysis;
      state.questionnaireAnswers = {};
      $("modalBody").innerHTML = renderAnalysis(data.analysis, activeRow, data.docs_found || 0, data.docs_used || []);
      wireQuestionnaireButtons();
    }
  } catch (err) {
    task.elapsedSeconds = (Date.now() - task.startTime) / 1000;
    task.status = "failed";
    task.error = String(err);
    updateTasksUI();
    if (_activeModalTaskId === task.id) {
      $("modalBody").innerHTML = `<p style="color:#b91c1c;padding:10px 0">Error: ${esc(String(err))}</p>`;
    }
  } finally {
    clearInterval(rotateInterval);
    clearInterval(timerInterval);
    $("btnRunAnalysis")?.classList.add("hidden");
    if (_activeModalTaskId === task.id && btnReRun) {
      btnReRun.classList.remove("hidden");
      btnReRun.disabled = false;
      btnReRun.textContent = "🔄 Re-run Analysis";
    }
  }
}

async function deleteHistoryItem(id) {
  try {
    const res = await fetch(`/api/analyses/${id}`, { method: "DELETE" });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || "Failed to delete record");
    loadHistory();
  } catch (err) {
    await showAlert("Error deleting record: " + err.message);
  }
}

