  initProfileColorSection();
  loadSavedProfileColor();

  $("btnUserDocuments")?.addEventListener("click", openUserDocuments);
  $("userDocumentsClose")?.addEventListener("click", closeUserDocuments);
  $("userDocsCompanyFilter")?.addEventListener("change", (e) => {
    const val = e.target.value;
    if (val && val !== "all" && val !== "global") {
      handleCompanyProfileSelectionChange(val, { makeDefault: false });
    } else {
      filterAndRenderUserDocuments();
    }
  });

  $("adminUserSearch")?.addEventListener("input", e => {
    profileState.search = e.target.value;
    renderAdminUsers();
  });

  // Set up AI settings form events
  const providerSelect = $("aiProviderSelect");
  const keyGroup = $("aiKeyGroup");
  const modelGroup = $("aiModelGroup");
  const keyInput = $("aiApiKeyInput");
  const modelInput = $("aiModelInput");
  const defaultText = $("aiModelDefaultText");
  const saveBtn = $("btnSaveAiSettings");
  const toggleKeyBtn = $("btnToggleAiKey");

  const modelDefaults = {
    system: "",
    deepseek: "deepseek-chat",
    openai: "gpt-4o",
    gemini: "gemini-1.5-flash",
    claude: "claude-3-5-sonnet-20241022"
  };

  if (providerSelect) {
    providerSelect.addEventListener("change", () => {
      const val = providerSelect.value;
      if (val === "system") {
        keyGroup?.classList.add("hidden");
        modelGroup?.classList.add("hidden");
      } else {
        keyGroup?.classList.remove("hidden");
        modelGroup?.classList.remove("hidden");
        if (defaultText) defaultText.textContent = modelDefaults[val] || "";
        // If the model input is empty, fill it with default
        if (modelInput && (!modelInput.value.trim() || Object.values(modelDefaults).includes(modelInput.value.trim()))) {
          modelInput.value = modelDefaults[val] || "";
        }
      }
    });
  }

  if (toggleKeyBtn && keyInput) {
    toggleKeyBtn.addEventListener("click", () => {
      const isShowingLastFour = keyInput.dataset.showingUnmasked === "true";
      if (isShowingLastFour) {
        // Switch to all stars
        keyInput.dataset.showingUnmasked = "false";
        toggleKeyBtn.textContent = "👁️";
        if (keyInput.value && !keyInput.value.includes("*")) {
          keyInput.dataset.original = keyInput.value;
        }
        keyInput.value = keyInput.dataset.original ? maskAllStars(keyInput.dataset.original) : "";
      } else {
        // Switch to last 4 values and all preceding stars
        keyInput.dataset.showingUnmasked = "true";
        toggleKeyBtn.textContent = "🙈";
        if (keyInput.value && !keyInput.value.includes("*")) {
          keyInput.dataset.original = keyInput.value;
        }
        keyInput.value = keyInput.dataset.original ? maskApiKey(keyInput.dataset.original) : "";
      }
    });
  }

  function saveAiSettings() {
    const provider = providerSelect ? providerSelect.value : "system";
    let key = keyInput ? keyInput.value.trim() : "";
    const model = modelInput ? modelInput.value.trim() : "";

    if (key.includes("*")) {
      key = keyInput.dataset.original || "";
    }

    localStorage.setItem("ai_provider", provider);
    localStorage.setItem("ai_api_key", key);
    localStorage.setItem("ai_model", model);

    if (keyInput) {
      keyInput.value = key ? maskAllStars(key) : "";
      keyInput.dataset.original = key;
      keyInput.dataset.showingUnmasked = "false";
    }
    if (toggleKeyBtn) toggleKeyBtn.textContent = "👁️";
  }

  if (saveBtn) {
    saveBtn.addEventListener("click", saveAiSettings);
  }

  // ── Email Automation Settings ──
  const emailToggle = $("emailAlertsToggle");
  const newMatchToggle = $("newMatchAlertsToggle");
  const newMatchFreq = $("newMatchFrequency");
  const deadlineRemindersToggle = $("deadlineRemindersToggle");
  const deadlineThreshold = $("deadlineRemindersThreshold");
  const lowCreditToggle = $("lowCreditWarningToggle");
  const lowCreditThreshold = $("lowCreditThreshold");
  const fitScoreThreshold = $("fitScoreThreshold");
  const btnSaveEmailSettings = $("btnSaveEmailSettings");
  const btnTestEmail = $("btnTestEmailAlert");
  const emailStatus = $("emailAlertStatus");

  // Email settings are loaded lazily when the profile modal is opened (see setupProfileEmailSettings → btnProfile click)

  async function saveEmailSettings() {
    const emailAlertsToggle = $("emailAlertsToggle");
    const newMatchToggle = $("newMatchAlertsToggle");
    const newMatchFreq = $("newMatchFrequency");
    const deadlineRemindersToggle = $("deadlineRemindersToggle");
    const deadlineThreshold = $("deadlineRemindersThreshold");
    const lowCreditToggle = $("lowCreditWarningToggle");
    const lowCreditThreshold = $("lowCreditThreshold");
    const fitScoreThreshold = $("fitScoreThreshold");
    const txtEmail = $("txtProfileNotificationEmail");
    const selCompany = $("selProfileEmailCompany");

    const rawFit = fitScoreThreshold ? fitScoreThreshold.value : "70%";
    const fitScoreVal = parseInt(rawFit.replace("%", "").replace("+", "").trim(), 10) || 70;

    const payload = {
      automated_emails_enabled: emailAlertsToggle ? emailAlertsToggle.checked : true,
      email_alerts_enabled: emailAlertsToggle ? emailAlertsToggle.checked : true,
      best_fit_emails_enabled: newMatchToggle ? newMatchToggle.checked : true,
      new_match_alerts_enabled: newMatchToggle ? newMatchToggle.checked : true,
      email_frequency: newMatchFreq ? newMatchFreq.value : "Immediately",
      new_match_frequency: newMatchFreq ? newMatchFreq.value : "Immediately",
      deadline_reminders_enabled: deadlineRemindersToggle ? deadlineRemindersToggle.checked : true,
      deadline_reminders_threshold: deadlineThreshold ? deadlineThreshold.value : "7 days before",
      low_credit_warning_enabled: lowCreditToggle ? lowCreditToggle.checked : false,
      low_credit_threshold: lowCreditThreshold ? lowCreditThreshold.value : "Below 50 credits",
      min_fit_score: fitScoreVal,
      fit_score_threshold: `${fitScoreVal}%`,
      notification_email: txtEmail ? (txtEmail.value || "").trim() : "",
      selected_profile_id: selCompany ? selCompany.value : ""
    };

    const res = await fetch("/api/email-settings", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    const data = await res.json();
    if (!data.ok) {
      throw new Error(data.error || "Failed to save email settings");
    }
    return data;
  }

  if (btnSaveEmailSettings) {
    btnSaveEmailSettings.addEventListener("click", () => {
      saveEmailSettings()
        .then(() => cpShowToast("Email settings saved successfully!", "success"))
        .catch(err => cpShowToast("Error saving email settings: " + err.message, "error"));
    });
  }

  const btnSaveGlobal = $("btnSaveProfileGlobal");
  if (btnSaveGlobal) {
    btnSaveGlobal.addEventListener("click", async () => {
      btnSaveGlobal.disabled = true;
      btnSaveGlobal.classList.remove("profile-btn-save--lit", "profile-btn-saved");
      btnSaveGlobal.innerHTML = `
        <svg class="spin-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
          <circle cx="12" cy="12" r="10" stroke-opacity="0.25" stroke="currentColor" stroke-width="3"></circle>
          <path d="M12 2 a10 10 0 0 1 10 10" stroke="currentColor" stroke-width="3"></path>
        </svg>
        Saving...`;
      try {
        saveProfileColor();
        saveAiSettings();
        await saveEmailSettings();
        saveProfileCountries();

        // If user typed an email in the Add Email box, auto-submit it
        const recipientInput = document.getElementById("txtAddRecipientEmail");
        const pendingEmail = (recipientInput?.value || "").trim().toLowerCase();
        if (pendingEmail && pendingEmail.includes("@") && pendingEmail.includes(".")) {
          await addNotificationRecipient();
        }

        cpShowToast("Profile settings saved successfully!", "success");

        captureInitialProfileState();

        btnSaveGlobal.disabled = true;
        btnSaveGlobal.classList.remove("profile-btn-save--lit");
        btnSaveGlobal.classList.add("profile-btn-saved");
        btnSaveGlobal.innerHTML = `
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
            <polyline points="20 6 9 17 4 12"></polyline>
          </svg>
          Profile Saved`;
      } catch (err) {
        cpShowToast("Error saving profile: " + err.message, "error");
        btnSaveGlobal.disabled = false;
        btnSaveGlobal.classList.add("profile-btn-save--lit");
        btnSaveGlobal.innerHTML = `
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
            <path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"></path>
            <polyline points="17 21 17 13 7 13 7 21"></polyline>
            <polyline points="7 3 7 8 15 8"></polyline>
          </svg>
          Save Profile`;
      }
    });
  }

  if (emailToggle) {
    emailToggle.addEventListener("change", saveEmailSettings);
  }

  if (btnTestEmail && emailStatus) {
    btnTestEmail.addEventListener("click", () => {
      btnTestEmail.disabled = true;
      btnTestEmail.textContent = "Sending...";
      emailStatus.style.display = "none";
      fetch("/api/email-notifications/test", { method: "POST" })
        .then(r => r.json())
        .then(data => {
          if (data.ok) {
            emailStatus.textContent = "✅ Check complete! Any qualifying tenders have been emailed.";
            emailStatus.style.color = "var(--success-text, #16a34a)";
          } else {
            emailStatus.textContent = `❌ Error: ${data.error || "Unknown error"}`;
            emailStatus.style.color = "var(--critical-text, #dc2626)";
          }
          emailStatus.style.display = "block";
        })
        .catch(() => {
          emailStatus.textContent = "❌ Network error sending test email.";
          emailStatus.style.color = "var(--critical-text, #dc2626)";
          emailStatus.style.display = "block";
        })
        .finally(() => {
          btnTestEmail.disabled = false;
          btnTestEmail.textContent = "🧪 Send Test Email Now";
        });
    });
  }

  // Init Supplier Intelligence & Buyer Intelligence events
  initSupplierIntelligenceEvents();
  initBuyerIntelligenceEvents();

  // Handle escape key
  document.addEventListener("keydown", e => {
    if (e.key === "Escape") {
      if (!$("supplierIntelligenceModal")?.classList.contains("hidden")) {
        closeSupplierIntelligenceModal();
      }
      if (!$("buyerIntelligenceModal")?.classList.contains("hidden")) {
        closeBuyerIntelligenceModal();
      }
      if (!$("buyerProfileDrawerModal")?.classList.contains("hidden")) {
        closeBuyerProfileDrawer();
      }
      if (!$("pricingModal")?.classList.contains("hidden")) {
        closePricingModal();
      }
      if (!$("profileModal")?.classList.contains("hidden")) {
        closeProfile();
      }
      if (!$("userDocumentsModal")?.classList.contains("hidden")) {
        closeUserDocuments();
      }
      if (!$("docPreviewModal")?.classList.contains("hidden")) {
        closeDocPreviewModal();
      }
    }
  });

