// Distance filters show miles in the UI, but every geo query param/column on the backend
// (radius_km, distance_km, geo_radius_clause, etc.) stays in km — converting only at the
// display/input edges avoids touching any server-side geo logic.
const KM_PER_MILE = 1.609344;
function milesToKm(mi) { return Math.round(mi * KM_PER_MILE * 10) / 10; }
function kmToMiles(km) { return Math.round(km / KM_PER_MILE); }
window.milesToKm = milesToKm;
window.kmToMiles = kmToMiles;

// Shared "use my location" handler for the Buyer/Supplier/Planning distance filters
// (planning.js calls this too — it loads after app.js, so this top-level function is
// already on window by the time it runs).
//
// Once a site's geolocation permission is set to "denied" in the browser, calling
// getCurrentPosition() again never re-shows the native prompt — it just fails immediately
// with code 1, which reads to users as "it never even asked me". We check
// navigator.permissions first so we can say plainly that the browser has this site blocked
// and how to unblock it, instead of implying the prompt just appeared and got declined.
// The button stays enabled either way, so clicking it again after fixing the browser
// setting re-checks permission state fresh and retries.
function tfRequestGpsLocation(btn, statusEl, onSuccess) {
  if (!navigator.geolocation) {
    window.showToast?.("Geolocation is not supported by your browser", "warning");
    return;
  }

  // code 1 (PERMISSION_DENIED) means two different things and needs two different messages:
  // the SITE's own permission is blocked in the browser (permissions.query says "denied" —
  // fixed via the browser's site settings), or the site permission is fine but the OS itself
  // is blocking location for the browser (Windows: Settings > Privacy & security > Location) —
  // telling someone to check browser site settings that are already "Allowed" (as Chrome's own
  // panel can show) just sends them looking in the wrong place.
  const siteBlockedMsg = "Location is blocked for this site in your browser. Click the location or lock icon in the address bar, allow access, then click this button again — or pick a preset below.";
  const osBlockedMsg = "This site is allowed to use your location, but the request still failed — that usually means location is off at the operating system level. On Windows: Settings → Privacy & security → Location, turn it on, and make sure your browser is allowed there. Then click this button again — or pick a preset below.";
  const originalHtml = btn.innerHTML;
  const restore = () => { btn.disabled = false; btn.innerHTML = originalHtml; };
  const showMessage = (msg) => {
    if (statusEl) statusEl.innerHTML = `<span style="color:#d97706;">⚠️ ${msg}</span>`;
    window.showToast?.(msg, "warning");
  };

  const runRequest = (siteLevelDenied) => {
    btn.disabled = true;
    // This button is a fixed 32x32 icon button (.btn--icon) with no room for a text label —
    // "Locating..." text here doesn't make it grow, it just overflows past the button's own
    // edge and gets clipped at the popover boundary. The status line below already says
    // "Requesting GPS permission..." in words, so the button only needs the spinner itself.
    btn.innerHTML = `<span style="display:inline-block; animation:spin 1s linear infinite;">⏳</span>`;
    if (statusEl) statusEl.innerHTML = `<span style="color:var(--primary,#2563eb);">📡 Requesting GPS permission...</span>`;

    // On some Windows/Chrome setups, enableHighAccuracy's GPS-chip code path never calls back
    // at all — not even after the given timeout — leaving the button stuck on "Locating..."
    // indefinitely. Wi-Fi/IP positioning (enableHighAccuracy: false) doesn't hit that path and
    // is the right choice for a desktop distance filter anyway (city-level accuracy is plenty).
    // The watchdog below is a second layer of protection in case the browser ignores its own
    // timeout option too.
    let settled = false;
    const watchdog = setTimeout(() => {
      if (settled) return;
      settled = true;
      restore();
      showMessage("GPS request timed out. Please select a city preset.");
    }, 12000);

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        if (settled) return;
        settled = true;
        clearTimeout(watchdog);
        restore();
        onSuccess(pos);
      },
      (err) => {
        if (settled) return;
        settled = true;
        clearTimeout(watchdog);
        restore();
        console.warn("Geolocation error:", err);
        if (err.code === 1) { showMessage(siteLevelDenied ? siteBlockedMsg : osBlockedMsg); return; }
        let msg = "Could not get GPS location.";
        if (err.code === 2) msg = "Position unavailable. Please select a city preset.";
        else if (err.code === 3) msg = "GPS request timed out. Using selected city preset.";
        showMessage(msg);
      },
      { timeout: 10000, enableHighAccuracy: false, maximumAge: 60000 }
    );
  };

  if (navigator.permissions?.query) {
    navigator.permissions.query({ name: "geolocation" }).then((status) => {
      if (status.state === "denied") { showMessage(siteBlockedMsg); return; }
      runRequest(false);
    }).catch(() => runRequest(false));
  } else {
    runRequest(false);
  }
}

// Map / proximity state (mirrors the buyer equivalents at _buyerFilterState etc.)
let _activeSupplierTab = "list"; // "list" | "map"
